    ('ru', 'Mireraband', 'defeat_message', 'Как я и думал, %w, твои умения мне не ровня!'),
    ('ru', 'Fie', 'defeat_message', 'Тебе следовало знать, что моему %X ты не ровня'),
    ('ru', 'Glynyc', 'defeat_message', 'Ха-ха, тебе бы вернуться в класс Мирерабанда.'),
    ('ru', 'Guth', 'defeat_message', 'В ВВС мы таких, как ты, живьём ели! Иди-ка подтяни своё мастерство, дружок!'),
    ('ru', 'Un?ith', 'defeat_message', 'Твоей силы духа недостаёт. Поразмысли над этой неудачей — быть может, однажды ты одолеешь меня.'),
    ('ru', 'Adwares', 'defeat_message', 'Ха! Тебе, щенок, ещё тренироваться и тренироваться!'),
    ('ru', 'Gerrard', 'defeat_message', 'Как я и думал.'),
    ('ru', 'Ceiloth', 'defeat_message', 'Ты крепнешь, но пока не настолько.'),
