    ('ru', 'Gadriel the Elven Ranger', 'defeat_message', 'Не забывай, что эльфы бессмертны. Смертным вряд ли когда-нибудь одолеть дивный народ.'),
    ('ru', 'Adoawyr', 'defeat_message', 'Ха-ха, я даже меч поднять не смог — и всё равно победил!'),
    ('ru', 'Yoresh', 'defeat_message', 'В следующий раз берегись моего касания!')
  ) AS source
  JOIN training_master ON training_master.master_name = source.column2;

