DELETE FROM catalog_translation WHERE entity_type = 'taunt';

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'taunt', taunt.taunt_id, 'taunt_text', source.column1, source.column3
  FROM (VALUES
    ('ko', '`5"`6Just wait for my revenge, `4%W`6. It will be swift!`5" %w declares.', '`5"`6반드시 갚아주마, `4%W`6. 그것도 아주 빠르게!`5" %w가 선언한다.'),
    ('ko', '`5"`6I''m really going to enjoy this new `4%x`6 that %w`6 had,`5" exclaimed %W.', '`5"`6%w`6가 갖고 있던 이 새 `4%x`6를 아주 잘 쓰겠어,`5" %W가 외쳤다.'),
    ('ko', '`5"`6Aah, so `bthat''s`b what `4%X`6 is for!`5" exclaimed %W', '`5"`6아아, `4%X`6는 `b이럴 때`b 쓰는 것이었군!`5" %W가 외쳤다'),
    ('ko', '`5"`6Oh man!  I didn''t think you had it in you, `5%W`6,`5" %w exclaims.', '`5"`6이런! 네게 그런 게 있는 줄은 몰랐다, `5%W`6,`5" %w가 외친다.'),
    ('ko', '`5%W was over heard saying, "`6%p `4%x`6 was no match for my `4%X`6!`5"', '`5%W가 이렇게 말하는 것이 들렸다, "`6%p `4%x`6 따위는 내 `4%X`6의 상대가 아니었지!`5"'),
    ('ko', '`5"`6You know, you really shouldn''t have a `4%x`6 unless you know how to use it,`5" suggested %W.', '`5"`6쓸 줄도 모르면서 `4%x`6를 들고 다니면 못써,`5" %W가 충고했다.'),
    ('ko', '`5"`6`bARRRGGGGGGG`b!!`5" %w screams in frustration.', '`5"`6`b으아아아악`b!!`5" %w가 분해서 비명을 지른다.'),
    ('ko', '`5"`6How could I be so feeble?`5" %w laments.', '`5"`6어찌 이리도 나약할 수 있단 말인가?`5" %w가 한탄한다.'),
    ('ko', '`5"`6I must not be as sturdy as I thought...!`5" %w concedes.', '`5"`6내가 생각만큼 튼튼하지는 않았나 보군...!`5" %w가 인정한다.'),
    ('ko', '`5"`6Watch your back, `4%W`6 I am coming for you!`5" %w warns.', '`5"`6등 뒤를 조심해라, `4%W`6. 내가 찾아가마!`5" %w가 경고한다.'),
    ('ko', '`5"`6This both sucks and blows!`5" wails %w.', '`5"`6이건 최악에 최악이다!`5" %w가 울부짖는다.'),
    ('ko', '`5"`6I see London, I see France, I see `4%w''s`6, underpants!`5" reveals %W.', '`5"`6런던도 보이고 프랑스도 보이고, `4%w의`6 속옷도 보인다!`5" %W가 폭로한다.'),
    ('ko', '`5"`6The Healer''s Hut can''t help you now, `4%w`6!,`5" chides %W.', '`5"`6이제는 치유사의 오두막도 너를 구하지 못한다, `4%w`6!,`5" %W가 나무란다.'),
    ('ko', '`5%W smiles.  "`6You are too slow.  You are too weak.`5"', '`5%W가 미소 짓는다. "`6너는 너무 느리다. 너는 너무 약하다.`5"'),
    ('ko', '`5%w bangs %p head against a stone..."`6Stupid, stupid, stupid!`5" %o was heard to say.', '`5%w가 %p 머리를 돌에 찧는다..."`6멍청이, 멍청이, 멍청이!`5" %o가 말하는 것이 들렸다.'),
    ('ko', '`5"`6My ego can''t take much more of this bruising!`5" exclaims %w.', '`5"`6내 자존심이 이 이상 얻어맞는 걸 견디지 못하겠다!`5" %w가 외친다.'),
    ('ko', '`5"`6Why didn''t I become a successful doctor like my father suggested?`5" wonders %w aloud.', '`5"`6아버지 말씀대로 훌륭한 의사가 될 걸 그랬나?`5" %w가 소리 내어 되뇐다.'),
