    ('ja', '`5"`6I''m really going to enjoy this new `4%x`6 that %w`6 had,`5" exclaimed %W.', '`5"`6%w`6が持っていたこの新しい`4%x`6、存分に使わせてもらう、`5" %Wが叫んだ。'),
    ('ja', '`5"`6Aah, so `bthat''s`b what `4%X`6 is for!`5" exclaimed %W', '`5"`6ああ、`4%X`6は`bそのため`bにあったのか！`5" %Wが叫んだ'),
    ('ja', '`5"`6Oh man!  I didn''t think you had it in you, `5%W`6,`5" %w exclaims.', '`5"`6なんと！ お前にそんな力があるとは思わなかった、`5%W`6、`5" %wが叫ぶ。'),
