DELETE FROM catalog_translation
 WHERE entity_type = 'creature'
   AND field_code IN ('victory_message', 'defeat_message')
   AND locale_code = 'ko';

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'creature', creature.creature_id, 'victory_message', 'ko', source.column2
  FROM (VALUES
    ('"I vant to suk your blooood!"', '"네 피이이를 빨아먹겠다!"'),
    ('"Oooga Booga," indeed.', '"우가 부가"라니, 과연.'),
    ('A cold shiver goes down your spine.  You would rather be with Violet', '등골이 서늘해진다. 차라리 바이올렛과 있는 편이 낫겠다'),
    ('A unicorn is a thing of beauty, even in death', '유니콘은 죽어서도 아름답다'),
    ('A well-aimed strike grounds the flying dragon and his rider', '정확한 일격이 나는 용과 그 기수를 땅에 떨어뜨린다'),
    ('After an astronomical battle Ursus Minor is the one seeing stars', '천문학적인 싸움 끝에 별을 보는 쪽은 작은곰이었다'),
    ('After you lop him in half, you realize he''s not so big.', '반으로 갈라 놓고 보니 그리 크지도 않다.'),
    ('Ah Ha! A toothpick!', '아하! 이쑤시개로군!'),
    ('All he could say was "Shhh, you are scaring the dragons!"', '그가 남긴 말은 "쉿, 용들이 놀라잖아!"뿐이었다'),
    ('All she ever did was nag...nag...nag...', '그녀가 한 일이라곤 잔소리...잔소리...잔소리뿐이었다'),
    ('All these squirrels are nuts.', '이 다람쥐들은 죄다 제정신이 아니다.'),
    ('Another evil cat sent to hell C.O.D.', '사악한 고양이 한 마리를 착불로 지옥에 부쳤다.'),
    ('Arrrrrr! indeed.', '아아아! 과연 그렇군.'),
    ('As he dies, he curses you and tells you that you will never defeat the dragon.', '그는 죽어가며 너를 저주하고, 결코 용을 이기지 못할 것이라 말한다.'),
    ('As you recover from the fight, the Spectre melts away into the shadows.', '네가 숨을 고르는 사이 망령은 그림자 속으로 녹아든다.'),
    ('As you stare at his smoking corpse, you marvel at the ineffectiveness of flaming wingnuts.', '연기 나는 시체를 보며 불타는 나비너트가 얼마나 쓸모없었는지 감탄한다.'),
    ('Aww, now look, you broke its heart!', '저런, 이것 봐, 심장을 부숴 놓았잖아!'),
    ('Best way to get rid of the coffin is Robitussin.', '관을 없애는 최선책은 기침약이다.'),
    ('Boy, thats a face not even a mother could love.', '이런, 어머니조차 사랑하지 못할 얼굴이군.'),
    ('Butter?  What kind of a name is Butter?', '버터? 대체 무슨 이름이 버터야?'),
    ('Chopped him down to size...', '크기에 맞게 베어 냈다...'),
    ('Crikey!  That thing could have killed you!', '이런! 하마터면 저것에게 죽을 뻔했다!'),
    ('D00d U pwned that guy!', '야, 너 저 녀석 제대로 발랐다!'),
    ('Death to lies!  Death to Ulysses Wolfgang', '거짓에 죽음을! 율리시스 볼프강에게 죽음을'),
    ('Defeated, the Mud Man dries up in the warm sun.', '패배한 진흙 인간은 따뜻한 볕에 말라붙는다.'),
    ('Do you know how to stop a charging buffalo?  Take away his credit card!', '돌진하는 들소를 멈추는 법을 아나? 신용카드를 빼앗으면 된다!'),
    ('Dragon.. Check. Green... Check.  Huge.. Nope.', '용.. 확인. 초록... 확인. 거대함.. 아니군.'),
    ('Drat!  He took your memory before you killed him.  Who are you anyway?', '이런! 죽이기 전에 그가 네 기억을 가져갔다. 그런데 너는 누구지?'),
    ('Each one''s breath was worst than the last', '하나하나 숨결이 앞선 것보다 더 지독했다'),
    ('Even the cute fuzzy kittens are evil in this place.', '이곳에서는 귀엽고 복슬복슬한 새끼 고양이조차 사악하다.'),
    ('Everybody wondered what happened to him.', '다들 그가 어떻게 되었는지 궁금해했다.'),
    ('Eythgim seems to be waging a personal war with you', '에이스김은 너와 사적인 전쟁을 벌이는 듯하다'),
    ('Fantasize, fantasize about Burly ...Eeeh, Eeeh, Eeeh!', '건장한 사내를 상상하고 또 상상하고... 에헴, 에헴, 에헴!'),
    ('Finally he is at peace.', '마침내 그는 안식을 얻었다.'),
    ('Finally! Peace in the night!', '드디어! 밤에 평화가 찾아왔다!'),
    ('Finally, I got my chance to kill him', '드디어 그를 죽일 기회를 잡았다'),
    ('For being the Devil, he really wasn''t so hot.', '악마치고는 별로 대단하지 않았다.'),
    ('For one moment you thought THIS was the Green Dragon, but alas not.', '한순간 이것이 초록 용인 줄 알았으나, 아쉽게도 아니었다.'),
    ('Funny.. I didn''t see any water around here..', '이상하군.. 이 근처에 물이라곤 없었는데..'),
    ('Fuzzie Wuzzie wasn''t very fuzzie, was he?', '퍼지 워지는 그리 복슬복슬하지 않았다, 그렇지?'),
