    ('Happiness is over-rated anyway', '어차피 행복은 과대평가된 것이다'),
    ('Hats have gone out of style anyway.', '어차피 모자는 유행이 지났다.'),
    ('He Fought kind of Dirty.', '그는 좀 치사하게 싸웠다.'),
    ('He bursts into flames and is sucked into the earth.', '그는 불길에 휩싸여 땅속으로 빨려 들어간다.'),
    ('He disappears in a cloud of fairy dust.', '그는 요정 가루 구름 속으로 사라진다.'),
    ('He eats his information before he dies, so you learn nothing from him.', '그는 죽기 전에 정보를 삼켜 버려, 너는 아무것도 얻지 못한다.'),
    ('He gasps a final breath and melts into a tarry liquid.', '그는 마지막 숨을 몰아쉬고 타르 같은 액체로 녹아내린다.'),
    ('He lost me at the corrupt it to save it part.', '"구하려면 타락시켜야 한다"는 대목에서 이미 설득력을 잃었다.'),
    ('He really was just a feather-weight', '그는 정말 깃털처럼 가벼운 상대였다'),
    ('He really went to pieces, didn''t he?', '아주 산산조각이 났군, 그렇지?'),
    ('He resembled a mosquito more than a vampire bat', '흡혈박쥐라기보다는 모기에 가까웠다'),
    ('He speaks only these words as he dies: "You must leave the Dragon''s Forest."', '그는 죽으며 이 말만 남긴다: "너는 용의 숲을 떠나야 한다."'),
    ('He took so long to aim, you just walked up and kicked him', '조준하는 데 하도 오래 걸려서, 그냥 걸어가 걷어차 버렸다'),
