    ('Her breath was worse than her bite', '그녀의 입냄새가 물어뜯기보다 더 지독했다'),
    ('Here kitty kitty kitty', '이리 온 야옹아 야옹아'),
    ('Here taco taco taco..', '이리 온 타코야 타코야..'),
    ('His armor sizzles and he melts as he crumples to the ground.', '갑옷이 지글거리고, 그는 녹아내리며 땅에 무너진다.'),
    ('His death is a rather sad charade', '그의 죽음은 다소 서글픈 가면극이다'),
    ('His evil laughter dies with him.', '그의 사악한 웃음이 그와 함께 죽는다.'),
