    ('His last words were "...I must protect the dragon"', '그의 마지막 말은 "...나는 용을 지켜야 한다"였다'),
    ('His leg ought to make a good toy for your dog.', '그의 다리는 네 개에게 좋은 장난감이 되겠다.'),
    ('His pockets were almost empty, I guess he wasn''t much of a thief.', '주머니가 거의 비어 있었다. 별로 대단한 도둑은 아니었나 보다.'),
    ('Hmm Not too good at combat the second time around, either.', '흠, 두 번째에도 전투에는 영 소질이 없군.'),
