    ('Ho, Ho, Ho that, green man.', '호, 호, 호, 그 초록 사내 말이지.'),
    ('I *HATE* spiders!', '나는 거미가 *정말* 싫다!'),
    ('I didn''t need a bath, thank you.', '목욕은 필요 없었는데, 고맙군.'),
    ('I don''t even want to know how they breed these', '이런 것을 어떻게 번식시키는지 알고 싶지도 않다'),
    ('I guess the saying is true, Wild Horse can''t drag you away', '속담이 맞나 보다, 야생마도 너를 끌고 가지는 못한다'),
    ('I guess this makes you king of their Village.', '이걸로 네가 그 마을의 왕이 되겠군.'),
    ('I know where I can get him made into a nice pair of boots', '이걸로 멋진 장화 한 켤레를 맞출 곳을 안다'),
    ('I really really hate spiders.', '나는 거미가 정말 정말 싫다.'),
    ('I snapped him like a.. well, twig.', '잔가지처럼.. 아니, 말 그대로 부러뜨렸다.'),
