    ('It was a no-win situation, speeding on these forest paths.  The driver had it coming.', '이 숲길에서 과속이라니 애초에 이길 수 없는 싸움이었다. 운전자가 자초한 일이다.'),
    ('It was a shame to kill her.', '그녀를 죽인 것은 안타까운 일이었다.'),
