    ('Mirror, Mirror, on the Ground, it is your death that you have found.', '거울아 거울아 땅에 놓인 거울아, 네가 찾은 것은 네 죽음이란다.'),
    ('Mmm...Bacon', '음...베이컨'),
    ('Mr. Bear was too tired to finish playing with you and went back to napping', '곰 씨는 너무 지쳐 놀이를 그만두고 다시 낮잠을 자러 갔다'),
