    ('Slings and Arrows of outrageous fortune? Nope.  Just the can o'' Whoopass.', '무도한 운명의 돌팔매와 화살? 아니지. 그냥 응징의 한 방이다.'),
    ('So THAT''S what happens when you right-click a Mac.', '맥에서 우클릭하면 이렇게 되는군.'),
