    ('This reminds you of the time you needed a new heel for your shoe', '신발 굽을 갈아야 했던 때가 떠오른다'),
    ('Those Ladybugs weren''t very ladylike.', '그 무당벌레들은 별로 숙녀답지 않았다.'),
    ('Those little teeth HURT!', '그 작은 이빨들, 정말 아프다!'),
    ('To think you almost ran away!', '하마터면 달아날 뻔했다니!'),
    ('Two heads are not better than one in this case.  Just more to lop off', '이 경우엔 머리 둘이 하나보다 낫지 않다. 잘라 낼 것이 늘 뿐.'),
