    ('What the heck is a Lemur??', '여우원숭이가 대체 뭐야??'),
    ('When one wears a pin saying "Dragon Lovers Anonymous" they really are not as anonomous as they might think', '"용 애호가 익명 모임" 배지를 달고 다니면 생각만큼 익명은 아니다'),
    ('Who decides that this bat is a "Medium"?  Maybe he is a giant bat who hasn''t bloomed yet.', '이 박쥐를 누가 "중간 크기"라고 정했지? 아직 다 자라지 않은 거대 박쥐일지도 모른다.'),
    ('Who knew ferrets were so violent!', '족제비가 이렇게 사나운 줄 누가 알았겠나!'),
    ('Who knew goblins had lackeys?', '고블린에게 졸개가 있는 줄 누가 알았겠나?'),
