    ('With a satisfying thump, you knock the smirk right off his face', '통쾌한 한 방에 그 능글맞은 웃음이 얼굴에서 떨어져 나간다'),
    ('With a well placed stomp, Audrey and the kittens are no more.', '정확한 발구르기 한 번에 오드리와 새끼 고양이들은 사라졌다.'),
    ('With her dying breath she gasps "...and I never saw the dragon."', '그녀는 마지막 숨으로 "...끝내 용을 보지 못했구나"라고 내뱉는다.'),
