    ('You are even more god-like then he', '너는 그보다도 더 신 같다'),
    ('You are not easily bribed, and he was a mortal enemy', '너는 쉽게 매수되지 않았고, 그는 불구대천의 원수였다'),
    ('You aren''t sure how you did it, but you killed something that was already dead.  Good for you.', '어떻게 했는지는 모르겠지만, 이미 죽은 것을 죽였다. 잘했다.'),
