    ('You have bested their army by killing its master.', '주인을 죽여 그들의 군대를 이겼다.'),
    ('You have rendered the Chef Ironless!  He''s now simply a copper/tin alloy!', '요리사에게서 철을 빼앗았다! 이제 그저 구리주석 합금일 뿐이다!'),
