    ('You know Violet isn''t going to believe a Whale attacked you in the forest', '숲에서 고래가 덤벼들었다는 말을 바이올렛이 믿어 줄 리 없다'),
    ('You know your motto, Live and let die.', '네 좌우명대로다, 살고 또 죽게 하라.'),
    ('You leave him to the mercies of the other ghouls..', '다른 구울들의 자비에 그를 맡긴다..'),
    ('You manage to break free of those deep hypnotic eyes...', '그 깊은 최면의 눈에서 겨우 벗어난다...'),
    ('You marched in like a lion and he died like a lamb', '사자처럼 들어갔고 그는 양처럼 죽었다'),
    ('You never were the diplomatic type.', '너는 애초에 외교적인 유형이 아니었다.'),
    ('You only wish you could pickpocket your money back from the thief.', '도둑에게서 돈을 소매치기해 되찾을 수 있으면 좋으련만.'),
    ('You pick up the box and put it in your pocket.  You never know when a tissue might come in handy', '상자를 주워 주머니에 넣는다. 화장지가 언제 요긴할지 모르니'),
    ('You plunge your weapon into her breast, silencing her song', '무기를 그녀의 가슴에 꽂아 그 노래를 잠재운다'),
    ('You ponder the tiger''s body thinking what a good rug it might make', '호랑이 시체를 보며 좋은 양탄자가 되겠다고 생각한다'),
    ('You really aren''t sure if it is dead, or just hiding...after all it is invisible', '죽었는지 그냥 숨은 것인지 알 수 없다... 어차피 보이지 않으니'),
    ('You really cut that wood sprite down to size', '그 나무 정령을 크기에 맞게 잘라 냈다'),
    ('You really prefer black dresses anyway.', '어차피 너는 검은 드레스를 더 좋아한다.'),
    ('You regret killing him, you wanted to see him make a dragon jump through that hoop', '그를 죽인 것이 아깝다, 용이 저 굴렁쇠를 통과하는 걸 보고 싶었는데'),
    ('You send the ceature back to where it came from.', '그 존재를 온 곳으로 돌려보낸다.'),
    ('You shake your fist over his dead, pathetic corpse.', '죽어 널브러진 그의 시체 위로 주먹을 흔든다.'),
    ('You slice him in two only to watch his body disappear, leaving an empty robe behind.', '그를 둘로 베자 몸은 사라지고 빈 로브만 남는다.'),
    ('You smile a grim smile at Willie and quietly munch on some seeds', '윌리를 향해 서늘한 미소를 짓고 조용히 씨앗을 갉아 먹는다'),
    ('You still don''t get it.', '너는 아직도 이해하지 못한다.'),
    ('You sure cut that cheese....eater', '그 치즈....먹는 놈을 제대로 잘라 냈다'),
    ('You survived a battle to the death with a butterfly.  You must be so proud.', '나비와의 목숨 건 결투에서 살아남았다. 참 자랑스럽겠다.'),
    ('You swat the little bird out of the air with little effort.', '힘도 들이지 않고 작은 새를 공중에서 쳐 낸다.'),
    ('You swat the small, majestic beast out of the air.', '작고 장엄한 짐승을 공중에서 쳐 낸다.'),
    ('You sweep the poor bunny under the rug when no one is looking', '아무도 보지 않을 때 가엾은 토끼를 양탄자 밑으로 밀어 넣는다'),
    ('You think it was the alliteration that did him in.', '그를 죽인 것은 두운이었던 것 같다.'),
    ('You think to yourself they look tougher on TV', '텔레비전에서는 더 강해 보인다고 속으로 생각한다'),
    ('You thought bats were republicans.', '박쥐는 공화당원인 줄 알았다.'),
    ('You wonder who watches the watchers', '감시자를 감시하는 자는 누구인가 생각한다'),
    ('Your swift moves were too fast for this sloth', '네 날쌘 몸놀림은 이 나무늘보에게 너무 빨랐다'),
    ('Your victory is not comforting, you know he will still catch up to you', '승리가 위안이 되지 않는다, 그는 결국 너를 따라잡을 것이다')
  ) AS source
  JOIN creature ON creature.victory_message = source.column1;

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'creature', creature.creature_id, 'defeat_message', 'ko', source.column2
  FROM (VALUES
    ('What is the sound of one hand clapping?', '한 손으로 치는 박수 소리는 어떤 것인가?')
  ) AS source
  JOIN creature ON creature.defeat_message = source.column1;

DELETE FROM catalog_translation
 WHERE entity_type = 'creature'
   AND field_code IN ('victory_message', 'defeat_message')
   AND locale_code = 'ja';

