  ) AS source
  JOIN creature ON creature.victory_message = source.column1;

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'creature', creature.creature_id, 'defeat_message', 'ja', source.column2
  FROM (VALUES
    ('What is the sound of one hand clapping?', '隻手の音声とはいかなるものか？')
  ) AS source
  JOIN creature ON creature.defeat_message = source.column1;

DELETE FROM catalog_translation
 WHERE entity_type = 'creature'
   AND field_code IN ('victory_message', 'defeat_message')
   AND locale_code = 'zh';

