    ('You really aren''t sure if it is dead, or just hiding...after all it is invisible', '你实在拿不准它是死了还是藏起来了……毕竟它是隐形的'),
    ('You really cut that wood sprite down to size', '你把那木精灵砍到了合适的尺寸'),
    ('You really prefer black dresses anyway.', '反正你更喜欢黑裙子。'),
    ('You regret killing him, you wanted to see him make a dragon jump through that hoop', '你后悔杀了他，本想看他让龙钻过那个圆环'),
    ('You send the ceature back to where it came from.', '你把那生物送回了它来的地方。'),
    ('You shake your fist over his dead, pathetic corpse.', '你对着他可悲的尸体挥了挥拳。'),
    ('You slice him in two only to watch his body disappear, leaving an empty robe behind.', '你将他劈成两半，只见身躯消失，只留下一件空袍。'),
    ('You smile a grim smile at Willie and quietly munch on some seeds', '你朝威利露出冷峻的笑，静静嚼着几粒种子'),
    ('You still don''t get it.', '你还是没搞明白。'),
    ('You sure cut that cheese....eater', '你确实把那个吃奶酪的……切得漂亮'),
    ('You survived a battle to the death with a butterfly.  You must be so proud.', '你在与一只蝴蝶的殊死搏斗中活了下来。想必十分自豪。'),
    ('You swat the little bird out of the air with little effort.', '你毫不费力地把小鸟从空中拍落。'),
    ('You swat the small, majestic beast out of the air.', '你把那小巧而威严的生灵从空中拍落。'),
    ('You sweep the poor bunny under the rug when no one is looking', '趁没人看见，你把可怜的兔子扫到地毯下面'),
    ('You think it was the alliteration that did him in.', '你觉得害死他的是那串头韵。'),
    ('You think to yourself they look tougher on TV', '你心想，它们在电视上看着更凶'),
    ('You thought bats were republicans.', '你还以为蝙蝠都是共和党人。'),
    ('You wonder who watches the watchers', '你想着，谁来监视监视者呢'),
    ('Your swift moves were too fast for this sloth', '你的迅捷身法对这只树懒来说太快了'),
    ('Your victory is not comforting, you know he will still catch up to you', '胜利并不令人安心，你知道他终会追上你')
  ) AS source
  JOIN creature ON creature.victory_message = source.column1;

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'creature', creature.creature_id, 'defeat_message', 'zh', source.column2
  FROM (VALUES
    ('What is the sound of one hand clapping?', '只手拍击之声为何？')
  ) AS source
  JOIN creature ON creature.defeat_message = source.column1;

DELETE FROM catalog_translation
 WHERE entity_type = 'creature'
   AND field_code IN ('victory_message', 'defeat_message')
   AND locale_code = 'ru';

