    ('The skeleton crumbles into a pile of dust.', 'Скелет рассыпается в кучку праха.'),
    ('The small mammal falls to the ground', 'Мелкий зверёк падает на землю'),
    ('The spiritling gasps a final breath as you end its pitiful life', 'Духёныш делает последний вздох, и ты обрываешь его жалкую жизнь'),
    ('The spirits of its victims drag the skeleton back to hell', 'Духи жертв утаскивают скелет обратно в ад'),
    ('The storm is no more, you can see the light of day peeking through the last of the clouds', 'Бури больше нет, дневной свет пробивается сквозь последние облака'),
    ('The strange little monkey falls from the trees and lies still.', 'Странная обезьянка падает с дерева и замирает.'),
    ('The things beautiful people have to put up with.', 'И что только не приходится терпеть красивым людям.'),
    ('The tiny warrior dies with a faint squeal', 'Крошечный воин умирает с тихим писком'),
    ('The tree is  burning, you''d better try to put it out.', 'Дерево горит, лучше поспеши его потушить.'),
    ('The truth gave you life and the truth set you free', 'Истина дала тебе жизнь, и истина сделала тебя свободным'),
    ('The twisted man-beast lies still', 'Искорёженный человекозверь лежит недвижим'),
    ('There is but one Gar Man!  And now he''s just fluff!', 'Гар-мэн только один! И теперь от него остался лишь пух!'),
    ('There is no justice for an angry mob', 'Для разъярённой толпы правосудия нет'),
    ('There it is!  Death!!!!!', 'Вот она! Смерть!!!!!'),
    ('There must be fifty ways to cut your lumber (Groan)', 'Должно быть, есть полсотни способов пилить брёвна (ох)'),
    ('There seems to be a person inside that strange dino.  You wonder why.', 'Внутри того странного динозавра, кажется, сидит человек. Зачем — непонятно.'),
    ('There was just enough steam left to make an espresso', 'Пара осталось ровно на одну чашку эспрессо'),
    ('There''s one lawyer who''ll never trouble you again!', 'Вот один юрист, который больше тебя не потревожит!'),
    ('They DO smell worse when they are bigger!', 'Чем они крупнее, тем хуже пахнут — это правда!'),
    ('They did all right until they hit each other.', 'Они неплохо держались, пока не столкнулись друг с другом.'),
    ('They just wanted to be your friend.  You meanie.', 'Они всего лишь хотели с тобой подружиться. Злюка.'),
    ('They learn to ride dragons using a mechanical bull?', 'Они учатся ездить на драконах с помощью механического быка?'),
    ('This carnage disgusts you', 'Эта бойня вызывает у тебя отвращение'),
    ('This extra is really on her own now', 'Теперь эта статистка и вправду сама по себе'),
    ('This fan doesn''t have much to cheer about.', 'Этому болельщику радоваться особо нечему.'),
    ('This guy really painted himself into a corner', 'Этот тип и правда загнал себя в угол'),
    ('This is indeed a grave situation', 'Положение поистине могильное'),
    ('This is one whopper that won''t show up on your hips tomorrow.', 'Этот воппер завтра не отложится у тебя на боках.'),
    ('This narcoleptic won''t be waking up anytime soon', 'Этот нарколептик не проснётся ещё долго'),
    ('This one''s nuts!', 'Этот совсем спятил!'),
    ('This reminds you of the time you needed a new heel for your shoe', 'Это напоминает тебе о том, как нужно было сменить каблук на ботинке'),
    ('Those Ladybugs weren''t very ladylike.', 'Те божьи коровки вели себя вовсе не по-дамски.'),
    ('Those little teeth HURT!', 'Эти мелкие зубы кусаются больно!'),
    ('To think you almost ran away!', 'И подумать только, ты чуть не сбежал!'),
    ('Two heads are not better than one in this case.  Just more to lop off', 'В этом случае две головы не лучше одной. Просто рубить больше'),
    ('We should all pray for whirled peas.', 'Помолимся же все о взбитом горошке.'),
    ('Well, im sure that helped him on his way...', 'Что ж, в путь его это точно проводило...'),
    ('Well, really, who throws a cell phone?  I mean, that really, really hurt!', 'Нет, ну кто вообще бросается телефоном? Это было очень, очень больно!'),
    ('Well, that was a bad move', 'Что ж, это был плохой ход'),
    ('Well, you sure reprioritized his downsizing.', 'Что ж, ты основательно переставил приоритеты его сокращения.'),
    ('What happens when I do THIS?', 'А что будет, если сделать вот так?'),
    ('What is the sound of one hand clapping?', 'Каков звук хлопка одной ладонью?'),
    ('What the heck is a Lemur??', 'Что за чертовщина этот лемур??'),
    ('When one wears a pin saying "Dragon Lovers Anonymous" they really are not as anonomous as they might think', 'Если носишь значок «Анонимные драконолюбы», ты вовсе не так анонимен, как думаешь'),
    ('Who decides that this bat is a "Medium"?  Maybe he is a giant bat who hasn''t bloomed yet.', 'Кто решил, что эта мышь «средняя»? Может, это гигантская, просто ещё не выросла.'),
    ('Who knew ferrets were so violent!', 'Кто бы знал, что хорьки такие свирепые!'),
    ('Who knew goblins had lackeys?', 'Кто бы знал, что у гоблинов есть прихвостни?'),
    ('Why are there so many darn bats in this forest?', 'Откуда в этом лесу столько треклятых летучих мышей?'),
    ('Why do movie bats always fly at people''s hair?', 'Почему в кино летучие мыши всегда лезут людям в волосы?'),
    ('Why in the world would that monster be in this forest.  You must have been dreaming!', 'С какой стати такому чудовищу быть в этом лесу. Тебе явно померещилось!'),
    ('With a satisfying thump, you knock the smirk right off his face', 'С приятным глухим стуком ты сбиваешь ухмылку с его лица'),
    ('With a well placed stomp, Audrey and the kittens are no more.', 'Один точный удар ногой — и Одри с котятами больше нет.'),
    ('With her dying breath she gasps "...and I never saw the dragon."', 'С последним вздохом она выдыхает: «...а дракона я так и не увидела».'),
    ('With his dying breath he explodes into a pillar of black flame!', 'С последним вздохом он взрывается столбом чёрного пламени!'),
    ('With one fell swoop you save your social life!', 'Одним махом ты спасаешь свою светскую жизнь!'),
    ('Won''t Someone PLEASE stop the Violins?', 'Ну пусть кто-нибудь остановит эти скрипки!'),
    ('Wow, he smelled bad enough alive, can you imagine how he''ll smell tomorrow?', 'Ого, он и живой вонял будь здоров, представляешь, чем будет пахнуть завтра?'),
    ('Wrecked''em?  Darn near killed ''em!', 'Разнёс? Да чуть не прикончил!'),
    ('You are afraid of the dark no longer', 'Ты больше не боишься темноты'),
    ('You are even more god-like then he', 'Ты ещё богоподобнее, чем он'),
    ('You are not easily bribed, and he was a mortal enemy', 'Тебя непросто подкупить, а он был смертельным врагом'),
    ('You aren''t sure how you did it, but you killed something that was already dead.  Good for you.', 'Ты не понял, как это вышло, но убил то, что уже было мертво. Молодец.'),
    ('You bow to the fallen master before you walk away', 'Ты кланяешься павшему мастеру и уходишь'),
    ('You break the deadly gaze of the snake to save your own life', 'Ты разрываешь смертельный взгляд змеи, спасая свою жизнь'),
    ('You climb atop the Mammoth''s remains and declare yourself king (or queen) for a day!', 'Ты забираешься на останки мамонта и объявляешь себя королём (или королевой) на день!'),
    ('You cooled him off in a hurry...', 'Ты остудил его в два счёта...'),
    ('You could use an ale', 'Тебе бы сейчас кружку эля'),
    ('You cut off the Demon''s head, to be sure of its death.', 'Ты отрубаешь демону голову, чтобы удостовериться в его смерти.'),
    ('You decide to leave before the rest of the bats come to find their king', 'Ты решаешь уйти, пока прочие мыши не явились за своим королём'),
    ('You defeated him, but caught a cold.', 'Ты одолел его, но простудился.'),
    ('You didn''t like his style', 'Тебе не понравился его стиль'),
    ('You dispatch the bear and wonder if there are more lurking about.', 'Ты приканчиваешь медведя и гадаешь, не таятся ли поблизости другие.'),
    ('You extinguish the flame of life and the zombie falls to the ground, smoking.', 'Ты гасишь пламя жизни, и зомби падает наземь, дымясь.'),
    ('You feel as if you have seen this man before in the village', 'Тебе кажется, что этого человека ты уже видел в деревне'),
    ('You feel like a pincushion, but you are alive', 'Ты чувствуешь себя игольницей, но ты жив'),
    ('You feel like a real jerk killing something so pretty', 'Убив такое красивое создание, ты чувствуешь себя настоящим негодяем'),
    ('You feel the need to take a bath', 'Тебе хочется принять ванну'),
    ('You find a copy of "Cave-Dwelling Dragons, and Where to Find Them." in his pack', 'В его мешке ты находишь «Пещерные драконы и где их искать».'),
    ('You find a dragon-watching textbook in his backpack.', 'В его рюкзаке ты находишь учебник по наблюдению за драконами.'),
    ('You gave more blood to the Red Cross', 'Красному Кресту ты сдавал крови и побольше'),
    ('You give the clown''s nose a honk just for fun before you leave', 'Уходя, ты забавы ради нажимаешь клоуну на нос'),
    ('You have bested their army by killing its master.', 'Убив хозяина, ты одолел всё их войско.'),
    ('You have rendered the Chef Ironless!  He''s now simply a copper/tin alloy!', 'Ты лишил повара железа! Теперь он просто медно-оловянный сплав!'),
    ('You have sent this student to permenant detention', 'Ты отправил этого ученика на вечное наказание после уроков'),
    ('You have set the tortured souls free', 'Ты освободил истерзанные души'),
    ('You have slain Cupid, you shall never find true love', 'Ты убил Купидона — истинной любви тебе не найти'),
    ('You have slain the goose but it is too heavy to take back to town.  All that wealth wasted.', 'Ты убил гуся, но он слишком тяжёл, чтобы нести в город. Всё богатство пропало даром.'),
    ('You hope he wasn''t a relative of the Green Dragon', 'Ты надеешься, что он не был роднёй Зелёного Дракона'),
    ('You kick at the annoying pest as it lies on the ground', 'Ты пинаешь надоедливого вредителя, лежащего на земле'),
    ('You kill the doppleganger and he returns to his true form.', 'Ты убиваешь доппельгангера, и он принимает истинный облик.'),
    ('You kill the necromancer and his minions disintegrate before your eyes.', 'Ты убиваешь некроманта, и его прислужники рассыпаются у тебя на глазах.'),
    ('You killed it just to shut it up.', 'Ты убил его лишь бы заставить замолчать.'),
    ('You know Violet isn''t going to believe a Whale attacked you in the forest', 'Ты знаешь, что Виолетта не поверит, будто в лесу на тебя напал кит'),
    ('You know your motto, Live and let die.', 'Твой девиз известен: живи и дай умереть.'),
    ('You leave him to the mercies of the other ghouls..', 'Ты оставляешь его на милость прочих упырей...'),
    ('You manage to break free of those deep hypnotic eyes...', 'Тебе удаётся вырваться из этих глубоких гипнотических глаз...'),
    ('You marched in like a lion and he died like a lamb', 'Ты вошёл, как лев, а он умер, как ягнёнок'),
    ('You never were the diplomatic type.', 'Дипломатом ты никогда не был.'),
    ('You only wish you could pickpocket your money back from the thief.', 'Тебе бы вытащить свои деньги обратно из кармана вора.'),
    ('You pick up the box and put it in your pocket.  You never know when a tissue might come in handy', 'Ты подбираешь коробку и кладёшь в карман. Мало ли когда пригодится салфетка'),
    ('You plunge your weapon into her breast, silencing her song', 'Ты вонзаешь оружие ей в грудь, обрывая песню'),
    ('You ponder the tiger''s body thinking what a good rug it might make', 'Ты разглядываешь тушу тигра, думая, какой славный выйдет ковёр'),
    ('You really aren''t sure if it is dead, or just hiding...after all it is invisible', 'Ты не уверен, мертво оно или просто прячется... оно ведь невидимо'),
    ('You really cut that wood sprite down to size', 'Ты и впрямь укоротил этого лесного духа до нужного размера'),
    ('You really prefer black dresses anyway.', 'Тебе всё равно больше по душе чёрные платья.'),
    ('You regret killing him, you wanted to see him make a dragon jump through that hoop', 'Ты жалеешь, что убил его: хотелось увидеть, как дракон прыгнет сквозь тот обруч'),
    ('You send the ceature back to where it came from.', 'Ты отправляешь тварь туда, откуда она пришла.'),
    ('You shake your fist over his dead, pathetic corpse.', 'Ты потрясаешь кулаком над его жалким трупом.'),
    ('You slice him in two only to watch his body disappear, leaving an empty robe behind.', 'Ты рассекаешь его надвое, но тело исчезает, оставив лишь пустую мантию.'),
    ('You smile a grim smile at Willie and quietly munch on some seeds', 'Ты мрачно улыбаешься Вилли и тихо грызёшь семечки'),
    ('You still don''t get it.', 'Ты всё ещё не понял.'),
    ('You sure cut that cheese....eater', 'Ты знатно разделал этого... сыроеда'),
    ('You survived a battle to the death with a butterfly.  You must be so proud.', 'Ты выжил в смертельной схватке с бабочкой. Наверное, ты очень горд.'),
    ('You swat the little bird out of the air with little effort.', 'Ты без труда сбиваешь птичку прямо в воздухе.'),
    ('You swat the small, majestic beast out of the air.', 'Ты сбиваешь маленькое величавое создание прямо в воздухе.'),
    ('You sweep the poor bunny under the rug when no one is looking', 'Пока никто не видит, ты заметаешь беднягу кролика под ковёр'),
    ('You think it was the alliteration that did him in.', 'Ты думаешь, что его сгубила аллитерация.'),
    ('You think to yourself they look tougher on TV', 'Ты думаешь про себя, что по телевизору они выглядят покрепче'),
    ('You thought bats were republicans.', 'Ты думал, летучие мыши — республиканцы.'),
    ('You wonder who watches the watchers', 'Ты задаёшься вопросом, кто сторожит сторожей'),
    ('Your swift moves were too fast for this sloth', 'Твои быстрые движения оказались слишком стремительны для этого ленивца'),
    ('Your victory is not comforting, you know he will still catch up to you', 'Победа не утешает: ты знаешь, что он всё равно тебя настигнет')
  ) AS source
  JOIN creature ON creature.victory_message = source.column1;

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'creature', creature.creature_id, 'defeat_message', 'ru', source.column2
  FROM (VALUES
    ('What is the sound of one hand clapping?', 'Каков звук хлопка одной ладонью?')
  ) AS source
  JOIN creature ON creature.defeat_message = source.column1;

DELETE FROM catalog_translation WHERE entity_type = 'riddle' AND locale_code = 'ko';

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'riddle', riddle.riddle_id, source.column1, 'ko', source.column3
  FROM (VALUES
    ('riddle_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', '너는 심지도 갈지도 않은 것을 먹는다.`n그것은 물의 아들이나, 물이 닿으면 죽는다.'),
    ('answer_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', '소금'),
    ('riddle_text', 'Teacher, open thy book.', '선생이여, 그대의 책을 펴라.'),
    ('answer_text', 'Teacher, open thy book.', '나비'),
    ('riddle_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', '내 갈래는 길다.`n내 갈래는 짧다.`n내 갈래는 끝난다`n내 첫 소식이 닿기 전에.'),
    ('answer_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', '번개; 벼락'),
    ('riddle_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', '우리를 뒤집어`n배를 열어 보아라`n너는 가장 지혜로운 자가 되리라`n처음엔 얼간이였을지라도.'),
    ('answer_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', '책'),
    ('riddle_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', '깊이 묻고`n돌을 쌓아라,`n그래도 나는`n그 뼈를 파낼 것이다.'),
    ('answer_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', '기억'),
    ('riddle_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', '그것은 매 분마다 한 번 나타나고`n매 순간마다 두 번 나타나지만`n십만 년 안에는 한 번도 없다.'),
    ('answer_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', '글자 M; M'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', '결코 앞서지 않고 늘 뒤에 있으나,`n쏜살같이 스쳐 지나간다.`n아이에게 나는 영원하고,`n어른에게 나는 너무 빨리 사라진다.'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', '어린 시절'),
    ('riddle_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', '가장 빨리 달리는 두 마리 말,`n한 쌍으로 매여 있으나`n언제나 저희에게서 먼 곳에서`n풀을 뜯는다.'),
    ('answer_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', '두 눈; 해와 달'),
    ('riddle_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', '이렇게 말할 수 있다.`n황금이면 선한 것이고,`n돌이면 아무것도 아니며,`n유리면 부서지기 쉽고,`n차가우면 잔혹하다고.`n비유를 걷어 내면, 나는 무엇인가?'),
    ('answer_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', '심장'),
    ('riddle_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', '둥글지만 판자처럼 납작하고`n늑대 군주들의 제단이라.`n검은 벨벳 위의 보석, 바다의 진주,`n변함없되 영원히 변하는 것.'),
    ('answer_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', '달'),
    ('riddle_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', '그것은 황금 머리를 가졌고`n황금 꼬리를 가졌으나`n몸은 없다.'),
    ('answer_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', '금화; 동전'),
    ('riddle_text', 'Speak, friend, and enter!', '친구여, 말하고 들어오라!'),
    ('answer_text', 'Speak, friend, and enter!', '친구'),
    ('riddle_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', '가죽 같은 뱀,`n쏘는 듯한 무는 힘,`n나는 감겨 있으리라,`n싸워야 할 때가 아니라면.'),
    ('answer_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', '채찍'),
    ('riddle_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', '아무도 보지 못하는 뿌리를 지니고,`n나무보다 높으며,`n위로, 위로 뻗지만`n결코 자라지 않는 것은?'),
    ('answer_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', '산'),
    ('riddle_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', '붉은 언덕 위 서른 마리 흰 말,`n먼저 물어뜯고,`n다음엔 짓밟고,`n그러고는 가만히 선다.'),
    ('answer_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', '이빨'),
    ('riddle_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', '목소리 없이 울고,`n날개 없이 나부끼며,`n이빨 없이 물고,`n입 없이 중얼거린다.'),
    ('answer_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', '바람'),
    ('riddle_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', '보이지 않고 만져지지 않으며,`n들리지 않고 냄새도 나지 않는다.`n별 뒤에 있고 언덕 아래 있으며,`n빈 구멍을 채운다.`n먼저 오고 뒤따라오며,`n생명을 끝내고 웃음을 죽인다.'),
    ('answer_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', '어둠'),
    ('riddle_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', '경첩도 열쇠도 뚜껑도 없는 상자,`n그 안에 황금 보물이 숨어 있다.'),
    ('answer_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', '달걀; 오렌지'),
    ('riddle_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', '숨 없이 살아 있고,`n죽음처럼 차가우며,`n목마른 적 없으나 늘 마시고,`n갑옷을 둘렀으나 소리 나지 않는다.'),
    ('answer_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', '물고기'),
    ('riddle_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', '이것은 모든 것을 삼킨다.`n새와 짐승과 나무와 꽃,`n쇠를 갉고 강철을 물어뜯으며,`n단단한 돌을 가루로 만들고,`n왕을 죽이고 마을을 무너뜨리며,`n높은 산을 깎아 내린다.'),
    ('answer_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', '시간'),
    ('riddle_text', 'You feel it, but never see it and never will.', '너는 그것을 느끼지만, 결코 보지 못하고 앞으로도 보지 못한다.'),
    ('answer_text', 'You feel it, but never see it and never will.', '심장'),
    ('riddle_text', 'You must keep it after giving it.', '그것은 준 뒤에도 지켜야 한다.'),
    ('answer_text', 'You must keep it after giving it.', '약속'),
    ('riddle_text', 'As light as a feather, but you can''t hold it for ten minutes.', '깃털처럼 가볍지만, 십 분도 붙들고 있을 수 없다.'),
    ('answer_text', 'As light as a feather, but you can''t hold it for ten minutes.', '숨'),
    ('riddle_text', 'Has a mouth but does not speak, has a bed but never sleeps.', '입이 있으나 말하지 않고, 잠자리가 있으나 결코 잠들지 않는다.'),
    ('answer_text', 'Has a mouth but does not speak, has a bed but never sleeps.', '강'),
    ('riddle_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', '어떤 운율보다 매끄럽게 흐르고, 떨어지기를 좋아하나 오를 수는 없다!'),
    ('answer_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', '물'),
    ('riddle_text', 'You break it even if you name it!', '이름을 부르기만 해도 깨진다!'),
    ('answer_text', 'You break it even if you name it!', '침묵'),
    ('riddle_text', 'It passes before the sun and makes no shadow.', '해 앞을 지나가면서도 그림자를 만들지 않는다.'),
    ('answer_text', 'It passes before the sun and makes no shadow.', '공기'),
    ('riddle_text', 'You feed it, it lives, you give it something to drink, it dies.', '먹이면 살고, 마실 것을 주면 죽는다.'),
    ('answer_text', 'You feed it, it lives, you give it something to drink, it dies.', '불'),
    ('riddle_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', '붉은 북 하나가`n건드리지 않아도 울리고,`n건드리면`n조용해진다.'),
    ('answer_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', '심장'),
    ('riddle_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', '같은 날 뿌리고 거두는 수확,`n갈지 않은 밭에서 나며,`n자라지 않고 불어나고,`n안팎으로 먹히면서도`n온전히 남으며,`n쓸모없으나`n나라의 주식이다.'),
    ('answer_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', '전쟁'),
    ('riddle_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', '나를 부러뜨려도`n나는 멈추지 않고,`n나를 건드리면`n나는 덫에 걸릴 수 있으며,`n나를 잃으면`n아무것도 의미가 없다.'),
    ('answer_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', '희망'),
    ('riddle_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', '사방에 있으나 볼 수 없고,`n잡을 수 있으나 쥘 수 없으며`n목구멍이 없어도 들린다.'),
    ('answer_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', '소리; 소음'),
    ('riddle_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', '나는 빙빙 돌지만,`n언제나 앞으로 곧게 간다.`n어디로 이끌리든`n결코 불평하지 않는다.'),
    ('answer_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', '바퀴'),
    ('riddle_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', '나를 이루는 것보다`n나는 가볍고,`n보이는 것보다`n감춰진 것이 더 많다.'),
    ('answer_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', '빙산'),
    ('riddle_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', '사람이 내 짐을 진다면`n허리가 부러질 것이다.`n나는 부유하지 않으나,`n지나간 자리에 은을 남긴다.'),
    ('answer_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', '달팽이'),
    ('riddle_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', '내 삶은 시간으로 잴 수 있고,`n삼켜짐으로써 봉사한다.`n가늘면 빠르고`n굵으면 느리며`n바람은 나의 적이다.'),
    ('answer_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', '초'),
    ('riddle_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', '배 속에는 무게,`n등에는 나무,`n갈비뼈에는 못,`n발은 없다.'),
    ('answer_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', '배; 동굴'),
    ('riddle_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', '내 얼굴을 들여다보면`n다른 것은 아무것도 보이지 않는다.`n나는 네 눈을 마주 보며`n결코 거짓을 말하지 않는다.'),
    ('answer_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', '거울'),
    ('riddle_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', '나는 늘 굶주려`n끊임없이 먹여야 하고,`n내가 핥은 손가락은`n곧 붉어진다.'),
    ('answer_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', '불'),
    ('riddle_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', '나는 세 개의 삶을 지녔다.`n살갗을 달랠 만큼 부드럽고,`n하늘을 어루만질 만큼 가벼우며`n바위를 쪼갤 만큼 단단하다.'),
    ('answer_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', '물'),
    ('riddle_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', '아래로 내리꽂히는`n반짝이는 끝,`n결코 녹슬지 않는`n빛나는 창들.'),
    ('answer_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', '고드름'),
    ('riddle_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', '아침마다 나는 나타나`n네 발치에 눕고,`n온종일 너를 따르며`n네가 아무리 빨리 달려도 놓치지 않지만,`n한낮의 태양 아래서는`n거의 스러진다.'),
    ('answer_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', '그림자'),
    ('riddle_text', 'Keys without locks`nYet I unlock the soul.', '자물쇠 없는 열쇠들이나`n나는 영혼을 연다.'),
    ('answer_text', 'Keys without locks`nYet I unlock the soul.', '피아노; 하프시코드'),
    ('riddle_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', '나는 너무나 단순하여`n가리키는 일밖에 못 하지만`n온 세상 사람들을`n인도한다.'),
    ('answer_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', '나침반'),
    ('riddle_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', '우리의 감로 때문에 우리는`n유피테르에게 죽음의 침을 받았다.`n우리의 힘이 누군가에겐 우스울지라도,`n우리는 용의 숨결을 잠재웠다.`n우리는 누구인가?'),
    ('answer_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', '벌'),
    ('riddle_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', '처녀의 뺨처럼 물들었고,`n내가 시작될 때 시간은 없었다.`n정원을 지나 몰래 들어와,`n나 홀로 인간의 타락이 되었다.`n나는 무엇인가?'),
    ('answer_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', '사과'),
    ('riddle_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', '없어야 할 곳에 하나,`n혹은 둘이어야 할 곳에,`n순결을 찾아`n왕의 숲을 헤맨다.`n나는 무엇인가?'),
    ('answer_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', '유니콘'),
    ('riddle_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', '물어뜯는 이빨 하나,`n그는 숲의 적이다.`n싸우는 이빨 하나,`n북방인은 모두 안다.`n그것은 무엇인가?'),
    ('answer_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', '도끼'),
    ('riddle_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', '하늘에 있지 않은`n새의 일부,`n바다에서 헤엄치면서도`n언제나 젖지 않는다.`n그것은 무엇인가?'),
    ('answer_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', '새의 그림자; 그림자'),
    ('riddle_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', '뿌리가 줄기 위에 있는`n이 거꾸로 된 것은,`n겨울에 자라고`n봄에 죽는다.`n그것은 무엇인가?'),
    ('answer_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', '고드름'),
    ('riddle_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', '하나에 닿으면서 둘을 품고,`n한 고리짜리 사슬이 되어`n말을 지키는 이들을 묶는다.`n죽음이 둘로 갈라놓을 때까지.`n그것은 무엇인가?'),
    ('answer_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', '결혼반지; 반지'),
    ('riddle_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', '지혜롭고 아는 자는 그것을 확신한다.`n어리석은 자조차 그것을 안다.`n부자는 그것을 원한다.`n가장 위대한 영웅도 그것을 두려워한다.`n그러나 가장 비천한 겁쟁이도 그것을 위해 죽는다.`n내가 곱씹는 이것은 무엇인가?'),
    ('answer_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', '아무것도 아닌 것; 무언가'),
    ('riddle_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', '신보다 크고,`n악마보다 나쁘며,`n죽은 자는 그것을 먹고,`n네가 그것을 먹으면 죽는 것은?'),
    ('answer_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', '아무것도 아닌 것'),
    ('riddle_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', '나는 여인들에게 훌륭한 도움이며,`n다가올 무언가의 희망이다. 나는 나를 베는 자 외에는`n누구도 해치지 않는다.`n뿌리내린 채 높은 자리에 서 있고`n아래는 덥수룩하다. 때로는 아름다운`n농부의 딸, 팔을 걷어붙인`n당당한 여인이 내 몸을 붙잡아,`n붉은 살갗을 벗기고 꽉 쥐며,`n내 머리를 차지한다. 나를 단단히 붙든`n곱슬머리 여인은 우리의 만남을 느끼리라.`n그녀의 눈이 젖을 것이다.'),
    ('answer_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', '양파'),
    ('riddle_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', '군주가 쥘 힘이자 보물,`n단단하고 가파른 뺨을 지녔으며, 붉은`n금과 석류석에 싸여, 밝은 꽃들의 들판에서`n뜯겨 나와, 불과 줄의 잔재로 벼려졌고,`n섬세한 철사로 준엄한 아름다움에 묶였다.`n내 손아귀는 전사를 울리고, 내 침은`n황금을 쥔 손을 위협한다. 고리를 박은 채`n나는 상속자와 가보를 유린한다.`n내 주인에게도 적에게도 언제나 아름답고`n치명적이며, 얼굴과 모습을 바꾼다.'),
    ('answer_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', '검'),
    ('riddle_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', '내가 세인트 아이브스로 가는 길에`n일곱 아내를 둔 남자를 만났다.`n아내마다 일곱 자루를 지녔고,`n자루마다 일곱 고양이가 있었으며,`n고양이마다 일곱 새끼가 있었다.`n새끼와 고양이와 자루와 아내들,`n세인트 아이브스로 가던 것은 몇이었나?'),
    ('answer_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', '하나'),
    ('riddle_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', '새벽이 저물고,`n낮은 잿빛이 되니,`n나는 멀리 떠나야 한다.`n허나 나는 돌아오리라,`n그리고 우리는 좇으리라,`n또 다른 하루의 빛을.'),
    ('answer_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', '해; 그림자'),
    ('riddle_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', '깊고, 어둡고, 땅속,`n그곳이 내가 발견되는 자리다.`n허나 햇빛 아래로 나오면,`n나는 사방으로 빛을 흩뿌린다.`n기름에 흐려진 채 발견되어도,`n나는 놀랍도록 온전하고 견고하다.`n나를 재빨리 깎아 보면 알리라,`n내가 곧 눈부신 광채를 지닌다는 것을.'),
    ('answer_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', '다이아몬드; 보석'),
    ('riddle_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', '화덕에 있어야 하나 구워지지 않는 것은?`n열기 속에서 자라나 햇빛을 꺼리는 것은?`n물에서는 가라앉고 공기와 함께 떠오르는 것은?`n살갗처럼 보이나 머리카락처럼 고운 것은?'),
    ('answer_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', '효모'),
    ('riddle_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', '꼬마 조니 워커,`n어찌나 말이 많던지!`n허나 한마디도 하지 않았다!`n내가 그를 꺼내 놓으면,`n모두가 손가락질하며 소리쳤다!`n그리고 도로 넣으라 청했다.'),
    ('answer_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', '의견'),
    ('riddle_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', '그들은 여럿이자 하나,`n흔들고 두드리며,`n시선을 가리는 데 쓰이고,`n어디든 너와 함께 간다.'),
    ('answer_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', '손'),
    ('riddle_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', '쿵, 쿵,`n우적, 우적,`n뛰고, 뛴다.`n가만히 선 채로,`n채비를 갖추고.'),
    ('answer_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', '말'),
    ('riddle_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', '단것을 좋아하는 이,`n아뿔싸,`n다 사라졌네,`n우리 모두 바라네,`n그 한 조각 더를.'),
    ('answer_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', '사탕'),
    ('riddle_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', '그것은 고양이 걸음으로 들어와,`n시지도 달지도 않다.`n공중에 머물다가,`n어느새 사라진다.'),
    ('answer_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', '안개'),
    ('riddle_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', '웃음 하나,`n울음 하나,`n신음 하나,`n한숨 하나.'),
    ('answer_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', '감정'),
    ('riddle_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', '네가 답해야 하는 것은 무엇인가?`n허나 답하려면 물어야 하고,`n묻자면 말해야 하며,`n말하자면 알아야 한다,`n그 답을.'),
    ('answer_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', '수수께끼'),
    ('riddle_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', '나는 네 눈을 때릴 수도 있고,`n하늘에서 반짝일 수도 있으며,`n죽을 때 부풀어 오른다.`n나는 무엇이겠는가?'),
    ('answer_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', '별'),
    ('riddle_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', '질척,`n철벅,`n씻고 싶어지고,`n머리에도 묻으며,`n볼품없게 만든다.'),
    ('answer_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', '진흙'),
    ('riddle_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', '언덕을 오르고,`n언덕을 내려가고,`n그 위를 두루 헤매도,`n온갖 걸음 끝에는,`n내 것만 한 곳이 없다.'),
    ('answer_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', '집'),
    ('riddle_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', '이것은 참으로 놀라운 것이다.`n칼처럼 날카로울 수도 있고,`n바닥처럼 평평할 수도 있다.`n허나 그 모든 것이면서도,`n벌처럼 자연스럽다.'),
    ('answer_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', '음악; 음표'),
    ('riddle_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', '깊이, 깊이 내려간다.`n가면서 사방으로 퍼진다.`n공기는 조금도 필요 없다.`n때로는 머리카락처럼 가늘다.'),
    ('answer_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', '뿌리'),
    ('riddle_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', '오 주여! 저는 합당치 않나이다!`n저는 가지를 땅으로 늘어뜨립니다.`n소리 없이 웁니다.`n깊은 물을 마시게 하소서.`n그리고 침묵 속에 울겠나이다.'),
    ('answer_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', '버드나무'),
    ('riddle_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', '옮기고, 옮기고, 깊이 흘러간다.`n내 아래에는 크고 강대한 도시들이 잠들어 있다.`n소용돌이치고, 서둘러 사방으로 간다.`n나는 오직 물이 없는 곳에만 있다.'),
    ('answer_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', '사막'),
    ('riddle_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', '나는 보글거리고 웃으며`n네 얼굴에 물을 뿜는다.`n나는 숙녀가 아니고,`n레이스도 두르지 않는다.'),
    ('answer_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', '분수'),
    ('riddle_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', '날개가 있으나`n날지 못하는 것은.`n둘러싸여 있으나`n바깥에도 놓일 수 있고.`n스스로 열 수도,`n스스로 닫을 수도 있다.`n왕과 왕비의 자리이며,`n온갖 삼류 시의 자리이기도 하다.`n내가 딛고 선 이것은 무엇인가?`n우리를 다른 땅으로 이끌 수 있는 것.'),
    ('answer_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', '무대'),
    ('riddle_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', '이를 원망하지 말라,`n모든 사람의 운명이니.`n허나 이는 두려움의 대상이고,`n많은 땅에서 기피된다.`n문제를 일으키고 때로는 빈틈을 만들며,`n가장 강한 자를 절뚝이게 하고 기억을 흐린다.`n우리 모두가 마주하는 이 위험은 무엇인가?`n인류의 일원이라는 이유로.'),
    ('answer_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', '늙음; 나이'),
    ('riddle_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', '이것을 나는 두 개 가지고 있다.`n하나는 나를 위해, 하나는 너를 위해.`n값을 묻거든,`n나는 그저 웃으며 두 번 고개를 끄덕인다.'),
    ('answer_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', '나눔'),
    ('riddle_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', '나는 기묘한 생물,`n공중에 떠서,`n이곳저곳 옮겨 다니며,`n눈부신 빛을 낸다.`n누구는 내가 노래한다 하고,`n누구는 목소리가 없다 한다.`n그래서 나는 그저 흥얼거린다 — 스스로 택하여.`n나는 무엇인가?'),
    ('answer_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', '벌새'),
    ('riddle_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', '낮에는 잠들어,`n나는 몸을 숨긴다.`n밤새 깨어 있다가,`n새벽빛에 나는 열린다.`n허나 아주 잠깐만,`n나는 빛난다.`n그러고는 다시 숨어,`n온종일 잠든다.'),
    ('answer_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', '나팔꽃'),
    ('riddle_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', '물처럼 보이나,`n그것은 열기다.`n모래 위에 앉고,`n콘크리트 위에 눕는다.`n사람들은 그것을 어디든`n따라간다고들 한다.`n허나 그것은 어디에도 데려다주지 않고,`n그저 바라보는 수밖에 없다.'),
    ('answer_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', '신기루'),
    ('riddle_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', '하늘의 한 조각,`n허나 땅에 닿는다.`n누구는 값지다 하고,`n누구는 아무 가치 없다 한다.'),
    ('answer_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', '무지개'),
    ('riddle_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', '나는 서서,`n바다를 건너다본다,`n물결과 마루와 골과 골짜기가 있는 그 바다를.`n나는 성큼성큼,`n이 물을 건너고, 내 말이 뒤따르며,`n물이 그 어깨를 찰싹이고,`n내 허벅지를 스칠 때,`n나는 웃음으로 공허를 채운다.`n그리고 그는 — 한숨으로.`n우리는 어디로 가는가?`n아니, 우리는 가기는 하는가?`n아니면 그저 여기서 물을 건너며,`n다음 기항지로 향하는 것인가.`n바다가 끝나는 곳,`n발밑에 흙이 단단해지는 곳,`n그곳에서 나는 다시 말에 올라,`n다음 만남까지 나아가리라.`n실제로 말하는 것은 무엇인가?'),
    ('answer_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', '드넓은 평원; 평원'),
    ('riddle_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', '나는 눈먼 채 태어나,`n보지 못했다,`n세 시 십오 분 전이 되기까지.`n나는 웃지 못했다,`n여섯 시 반이 되기까지,`n그리고 내 팔과 다리는 모두`n나뭇가지로 되어 있었다.'),
    ('answer_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', '인형'),
    ('riddle_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', '아! 내 숨이 떨리고,`n팔다리는 야위었으며,`n배가 아프다.`n흰빛이 내 머리를 덮고,`n내가 남긴 자취는,`n지나온 자리마다 흔들린다.`n흐릿한 눈으로 내다보며,`n마지막 작별을 고하는 듯하다.`n어둠이 나를 가까이 끌어당기니,`n더 잘 듣기 위해 나는 그리로 기운다.'),
    ('answer_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', '늙음; 나이'),
    ('riddle_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', '히커모어, 해커모어,`n임금님 부엌문 위에 있네.`n임금님의 말들도,`n임금님의 신하들도,`n히커모어 해커모어를`n임금님 부엌문에서 떼어 내지 못했네.'),
    ('answer_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', '햇빛'),
    ('riddle_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', '나로 무엇을 만들 수 있느냐 물으니,`n사람들은 나에게서 먹을 것을 얻었다.`n나로 무엇을 만들 수 있느냐 물으니,`n집이 세워졌다.`n나로 무엇을 만들 수 있느냐 물으니,`n글이 쓰였다.`n나로 무엇을 만들 수 있느냐 물으니,`n나는 땅을 기름지게 했다.`n허나 더 무엇을 만들 수 있느냐 물었을 때,`n남은 것은 아무것도 없었다.'),
    ('answer_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', '나무'),
    ('riddle_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', '이것으로 너는 놀라운 일을 할 수 있다.`n가까운 것도 먼 것도 볼 수 있고,`n큰 것도 볼 수 있으며,`n작은 것도 볼 수 있다.`n혹은 아무것도 보지 못할 수도 있다.`n나는 온갖 빛깔과 색조로 온다,`n때로는 초록, 때로는 파랑.`n내가 붉을 때는 부끄러워서가 아니라,`n다른 이름을 지닌 무언가 때문이다.'),
    ('answer_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', '눈'),
    ('riddle_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', '오, 나는 춤추는 내 발이 참 좋다!`n어찌나 가지런히 붙어 있는지.`n내가 한 줄로 걷고자 하면,`n모두가 함께 두 배로 빨리 움직인다.`n열 번도 넘게 세어 보고,`n바닥을 가로질러 내달린다.'),
    ('answer_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', '지네; 노래기'),
    ('riddle_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', '우리 안에서 웅얼거리는 소리가 들려,`n나는 걷다 멈춰 안을 들여다보았다.`n내가 본 것은 무엇이었나?`n거대한 짐승, 발굽과 턱을 지닌.`n당당한 이마에는 뿔이 돋아,`n그가 흙을 차며 서성이는 것을 보았다.`n허나 그 모든 위용에도 불구하고,`n그는 저 나무 울타리를 벗어나지 못했다.'),
    ('answer_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', '황소'),
    ('riddle_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', '그날 밤이었다,`n내가 겪은 일을`n전해야 하는 그날의.`n해가 나와 있었고`n소리 한 번 지르지 않은 채`n조용히 들어갔다.`n참으로 기이했다`n나는 그가 흘겨보리라 여겼으나`n한마디도 끼어들 수 없었다.`n또 한마디 없이`n(적어도 내가 들은 바로는)`n그는 있던 자리로 돌아갔다.'),
    ('answer_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', '일식'),
    ('riddle_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', '해 뜰 때부터 해 질 때까지 나는 바다를 바라본다.`n해 질 때부터 해 뜰 때까지 나는 바다를 바라본다.`n허나 해가 떠 있을 때는 그 밝음에 눈을 깜빡일 뿐이고,`n해가 지면 나는 밝음을 깜빡여 내보낸다.'),
    ('answer_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', '등대'),
    ('riddle_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', '요란하게 짖어 대지만,`n아무도 알아채지 못한다.`n물어뜯을 것은 많고,`n모두가 마음을 쓴다.`n나는 개가 아니다,`n혹 누가 알아챈다면.`n내게는 많은 것이 있으나,`n털은 없다.`n나는 곧게 서 있다,`n네가 나를 눈여겨보았다면.`n내게는 팔다리가 많다,`n누가 마음을 쓴다면.`n나는 그늘을 줄 수 있다,`n네가 알아챘다면.`n그리고 나는 그보다 더한 일도 한다,`n나는 네게 공기를 준다.'),
    ('answer_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', '나무'),
    ('riddle_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', '십이월이었는지 유월이었는지,`n내 마님이 기절하셨을 때.`n머리카락이 빠지고,`n안경이 사라졌을 때.`n그분이 비명을 지르셨을 때,`n참으로 볼썽사나운 모양으로.`n나를 가리키며,`n"꺄아아! 꺄아아!" 하시면서.`n좀 지나쳤다고 해야겠다,`n나는 아무도 건드리지 않았으니.`n허나 무언가 잘못되었음은`n분명해 보였다.`n그래서 나는 다른 날 다시 오기로 했다,`n혹시 그분이 안 계실 때에.'),
    ('answer_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', '쥐'),
    ('riddle_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', '나는 떠돈다,`n느릿한 강물처럼.`n나는 춤춘다,`n한 줄기 산들바람 위에서도.`n나는 구른다,`n가장 뛰어난 곡예사보다 더 잘.`n소용돌이치고,`n빙글거리며,`n땅으로 내려간다.`n그곳에 누워,`n두 번째 바람을 얻을 때까지.`n그리하여 나는 다시 시작한다.'),
    ('answer_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', '나뭇잎'),
    ('riddle_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', '쉽게 풀리는 수수께끼.`n붉은 가슴.`n여럿 가운데 오직 하나.`n알에서 태어났다.`n노래하도록 영감을 받았다.`n이제 글자를 모아 내 뜻을 말해 보라.'),
    ('answer_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', '울새'),
    ('riddle_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', '나는 이것을 넷 가지고 있고,`n끝마다 짝이 있다.`n그것들은 많은 일을 할 수 있고,`n좀처럼 나를 아프게 하지 않는다.`n핀으로 찌르거나,`n가끔 데지 않는 한은...`n내 마음대로 꼼지락거릴 수 있고,`n다른 데도 쓰는 이것은 무엇인가?'),
    ('answer_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', '손가락'),
    ('riddle_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', '그의 정열의 불꽃과`n그녀의 손길의 서늘함을 보았을 때,`n나는 그 결합에서 비극밖에 나올 수 없음을 알았다.`n과연 그들이 하나로 만났을 때,`n어둠이 땅을 다스렸다.`n곧 서로 갈라져,`n서로에게 맞지 않음을 깨달았지만,`n그럼에도 스치듯 주고받은 그 눈길은,`n그것을 목격한 모든 이에게 자국을 남겼고,`n앞으로 오래도록 회자될 것이다.'),
    ('answer_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', '일식'),
    ('riddle_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', '외투를 걸친 것은 무엇인가?`n동정심으로 껴안지 않는 것은?`n그 미소를 보고 싶지 않은 것은?`n그 자세가 보기만 해도 끔찍한 것은?`n용감한 자들이 달아나는 대상은 누구인가?`n손가락에 갈고리가 달린 것은?`n몇 달이나 잠자는 것은?`n그리고 우리가 그 곁을 피하는 것은?'),
    ('answer_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', '곰'),
    ('riddle_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', '그 위에서 구를 수도 있고,`n뒹굴 수도 있고,`n태울 수도 있고,`n짐승이 먹기도 하며,`n바닥에 깔기도 하고,`n마구간 문 너머에서도 여전히 쓰인다.`n놓인 자리를 무엇이든 산뜻하게 하고,`n부어진 것은 무엇이든 빨아들인다.`n그것은 무엇인가?'),
    ('answer_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', '건초'),
    ('riddle_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', '정열의 열매 안에서 그것들을 볼 수 있고,`n석류의 왕관 속에는 더 많다.`n사과의 속에는 줄지어 있으며,`n다른 열매에는 더 많기도 하다.`n천도복숭아에는 하나뿐이지만,`n이 모든 것은 그저 놀이일 뿐.`n숨바꼭질 — 아이들의 놀이.`n찾고 보면 참가자는 모두 같다.'),
    ('answer_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', '씨앗'),
    ('riddle_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', '천국에서 속삭여졌고, 지옥에서 중얼거려졌으며,`n메아리는 그 소리가 떨어질 때 희미하게 붙잡았다.`n땅의 경계에서는 쉬도록 허락되었고,`n바다의 깊은 곳에서도 그 존재가 드러났다.`n하늘이 갈라질 때 그 안에서 발견될 것이며,`n번개 속에서 보이고 천둥 속에서 들릴 것이다.`n사람에게는 첫 숨과 함께 주어졌고,`n태어날 때 곁에 있으며 죽을 때 기다린다.`n그의 행복과 명예와 건강을 주관하고,`n그의 집을 떠받치며, 그의 부의 끝이다.`n구두쇠의 더미 속에서는 애지중지 쌓이지만,`n방탕한 상속자에게서는 반드시 잃는다.`n모든 희망을 시작하고, 모든 소원을 매듭지으며,`n농부와 함께 수고하고, 군주와 함께 왕관을 쓴다.`n그것 없이 병사와 뱃사람은 떠돌 수 있으나,`n그것을 제 집에서 내쫓는 자에게는 화가 있으리라!`n양심의 속삭임 속에서 그 목소리가 들리고,`n격정의 회오리 속에서도 결코 묻히지 않는다.`n마음을 부드럽게 하고, 귀가 먹었을지라도,`n그를 또렷이 즉시 듣게 만든다.`n그늘에 두어, 섬세한 꽃처럼 쉬게 하라.`n아! 부드럽게 숨을 불어라, 한 시간이면 죽으리니'),
    ('answer_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', '글자 H; H'),
    ('riddle_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', '우리는 공기 같은 작은 것들,`n저마다 목소리와 생김이 다르다.`n하나는 유리(glass) 속에 있고,`n하나는 흑옥(jet)에서 찾을 수 있으며,`n또 하나는 주석(tin) 속에서 볼 수 있고,`n넷째는 상자(box) 안에 있다.`n다섯째를 좇는다면,`n그것은 결코 네게서 달아나지 못하리라.'),
    ('answer_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', '모음'),
    ('riddle_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', '나는 기묘한 모순이다. 나는 새것이자 헌것이고,`n종종 누더기이며, 자주 금으로 치장된다.`n나는 결코 읽지 못하나, 글자가 새겨져 있고,`n눈멀었으되 남을 밝히며, 헐거우면서도 묶여 있다.`n나는 언제나 검고, 언제나 희다.`n나는 엄숙하고 또 유쾌하며, 무겁고 또 가볍다 —`n형태도 제각각이다 — 나는 두껍고 또 얇으며,`n살도 뼈도 없으나 가죽으로 덮여 있다.`n나침반보다 많은 점을 지니고, 피리보다 많은 멈춤을 지녔다.`n나는 목소리 없이 노래하고, 말하지 않고 논박한다.`n나는 영국인이고, 독일인이고, 프랑스인이고, 네덜란드인이다.`n누구는 나를 지나치게 아끼고, 누구는 지나치게 업신여긴다.`n나는 종종 일찍 죽지만, 때로는 오래도록 산다.`n그리고 살아 있는 어느 군주도 나만큼 많은 시종(page)을 두지 못한다.'),
    ('answer_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', '책'),
    ('riddle_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', '내가 정원 문을 지날 때,`n만난 이가 붉은 모자 딕이 아니고 누구랴!`n손에는 막대, 목구멍에는 돌.`n이 수수께끼를 맞히면, 은화 한 닢 주리라.'),
    ('answer_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', '버찌'),
    ('riddle_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', '꼬마 낸시 에티코트,`n흰 속치마를 입고,`n붉은 코를 하고 있네.`n오래 서 있을수록`n키가 줄어드네.'),
    ('answer_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', '초'),
    ('riddle_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', '내게 작은 누이가 있는데, 다들 그녀를 삐약삐약이라 부른다.`n그녀는 깊고 깊고 깊은 물을 건너고,`n높고 높고 높은 산을 오른다.`n가엾은 것, 그녀에게는 눈이 하나뿐이라네.'),
    ('answer_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', '별'),
    ('riddle_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', '나는 한 무리가 행진하는 것을 보았다,`n바다를 가로질러 행진하는 것을.`n그들을 바라보며,`n나는 스스로에게 물었다 "저것들은 무엇일까?"`n말이 한 마리 있었고,`n소도 한 마리 있었으며,`n사람들이 행진하고 있었다,`n집과 나무를 데리고. 그런데 어떻게?`n나는 한 무리가 행진하는 것을 보았다,`n바다를 가로질러 행진하는 것을.`n그리고 쉬면서 생각했다,`n나는 어지간히도 게으르구나.'),
    ('answer_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', '하늘의 구름; 구름'),
    ('riddle_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', '나는 위에 있다.`n나는 아래에 있다.`n나는 사방에 있다.`n허나 결코 붙잡히지 않는다.`n나는 누구인가?'),
    ('answer_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', '바람'),
    ('riddle_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', '나는 옮겨질 수 있다.`n나는 굴려질 수 있다.`n허나 나는 아무것도 담지 않는다.`n나는 붉고 또 푸르다.`n다른 빛깔일 수도 있다.`n머리는 없으나 모양은 비슷하고,`n눈도 없으나 사방을 돌아다닌다.`n나는 무엇인가?'),
    ('answer_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', '공'),
    ('riddle_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', '너는 내 위를 밟을 수 있다,`n덮개 아래로 부드럽게.`n그리고 나는 너를 데려가리라,`n아직 발견하지 못한 곳으로.`n나는 높고, 또 낮으며,`n가운데는 평평하다.`n아이들에게는 기쁨이지만,`n어른들은 나를 대수롭지 않게 여긴다.`n나는 무엇인가?'),
    ('answer_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', '계단'),
    ('riddle_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', '무엇이 것들을 세우고,`n산을 낮추며,`n호수를 마르게 하고,`n자라나게 하는가?`n네가 스러지는 것에는 조금도 개의치 않고,`n다른 어떤 것과도 다른 까닭은,`n그것이 영원하기 때문이다.'),
    ('answer_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', '시간'),
    ('riddle_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', '그것은 버드나무 위에 앉아,`n내게 나직이 노래했다.`n그 노래로 내 아픔과 슬픔을 달래니,`n나는 날고 싶었으나 오래 머물렀다.`n그리고 내 괴로움 속에서,`n버드나무는 서늘하고 맑은 샘 같았다.`n나를 그토록 도운 것은 무엇이었나?`n내 시름의 시간을 함께 보내 준 것은.'),
    ('answer_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', '새'),
    ('riddle_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', '그것들은 품을 수 있으나, 물을 담는 것은 드물고,`n키울 수 있으나, 오직 남에게 들이대야만 하며,`n지고 다닐 수 있으나, 팔로는 아니고,`n묻을 수 있으나, 땅에는 아니다.'),
    ('answer_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', '원한'),
    ('riddle_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', '사발처럼 깊고, 잔처럼 둥글지만,`n세상의 모든 바다로도 채울 수 없다.'),
    ('answer_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', '체'),
    ('riddle_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', '사막의 사람들은 한때 나를 신이라 불렀으나,`n오늘날 사람들은 나를 미쳤다 한다.`n나는 화가 나면 꼬리를 흔들고,`n기쁘면 으르렁대기 때문이다.'),
    ('answer_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', '고양이'),
    ('riddle_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', '나는 침략하여 정복하는 군대의 소문을 들었다.`n물처럼 빠르게 땅을 휩쓸며,`n모든 것을 정복하고 저항을 잠재웠다.`n그와 함께 어둠이 와 빛을 흐렸다.`n사람들은 집에 숨었고, 바깥에서는`n창들이 꿰뚫어 돌담을 부수었다.`n헤아릴 수 없는 병사들이 땅에 부딪혀 부서졌으나,`n저마다 죽으면서 생명을 불러냈다.`n군대가 북쪽으로 나아가 사라졌을 때,`n땅은 푸르게 자라나 되살아나 있었다.'),
    ('answer_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', '비바람; 비'),
    ('riddle_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '"나는 볼 수 없는 것을 찾을 수 있고, 찾을 수 없는 것을 볼 수 있다.`n앞의 것은 시간이고, 뒤의 것은 내 눈앞의 반점이다."'),
    ('answer_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '시간'),
    ('riddle_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', '나는 만질 수 없는 것을 느낄 수 있고, 느낄 수 없는 것을 만질 수 있다.`n앞의 것은 슬프고 애처로우며, 뒤의 것은 네 심장이다.'),
    ('answer_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', '심장'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', '결코 앞서지 않고 늘 뒤에 있으나,`n쏜살같이 스쳐 지나간다.`n아이에게 나는 영원하고,`n어른에게 나는 너무 빨리 사라진다.'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', '젊음'),
    ('riddle_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', '그녀는 키가 크고, 잔처럼 둥글지만,`n임금님의 말들을 다 동원해도`n그녀를 끌어올릴 수 없다.'),
    ('answer_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', '우물'),
    ('riddle_text', 'There more of it there is,`nThe less you see.', '그것이 많을수록,`n너는 덜 보게 된다.'),
    ('answer_text', 'There more of it there is,`nThe less you see.', '어둠'),
    ('riddle_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', '하나에게는 모자라고,`n둘에게는 알맞으며,`n셋에게는 지나친 것은?'),
    ('answer_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', '비밀'),
    ('riddle_text', 'What gets wetter the more it dries?', '마를수록 더 젖는 것은?'),
    ('answer_text', 'What gets wetter the more it dries?', '수건'),
    ('riddle_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', '긴 뱀 한 마리,`n쏘는 듯한 무는 힘,`n나는 감겨 있으리라`n싸워야 할 때가 아니라면.'),
    ('answer_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', '채찍'),
    ('riddle_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', '꽃들 사이의 전사,`n그는 찌르는 검을 지녔다.`n쓸 준비가 되어 있고 능하니,`n제 황금 곳간을 지키기 위함이다.'),
    ('answer_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', '벌'),
    ('riddle_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', '짐을 지는 자, 전사,`n겁먹은 자, 용감한 자,`n발 빠른 자, 쇠를 신은 자,`n충직한 자, 노예.'),
    ('answer_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', '말'),
    ('riddle_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', '바람 속을 걷고`n비 속을 달리며`n볕 아래 마른 바다를 만든다.`n시간을 세고, 시계를 멈추며,`n왕국을 삼키고, 바위를 갉는다.'),
    ('answer_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', '모래'),
    ('riddle_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', '구르는 언덕, 영원히 뛰는 심장,`n결코 변하지 않고 결코 멈추지 않는 땅,`n집을 떠난 나그네들이 갈아엎으나, 씨는 뿌리지 않는다.`n노하면 희고, 평온하면 푸르며, 언제나 파랗다.'),
    ('answer_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', '바다'),
    ('riddle_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', '귀 기울여 들어라, 나는 알기 어렵다.`n나는 한 줌 모래처럼 붙잡기 어렵다.`n나를 알아차린다 해도, 너는 나를 알지 못한다.`n내가 무엇을 잊었는지 네가 말하기 전에는.'),
    ('answer_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', '수수께끼'),
    ('riddle_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', '무엇이 문을 지나면서도 제 몸을 끼이지 않는가?`n무엇이 화덕 위에 앉아도 제 몸을 태우지 않는가?`n무엇이 식탁 위에 앉고도 부끄러워하지 않는가?'),
    ('answer_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', '해'),
    ('riddle_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', '내가 앉아 있는 동안`n죽은 것이 산 것을 나르는 것을 보았다.`n내가 본 것은 무엇인가?'),
    ('answer_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', '배'),
    ('riddle_text', 'I know a word of letters three,`nAdd two and fewer there will be.', '나는 글자 셋짜리 낱말을 안다.`n둘을 더하면 더 적어진다.'),
    ('answer_text', 'I know a word of letters three,`nAdd two and fewer there will be.', '적음'),
    ('riddle_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', '만든 자는 그것이 필요 없고,`n산 자는 그것을 쓸 데가 없으며,`n쓰는 자는 그것을 보지도 느끼지도 못한다.'),
    ('answer_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', '관'),
    ('riddle_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', '그것을 만든 자는 그것이 필요 없었다.`n그것을 산 자는 그것을 쓰지 않았다.`n그것을 쓴 자는 그것을 원하지 않았다.'),
    ('answer_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', '관'),
    ('riddle_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', '너는 나를 붙잡았으나 나는 달아났다.`n너는 내가 달아나는 것을 보고도 붙들지 못한다.`n손에 나를 쥐면, 주먹은 비어 있다.`n나는 무엇인가?'),
    ('answer_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', '눈'),
    ('riddle_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', '아침에는 네 다리,`n낮에는 두 다리,`n저녁에는 세 다리인 것은?'),
    ('answer_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', '사람'),
    ('riddle_text', 'What is deaf, dumb and blind`nand always tells the truth ?', '귀먹고 말 못 하고 눈멀었으나`n언제나 진실을 말하는 것은?'),
    ('answer_text', 'What is deaf, dumb and blind`nand always tells the truth ?', '거울'),
    ('riddle_text', 'What is always in front of you`nbut cannot be seen?', '언제나 네 앞에 있으나`n볼 수 없는 것은?'),
    ('answer_text', 'What is always in front of you`nbut cannot be seen?', '미래'),
    ('riddle_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', '사람이 목숨보다 더 사랑하고,`n죽음이나 죽을 만한 다툼보다 더 미워하는 것,`n만족한 자가 바라는 것,`n가난한 자는 가졌고 부유한 자는 필요로 하는 것,`n구두쇠는 쓰고 낭비가는 아끼는 것,`n그리고 모든 사람이 무덤까지 가져가는 것은?'),
    ('answer_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', '아무것도 아닌 것'),
    ('riddle_text', 'A life longer than any man,`nit dies each year to be reborn.', '어떤 사람보다도 긴 생명,`n해마다 죽어 다시 태어난다.'),
    ('answer_text', 'A life longer than any man,`nit dies each year to be reborn.', '나무'),
    ('riddle_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', '눈에는 멀게 하고,`n코에는 그저 재채기를 일으키나,`n어떤 이들은 이것을 빨아들이고,`n마치 기쁜 듯 군다.'),
    ('answer_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', '연기'),
    ('riddle_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', '그것은 뼈도 굳은 형체도 없이 홀로 선다.`n단호하여 결코 그르치는 법이 없으나,`n상처를 줄 수는 있다.`n비틀 수도, 주무를 수도 있으나,`n언제나 화살처럼 곧다.'),
    ('answer_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', '진실'),
    ('riddle_text', 'What sphinxes employ,`nthe players enjoy.', '스핑크스가 부리는 것,`n놀이하는 이들이 즐기는 것.'),
    ('answer_text', 'What sphinxes employ,`nthe players enjoy.', '수수께끼'),
    ('riddle_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', '내가 늘 곁에 있는 이가 있으나,`n어둠 속에서 나는 사라진다.`n오직 그에게만 나는 충실하며,`n그의 뒤에서 애쓰도록 정해져 있다.`n그는 나를 느끼지 못한다(우리는 늘 맞닿아 있건만).`n내가 사라져도 그는 잃을 것이 별로 없다.`n그리고 이제 놀라운 대목에 이른다,`n그가 바로 너이니 — 그렇다면 나는 누구인가?'),
    ('answer_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', '그림자'),
    ('riddle_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', '나는 자주 붙들리나 좀처럼 만져지지 않고,`n늘 젖어 있으나 결코 녹슬지 않으며,`n때로는 흔들리고 때로는 물린다.`n나를 잘 쓰려면 재치가 있어야 한다.'),
    ('answer_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', '혀'),
    ('riddle_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', '창가에 앉아 그녀는 울었다.`n그리고 눈물 한 방울마다 그녀의 생명이 스며 나갔다.'),
    ('answer_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', '초'),
    ('riddle_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', '나는 사실 구멍에 구멍을 이어 놓은 것에`n지나지 않는다.`n좋은 강철만큼 튼튼하나, 장대만큼`n뻣뻣하지는 않다.'),
    ('answer_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', '사슬'),
    ('riddle_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', '나는 힘은 약하나 권능은 크다.`n작은 오두막도 큰 탑도 지킨다.`n허나 혹여 내 주인이 떠난다면,`n그는 반드시 나를 잘 간수해야 한다.'),
    ('answer_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', '열쇠'),
    ('riddle_text', 'Delivered by breath,`nscares heroes to death.', '숨결로 전해져,`n영웅들을 죽도록 겁준다.'),
    ('answer_text', 'Delivered by breath,`nscares heroes to death.', '수수께끼'),
    ('riddle_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', '낮에는 웅덩이처럼 고여 있고,`n밤에는 안개처럼 뒤덮는다.`n닫힌 상자 속으로도 기어들고`n네 꽉 쥔 주먹 안에도 든다.`n볼 수 없을 때 나를 가장 잘 보나니,`n나는 존재하지 않기 때문이다.'),
    ('answer_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', '어둠'),
    ('riddle_text', 'Devils and rogues know nothing else,`nsave starlight.', '악마와 악당들은 별빛 말고는`n아무것도 알지 못한다.'),
    ('answer_text', 'Devils and rogues know nothing else,`nsave starlight.', '어둠'),
    ('riddle_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', '왕도 말도 이것을 지니고 있으나,`n너는 그 어느 쪽도 원하지 않으리라.'),
    ('answer_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', '치세; 고삐'),
    ('riddle_text', 'My spring up on the cliff.', '벼랑 위의 내 샘.'),
    ('answer_text', 'My spring up on the cliff.', '코코넛'),
    ('riddle_text', 'Three walls and you reach water.', '벽 셋을 지나면 물에 닿는다.'),
    ('answer_text', 'Three walls and you reach water.', '코코넛'),
    ('riddle_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', '쉼 없이 언제나 울리는`n내 카파(천의 일종) 통나무.'),
    ('answer_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', '바다'),
    ('riddle_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', '아침에는 네 다리,`n낮에는 두 다리,`n저녁에는 세 다리.'),
    ('answer_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', '사람'),
    ('riddle_text', 'My man that cannot be cut.', '벨 수 없는 나의 사내.'),
    ('answer_text', 'My man that cannot be cut.', '그림자'),
    ('riddle_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', '밤낮으로 나아가는 내 카누들,`n이물은 열, 고물은 둘.'),
    ('answer_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', '사람의 두 발'),
    ('riddle_text', 'My red cave, white soldiers standing in line.', '내 붉은 동굴, 흰 병사들이 줄지어 서 있다.'),
    ('answer_text', 'My red cave, white soldiers standing in line.', '사람의 입'),
    ('riddle_text', 'My man crying day and night,`nall through the year.', '밤낮으로 우는 나의 사내,`n한 해 내내.'),
    ('answer_text', 'My man crying day and night,`nall through the year.', '바다')
  ) AS source
  JOIN riddle ON riddle.riddle_text = source.column2;

DELETE FROM catalog_translation WHERE entity_type = 'riddle' AND locale_code = 'ja';

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'riddle', riddle.riddle_id, source.column1, 'ja', source.column3
  FROM (VALUES
    ('riddle_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', 'お前は植えも耕しもせぬものを食う。`nそれは水の子だが、水に触れれば死ぬ。'),
    ('answer_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', '塩'),
    ('riddle_text', 'Teacher, open thy book.', '師よ、汝の書を開け。'),
    ('answer_text', 'Teacher, open thy book.', '蝶'),
    ('riddle_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', '我が枝は長い。`n我が枝は短い。`n我が枝は終わる`n最初の報せが届く前に。'),
    ('answer_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', '稲妻; 雷'),
    ('riddle_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', '我らを裏返し`n腹を開いてみよ`n汝は最も賢き者となろう`n初めは愚か者であったとしても。'),
    ('answer_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', '本'),
    ('riddle_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', '深く埋め`n石を積め、`nそれでも我は`n骨を掘り返す。'),
    ('answer_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', '記憶'),
    ('riddle_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', 'それは一分ごとに一度現れ`n一瞬ごとに二度現れるが`n十万年のうちには一度も現れぬ。'),
    ('answer_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', '文字のM; M'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', '決して先を行かず、常に後ろにありながら、`n矢のように過ぎ去る。`n子にとって我は永遠であり、`n大人にとって我は去るのが早すぎる。'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', '子供時代'),
    ('riddle_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', '最も速く駆ける二頭の馬、`n一対に繋がれながら、`n常に己から遠い場所で`n草を食む。'),
    ('answer_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', '両の目; 太陽と月'),
    ('riddle_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', 'こう言える。`n金であれば善であり、`n石であれば無であり、`nガラスであれば脆く、`n冷たければ残酷である、と。`n比喩を剥げば、我は何か。'),
    ('answer_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', '心臓'),
    ('riddle_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', '丸くありながら板のように平たく`n狼の君主たちの祭壇。`n黒天鵞絨の宝石、海の真珠、`n変わらずして永遠に変わりゆくもの。'),
    ('answer_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', '月'),
    ('riddle_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', 'それは黄金の頭を持ち`n黄金の尾を持つが`n胴体を持たぬ。'),
    ('answer_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', '金貨; 硬貨'),
    ('riddle_text', 'Speak, friend, and enter!', '友よ、唱えて入れ！'),
    ('answer_text', 'Speak, friend, and enter!', '友'),
    ('riddle_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', '革のような蛇、`n刺すような噛みつき、`n我は巻いたままでいよう、`n戦わねばならぬ時でなければ。'),
    ('answer_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', '鞭'),
    ('riddle_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', '誰にも見えぬ根を持ち、`n木より高く、`n上へ上へと伸びながら、`n決して育たぬものは何か。'),
    ('answer_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', '山'),
    ('riddle_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', '赤い丘の上の三十頭の白馬、`nまず噛み、`n次に踏みつけ、`nそれから静かに立つ。'),
    ('answer_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', '歯'),
    ('riddle_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', '声なくして叫び、`n翼なくして舞い、`n歯なくして噛み、`n口なくして呟く。'),
    ('answer_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', '風'),
    ('riddle_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', '見えもせず、触れもせず、`n聞こえもせず、匂いもせぬ。`n星の後ろに横たわり、丘の下にあり、`n空の穴を満たす。`n最初に来て後から従い、`n命を終わらせ、笑いを殺す。'),
    ('answer_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', '闇'),
    ('riddle_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', '蝶番も鍵も蓋もない箱、`nそれでも中に黄金の宝が隠されている。'),
    ('answer_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', '卵; オレンジ'),
    ('riddle_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', '息なくして生き、`n死のごとく冷たく、`n渇きを知らぬのに常に飲み、`n鎧を纏いながら鳴らぬ。'),
    ('answer_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', '魚'),
    ('riddle_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', 'これはあらゆるものを食らう。`n鳥、獣、木、花、`n鉄を齧り、鋼を噛み、`n硬い石を粉にし、`n王を殺し、町を滅ぼし、`n高き山を打ち崩す。'),
    ('answer_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', '時'),
    ('riddle_text', 'You feel it, but never see it and never will.', '感じることはできるが、決して見えず、これからも見えぬ。'),
    ('answer_text', 'You feel it, but never see it and never will.', '心臓'),
    ('riddle_text', 'You must keep it after giving it.', '与えた後も守らねばならぬもの。'),
    ('answer_text', 'You must keep it after giving it.', '約束'),
    ('riddle_text', 'As light as a feather, but you can''t hold it for ten minutes.', '羽のように軽いが、十分と持ってはいられない。'),
    ('answer_text', 'As light as a feather, but you can''t hold it for ten minutes.', '息'),
    ('riddle_text', 'Has a mouth but does not speak, has a bed but never sleeps.', '口はあるが語らず、床はあるが決して眠らぬ。'),
    ('answer_text', 'Has a mouth but does not speak, has a bed but never sleeps.', '川'),
    ('riddle_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', 'いかなる韻よりも滑らかに流れ、落ちるのを好むが登れぬ！'),
    ('answer_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', '水'),
    ('riddle_text', 'You break it even if you name it!', '名を口にしただけで壊れてしまう！'),
    ('answer_text', 'You break it even if you name it!', '沈黙'),
    ('riddle_text', 'It passes before the sun and makes no shadow.', '太陽の前を過ぎても影を作らぬ。'),
    ('answer_text', 'It passes before the sun and makes no shadow.', '空気'),
    ('riddle_text', 'You feed it, it lives, you give it something to drink, it dies.', '食わせれば生き、飲ませれば死ぬ。'),
    ('answer_text', 'You feed it, it lives, you give it something to drink, it dies.', '火'),
    ('riddle_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', '赤い太鼓が`n触れられずして鳴り、`n触れられると`n静まる。'),
    ('answer_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', '心臓'),
    ('riddle_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', '同じ日に蒔かれ刈られる収穫、`n耕されぬ野に生じ、`n育たずして増え、`n内も外も食われながら`n丸ごと残り、`n役に立たぬのに`n国々の主食である。'),
    ('answer_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', '戦争'),
    ('riddle_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', '我を砕いても`n我は働きを止めず、`n我に触れれば`n我は罠にかかるやもしれず、`n我を失えば`n何もかも意味を持たぬ。'),
    ('answer_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', '希望'),
    ('riddle_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', '至る所にあるが見えず、`n捕らえられるが握れず、`n喉はないが聞こえる。'),
    ('answer_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', '音; 物音'),
    ('riddle_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', '我は円を描いて回るが、`n常にまっすぐ前へ進む。`nどこへ導かれようとも、`n決して不平を言わぬ。'),
    ('answer_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', '車輪'),
    ('riddle_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', '我を成すものより`n我は軽く、`n見えるものより`n隠れた部分のほうが多い。'),
    ('answer_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', '氷山'),
    ('riddle_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', '人が我が荷を負えば、`n背を折るだろう。`n我は富んではおらぬが、`n通った跡に銀を残す。'),
    ('answer_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', 'かたつむり'),
    ('riddle_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', '我が命は時間で測られ、`n食われることで仕えを果たす。`n細ければ我は速く`n太ければ我は遅い`n風は我が敵だ。'),
    ('answer_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', '蝋燭'),
    ('riddle_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', '腹には重み、`n背には木々、`n肋には釘、`n足はない。'),
    ('answer_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', '船; 洞窟'),
    ('riddle_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', '我が顔を覗けば`n他には何も見えぬ。`n我は汝の目を見つめ`n決して偽らぬ。'),
    ('answer_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', '鏡'),
    ('riddle_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', '我は常に飢えており、`n絶えず食わせねばならぬ。`n我が舐めた指は`nじきに赤くなる。'),
    ('answer_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', '火'),
    ('riddle_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', '我は三つの命を持つ。`n肌を宥めるほど優しく、`n空を撫でるほど軽く`n岩を割るほど硬い。'),
    ('answer_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', '水'),
    ('riddle_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', '下へ突き刺す`n煌めく穂先、`n決して錆びぬ`n輝く槍。'),
    ('answer_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', 'つらら'),
    ('riddle_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', '朝ごとに我は現れ`n汝の足元に横たわり、`n一日中付き従い`nどれほど速く走ろうと離れぬが、`n真昼の陽の下では`n消え入りそうになる。'),
    ('answer_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', '影'),
    ('riddle_text', 'Keys without locks`nYet I unlock the soul.', '錠のない鍵たちだが`n我は魂を開く。'),
    ('answer_text', 'Keys without locks`nYet I unlock the soul.', 'ピアノ; チェンバロ'),
    ('riddle_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', '我はいたって単純で、`n指し示すことしかできぬが`n世界中の人々を`n導く。'),
    ('answer_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', '羅針盤'),
    ('riddle_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', '我らの甘露ゆえに我らは`nユピテルより死の針を賜った。`n我らの力を笑う者もあろうが、`n我らは竜の息を鎮めたことがある。`n我らは何者か。'),
    ('answer_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', '蜂'),
    ('riddle_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', '乙女の頬のごとく色づき、`n我が始まりの時、時はまだ無かった。`n園を抜けて忍び込み、`n我ひとりが人の堕落となった。`n我は何か。'),
    ('answer_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', '林檎'),
    ('riddle_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', '無いはずの所に一つ、`nあるいは二つあるべき所に、`n純潔を求めて`n王の森をさまよう。`n我は何か。'),
    ('answer_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', 'ユニコーン'),
    ('riddle_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', '噛む歯が一つ、`n彼は森の敵。`n戦う歯が一つ、`n北欧の者は皆知っている。`nそれは何か。'),
    ('answer_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', '斧'),
    ('riddle_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', '空にはない`n鳥の一部、`n海を泳げるのに`n常に濡れぬもの。`nそれは何か。'),
    ('answer_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', '鳥の影; 影'),
    ('riddle_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', '根が幹の上にある`nこの逆さまのもの、`n冬に育ち`n春に死ぬ。`nそれは何か。'),
    ('answer_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', 'つらら'),
    ('riddle_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', '一つに触れながら二つを抱き、`n一環の鎖となって`n言葉を守る者たちを結ぶ、`n死が二つに裂くまで。`nそれは何か。'),
    ('answer_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', '結婚指輪; 指輪'),
    ('riddle_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', '賢く物知りな者はそれを確信している。`n愚者でさえそれを知っている。`n富める者はそれを欲する。`n最も偉大な英雄もそれを恐れる。`nしかし最も卑しい臆病者もそれのために死ぬだろう。`n我が思い巡らすこれは何か。'),
    ('answer_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', '無; 何か'),
    ('riddle_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', '神より大きく、`n悪魔より悪く、`n死者はそれを食い、`n食えば死ぬものは何か。'),
    ('answer_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', '無'),
    ('riddle_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', '我は女たちの見事な助けであり、`n来たるべきものの希望である。我は`n我を屠る者のほかは誰も傷つけぬ。`n根を張り高き床に立ち、`n下は毛深い。時に美しい`n農夫の娘、腕まくりした`n誇り高き女が我が身を掴み、`n赤い皮を剥ぎ、固く握り、`n我が頭を奪う。巻き毛の`n女が我をしかと捕らえれば、その出会いを感じよう。`n彼女の目は濡れるだろう。'),
    ('answer_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', '玉ねぎ'),
    ('riddle_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', '君主が握る力にして宝、`n硬く険しい頬を持ち、赤き`n金と柘榴石に包まれ、明るい花々の`n野から引き裂かれ、火と鑢の名残として`n鍛えられ、繊細な針金で峻厳な美に結ばれた。`n我が握りは戦士を泣かせ、我が刺は`n黄金を掴む手を脅かす。環を`n嵌められ、我は世継ぎと家宝を蹂躙する。`n我が主にも敵にも常に麗しく`n致命的で、顔と姿を変えていく。'),
    ('answer_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', '剣'),
    ('riddle_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', '我がセント・アイヴスへ行く途中、`n七人の妻を持つ男に出会った。`n妻はそれぞれ七つの袋を持ち、`n袋にはそれぞれ七匹の猫がおり、`n猫にはそれぞれ七匹の子がいた。`n子と猫と袋と妻たち、`nセント・アイヴスへ行くのは幾人だったか。'),
    ('answer_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', '一人'),
    ('riddle_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', '暁は去り、`n日は灰色に変わり、`n我は遠くへ旅立たねばならぬ。`nされど我は戻り、`nその時我らは追うだろう、`nまた新たな一日の光を。'),
    ('answer_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', '太陽; 影'),
    ('riddle_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', '深く、暗く、地の底、`nそこが我の見つかる場所。`nされど陽の光に運び出されれば、`n我は四方八方に光を撒く。`n油に曇らされて見つかろうとも、`n我は驚くほど無傷で堅固だ。`n素早く我を削ってみれば分かる、`n我が忽ち見事な輝きを帯びることが。'),
    ('answer_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', 'ダイヤモンド; 宝石'),
    ('riddle_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', '竈にありながら焼かれぬものは何か。`n熱の中で育ちながら日の光を避けるものは。`n水では沈み、空気と共に上がるものは。`n肌のように見えながら髪のように細いものは。'),
    ('answer_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', 'イースト菌'),
    ('riddle_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', '小さなジョニー・ウォーカー、`nおや、よく喋ること！`nだが一言も言わなかった！`n我が彼を取り出すと、`n皆が指差して叫んだ！`nそしてしまうよう頼んだ。'),
    ('answer_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', '意見'),
    ('riddle_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', 'それらは多くして一つ、`n振られ、叩き、`n視線を遮るのに使われ、`nどこへでも汝と共に行く。'),
    ('answer_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', '両手'),
    ('riddle_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', 'どすん、どすん、`nもぐもぐ、もぐもぐ、`n跳ね、跳ねる。`nじっと立ったまま、`n支度を整えて。'),
    ('answer_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', '馬'),
    ('riddle_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', '甘いもの好き、`nああ残念、`nもう無くなった、`n皆が望む、`nもう一切れを。'),
    ('answer_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', '菓子'),
    ('riddle_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', 'それは猫の足取りで訪れ、`n酸くも甘くもない。`n宙に漂い、`nそして消えている。'),
    ('answer_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', '霧'),
    ('riddle_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', '笑い一つ、`n泣き一つ、`n呻き一つ、`nため息一つ。'),
    ('answer_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', '感情'),
    ('riddle_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', '汝が答えねばならぬものは何か。`nされど答えるには問わねばならず、`n問うには語らねばならず、`n語るには知らねばならぬ、`nその答えを。'),
    ('answer_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', '謎かけ'),
    ('riddle_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', '我は汝の目を打つこともでき、`n空で瞬くこともでき、`n死ぬときには膨れ上がる。`n我は何だと思う。'),
    ('answer_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', '星'),
    ('riddle_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', 'ぐちゃり、`nべちゃり、`n洗いたくなり、`n髪にもつき、`n見栄えを損なう。'),
    ('answer_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', '泥'),
    ('riddle_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', '丘を登り、`n丘を下り、`nその上を巡り歩けど、`n歩き尽くした後には、`n我が家に勝る所はない。'),
    ('answer_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', '我が家'),
    ('riddle_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', 'これは実に驚くべきものだ。`nナイフのように鋭くもなれば、`n床のように平らにもなる。`nそしてそのすべてでありながら、`n蜂のように自然である。'),
    ('answer_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', '音楽; 音符'),
    ('riddle_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', '深く、深く下りていく。`n進むにつれ広がっていく。`n空気を必要とせぬ。`n時に髪のように細い。'),
    ('answer_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', '根'),
    ('riddle_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', 'おお主よ！ 我は値せぬ者！`n我は枝を地に垂れる。`n我は声もなく泣く。`n深き水を飲ませたまえ。`nそして沈黙のうちに我は嘆こう。'),
    ('answer_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', '柳'),
    ('riddle_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', '移ろい、移ろい、深く流れる。`n我が下には大いなる都が眠る。`n渦を巻き、慌ただしく、四方に散る。`n我は水なき所にのみある。'),
    ('answer_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', '砂漠'),
    ('riddle_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', '我は泡立ち笑い`n汝の顔に水を吐く。`n我は淑女ではなく、`nレースも纏わぬ。'),
    ('answer_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', '噴水'),
    ('riddle_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', '翼はあるが`n飛べぬもの。`n囲まれているが`n外にも横たわりうる。`n自ら開くこともでき、`n自ら閉じることもできる。`n王と女王の座であり、`nあらゆる駄詩の座でもある。`n我が立つこれは何か。`n我らを異なる地へ導きうるもの。'),
    ('answer_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', '舞台'),
    ('riddle_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', 'これを恨むな、`n万人の定めなのだから。`nされどこれは恐れられ、`n多くの地で忌まれる。`n厄介事を招き、時に隙間を作り、`n最も強き者を躓かせ、記憶を途切れさせる。`n我ら皆が向き合うこの危険は何か。`n人類の一員である以上。'),
    ('answer_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', '老い; 年齢'),
    ('riddle_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', 'これを我は二つ持っている。`n一つは我に、一つは汝に。`n値を尋ねられれば、`n我はただ微笑んで二度頷く。'),
    ('answer_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', '分かち合い'),
    ('riddle_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', '我は奇妙な生き物、`n宙に浮かび、`nあちらこちらへ移り、`n目も眩む輝きを放つ。`n我が歌うと言う者もあれば、`n声を持たぬと言う者もある。`nゆえに我はただ唸る — 己の選びとして。`n我は何か。'),
    ('answer_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', 'ハチドリ'),
    ('riddle_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', '昼は眠り、`n我は身を隠す。`n夜通し目を覚まし、`n暁の光に我は開く。`nされどほんの束の間だけ、`n我は輝く。`nそしてまた身を隠し、`n昼の間ずっと眠る。'),
    ('answer_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', '朝顔'),
    ('riddle_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', '水のように見えるが、`nそれは熱。`n砂の上に座り、`nコンクリートに横たわる。`n人はそれをどこまでも`n追うと言われる。`nだがそれはどこへも導かず、`nただ眺めるほかない。'),
    ('answer_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', '蜃気楼'),
    ('riddle_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', '天の一部でありながら、`n地に触れる。`n値打ちがあると言う者もあれば、`n何の値打ちもないと言う者もある。'),
    ('answer_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', '虹'),
    ('riddle_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', '我は立ち、`n海を見渡す、`n波と峰と谷間のあるその海を。`n我は大股に、`nこの水を渡り、我が馬が後に続き、`n水がその肩を打ち、`n我が腿をかすめる間、`n我は虚ろを笑いで満たす。`nそして彼は — ため息で。`n我らはどこへ行くのか。`nそもそも行くのか。`nそれともただここで水を渡り、`n次の寄港地へ向かうだけか。`n海の尽きる所、`n足の下に土が固く敷かれる所、`nそこで我は再び馬に跨り、`n次に会うまで進み続けよう。`n実際に語られているのは何か。'),
    ('answer_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', '広大な平原; 平原'),
    ('riddle_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', '我は盲いて生まれ、`n見ることができなかった、`n三時十五分前になるまでは。`n我は微笑めなかった、`n六時半になるまでは、`nそして我が腕も脚も皆`n小枝でできていた。'),
    ('answer_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', '人形'),
    ('riddle_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', 'ああ！ 我が息は震え、`n手足は痩せ細り、`n腹が痛む。`n白きものが我が頭を覆い、`n我が残す足跡は、`n通った所ごとに覚束ない。`n濁った目で外を見つめ、`n最後の別れを告げるかのようだ。`n闇が我を近くへ引き寄せ、`n我はよりよく聞こうとそちらへ傾く。'),
    ('answer_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', '老い; 年齢'),
    ('riddle_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', 'ヒッカモア、ハッカモア、`n王様の台所の扉の上。`n王様の馬をみな連れても、`n王様の家来をみな集めても、`nヒッカモア・ハッカモアを`n王様の台所の扉から外せなかった。'),
    ('answer_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', '日の光'),
    ('riddle_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', '我から何が作れるかと問われ、`n人々は我によって養われた。`n我から何が作れるかと問われ、`n家々が建てられた。`n我から何が作れるかと問われ、`n書きものがなされた。`n我から何が作れるかと問われ、`n我は地を肥やした。`nされどさらに何が作れるかと問われた時、`n何一つ残ってはいなかった。'),
    ('answer_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', '木'),
    ('riddle_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', 'これがあれば驚くべきことができる。`n近くのものも遠くのものも見え、`n大きなものも見え、`n小さなものも見える。`nあるいは何も見えぬかもしれぬ。`n我は様々な色合いで現れる、`n時に緑、時に青。`n我が赤いときは恥じてではなく、`n別の名を持つ何かのせいだ。'),
    ('answer_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', '目'),
    ('riddle_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', 'ああ、我は踊る我が足が大好きだ！`nなんと綺麗に揃っていることか。`n我が一列に歩こうとすれば、`n皆が揃って倍の速さで動く。`n十度も数え直し、`n床を横切って駆けていく。'),
    ('answer_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', 'ムカデ; ヤスデ'),
    ('riddle_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', '囲いの中から低い唸りが聞こえ、`n我は歩みを止めて中を覗いた。`n我が見たものは何であったか。`n蹄と顎を備えた巨大な獣。`n堂々たる額には棘が生え、`n彼が土を蹴り歩き回るのを我は見た。`nされどその威容にもかかわらず、`n彼はあの木の柵から出られなかった。'),
    ('answer_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', '雄牛'),
    ('riddle_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', 'それは我が関わったことを`n語らねばならぬ`nその日の夜であった。`n陽は出ていて`n声一つ上げずに`n静かに入っていった。`n実に奇妙なことだ`n我は彼が睨むと思ったが`n一言も差し挟めなかった。`nさらに一言もなく`n（少なくとも我が聞いた限りでは）`n彼は元いた場所へ戻っていた。'),
    ('answer_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', '日食'),
    ('riddle_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', '日の出から日の入りまで我は海を見渡す。`n日の入りから日の出まで我は海を見渡す。`nされど日が出ている間は眩しさに瞬くばかりで、`n日が沈めば我は眩しさを瞬かせて放つ。'),
    ('answer_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', '灯台'),
    ('riddle_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', 'よく吠える（樹皮が多い）が、`n誰も気に留めぬ。`n噛むものは多く、`n皆が気にかける。`n我は犬ではない、`n誰か気づくならば。`n我には多くのものがあるが、`n毛はない。`n我はまっすぐ立っている、`n汝が我に目を留めたなら。`n我には手足が多い、`n誰か気にかけるなら。`n我は日陰を与えられる、`n汝が気づいたなら。`nそしてそれ以上のこともする、`n我は汝に空気を与える。'),
    ('answer_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', '木'),
    ('riddle_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', '十二月だったか六月だったか、`n我が奥方が気を失われた時。`n髪が抜け落ち、`n眼鏡が失せた時。`n奥方が悲鳴を上げた時、`nそれはもう見苦しいほどに。`n我を指差して、`n「きゃああ！ きゃああ！」と。`n少々大げさに過ぎたと言わざるを得ぬ、`n我は誰にも触れていないのだから。`nされど何かが狂っていたのは`n明らかであった。`nそこで我は別の日に出直すことにした、`n奥方がおられぬ折にでも。'),
    ('answer_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', 'ネズミ'),
    ('riddle_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', '我は漂う、`n緩やかな川のように。`n我は踊る、`nほんの一吹きの風の上で。`n我は転がる、`n名だたる軽業師よりも巧みに。`n渦を巻き、`nくるくると回り、`n地へと降りていく。`nそこで我は横たわる、`n二度目の風を得るまで。`nそしてまた始めるのだ。'),
    ('answer_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', '葉'),
    ('riddle_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', '易しく解ける謎。`n赤い胸。`n多くの中のただ一つ。`n卵から生まれた。`n歌うよう促された。`nさあ文字を集めて我が意味を告げよ。'),
    ('answer_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', 'コマドリ'),
    ('riddle_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', '我はこれを四つ持ち、`nそれぞれに揃いの先端がある。`nそれらは多くのことができ、`nめったに我を痛めぬ。`n針で刺すか、`n時に焼くかしなければ…`n我が意のままに動かせ、`n他の用にも使うこれは何か。'),
    ('answer_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', '指'),
    ('riddle_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', '彼の情熱の炎と`n彼女の手の冷たさを見たとき、`n我はその結合から悲劇しか生まれぬと悟った。`n果たして二人が相まみえたとき、`n闇が地を支配した。`nやがて二人は引き離され、`n互いにふさわしくないと知ったが、`nそれでも交わした束の間の眼差しは、`nそれを目撃したすべての者に印を残し、`nこれから幾代も語り継がれるだろう。'),
    ('answer_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', '日食'),
    ('riddle_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', '外套を持つものは何か。`n情けから抱きしめはせぬものは。`nその笑みを見たくないものは。`nその構えを見るのも恐ろしいものは。`n勇者が逃げ出す相手は誰か。`n指が鉤爪になっているものは。`n幾月も眠り続けるものは。`nそして我らが付き合いを避けるものは。'),
    ('answer_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', '熊'),
    ('riddle_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', 'その上で転げ回ることも、`n寝転ぶことも、`n燃やすこともでき、`n獣が食べもし、`n床に敷かれもし、`n厩の戸の向こうでも今なお使われる。`n置かれたものを何であれ爽やかにし、`n注がれたものを何であれ吸い取る。`nそれは何か。'),
    ('answer_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', '干し草'),
    ('riddle_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', '情熱の果実の中にそれらは見つかり、`n柘榴の冠にはもっと多くある。`n林檎の芯には列をなし、`n他の果実にはさらに多い。`nネクタリンには一つしかないが、`nこれはみな戯れにすぎぬ。`nかくれんぼ — 子供の遊び。`n見つけてみれば、参加者は皆同じ。'),
    ('answer_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', '種'),
    ('riddle_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', 'それは天で囁かれ、地獄で呟かれ、`n落ちゆく音を木霊がかすかに捉えた。`n地の果てでは憩うことを許され、`n大海の深みでもその存在が示された。`n天が裂けるときその中に見出され、`n稲妻に見え、雷に聞こえるだろう。`n人には最初の息と共に与えられ、`n誕生に立ち会い、死に際して待つ。`n彼の幸福と名誉と健康を司り、`n家の支えであり、富の終わりでもある。`n守銭奴の山では大事に蓄えられるが、`n放蕩の相続人のもとでは必ず失われる。`nあらゆる希望を始め、あらゆる願いを結び、`n農夫と共に労し、君主と共に冠を戴く。`nそれなくして兵士も船乗りも彷徨えようが、`nそれを家から追い出す哀れな者に災いあれ！`n良心の囁きの中にその声は見出され、`n情念の旋風の中でも決してかき消されぬ。`nそれは心を和らげ、耳が聞こえずとも、`n彼に鋭く即座に聞かせるだろう。`n日陰に置き、繊細な花のように憩わせよ。`nああ！ そっと息を吹きかけよ、一時間で死んでしまう'),
    ('answer_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', '文字のH; H'),
    ('riddle_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', '我らは小さく空気のような者たち、`nそれぞれ声も姿も異なる。`n一人はガラス（glass）の中にあり、`n一人は黒玉（jet）の中に見つかり、`nもう一人は錫（tin）の中に見え、`n四人目は箱（box）の中にいる。`n五人目を追うならば、`nそれは決して汝から逃げられぬ。'),
    ('answer_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', '母音'),
    ('riddle_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', '我は奇妙な矛盾。我は新しくもあり、古くもある。`n我はしばしばぼろをまとい、しばしば金で飾られる。`n我は決して読めぬのに、文字を刻まれており、`n盲いていながら人を照らし、緩んでいながら綴じられている。`n我は常に黒く、常に白い。`n我は厳粛でもあり陽気でもあり、重くもあり軽くもある —`n形も様々だ — 我は厚くもあり薄くもあり、`n肉も骨もないが、皮に覆われている。`n羅針盤より多くの点を持ち、笛より多くの休止を持つ。`n我は声なくして歌い、語らずして論駁する。`n我は英国人であり、ドイツ人であり、フランス人であり、オランダ人である。`nある者は我を溺愛し、ある者は我を軽んじすぎる。`n我はしばしば早世するが、時には幾世代も生きる。`nそして生ける君主の誰一人、我ほど多くの小姓（ページ）を持たぬ。'),
    ('answer_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', '本'),
    ('riddle_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', '我が庭の門を通り抜けたとき、`n出会ったのは赤帽子のディックにほかならぬ！`n手には棒、喉には石。`nこの謎を解けたなら、銀貨一枚進ぜよう。'),
    ('answer_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', 'さくらんぼ'),
    ('riddle_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', '小さなナンシー・エティコート、`n白いペチコートを着て、`n赤い鼻をしている。`n長く立っているほど`n背が縮んでいく。'),
    ('answer_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', '蝋燭'),
    ('riddle_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', '我には小さな妹がいて、皆が彼女をピープ、ピープと呼ぶ。`n彼女は深い深い深い水を渡り、`n高い高い高い山に登る。`n哀れなことに、彼女には目が一つしかない。'),
    ('answer_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', '星'),
    ('riddle_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', '我は一団が行進するのを見た、`n海を越えて行進するのを。`nそれを眺めながら、`n我は自らに問うた「あれは何だろう」と。`nそこには馬がおり、`n牛もおり、`n人々が行進していた、`n家や木々を連れて。だがどうやって。`n我は一団が行進するのを見た、`n海を越えて行進するのを。`nそして休みながら思った、`n我はなんと怠け者であることか。'),
    ('answer_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', '空の雲; 雲'),
    ('riddle_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', '我は上にいる。`n我は下にいる。`n我は至る所にいる。`nされど決して見つけられぬ。`n我は誰か。'),
    ('answer_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', '風'),
    ('riddle_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', '我は動かされうる。`n我は転がされうる。`nだが何も入れておけぬ。`n我は赤くもあり青くもある。`n他の色にもなりうる。`n頭はないが形は似ており、`n目もないのに至る所を動き回る。`n我は何か。'),
    ('answer_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', 'ボール'),
    ('riddle_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', '汝は我を踏むことができる、`n覆いの下をそっと。`nそして我は汝を連れて行こう、`nまだ見ぬ場所へ。`n我は高く、また低く、`n真ん中は平らだ。`n子供には喜びだが、`n大人は我を大して気に留めぬ。`n我は何か。'),
    ('answer_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', '階段'),
    ('riddle_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', '物を築き上げ、`n山を低くし、`n湖を干上がらせ、`n物を育てるものは何か。`n汝の過ぎ去りなど気にも留めず、`n他のものとほとんど似ぬのは、`nそれが永遠だからだ。'),
    ('answer_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', '時'),
    ('riddle_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', 'それは柳の木に止まり、`n我に優しく歌ってくれた。`nその歌で我が痛みと悲しみを和らげ、`n我は飛び立ちたかったが長く留まった。`nそして我が苦しみの中で、`n柳は涼やかな清泉のようだった。`n我をそれほど助けたのは何だったか。`n我が憂いの時を共に過ごしてくれたものは。'),
    ('answer_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', '鳥'),
    ('riddle_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', 'それらは抱え込めるが、水を湛えるものは少なく、`n育てられるが、それには誰かに突きつけるほかなく、`n運べるが、腕でではなく、`n埋められるが、土の中にではない。'),
    ('answer_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', '恨み'),
    ('riddle_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', '椀のように深く、杯のように丸いが、`n世界中の海をもってしても満たせぬ。'),
    ('answer_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', 'ふるい'),
    ('riddle_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', '砂漠の民はかつて我を神と呼んだが、`n今日、人は我を狂っていると言う。`n我は怒ると尾を振り、`n嬉しいと唸るからだ。'),
    ('answer_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', '猫'),
    ('riddle_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', '我は侵略し征服する軍勢の噂を聞いた。`n水のごとく速く地を席巻し、`nすべてを征服し、抵抗を鎮めた。`nそれと共に闇が訪れ、光を翳らせた。`n人々は家に隠れ、外では`n槍が突き刺さり、石壁を砕いた。`n数えきれぬ兵が地に叩きつけられたが、`nそれぞれが死にながら命を呼び起こした。`n軍勢が北へ進み去った時、`n地は緑に育ち、生き返っていた。'),
    ('answer_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', '暴風雨; 雨'),
    ('riddle_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '「我は見えぬものを見つけ、見つけられぬものを見ることができる。`n前者は時であり、後者は我が目の前の斑点である。」'),
    ('answer_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '時'),
    ('riddle_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', '我は触れられぬものを感じ、感じられぬものに触れることができる。`n前者は悲しく痛ましく、後者は汝の心臓だ。'),
    ('answer_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', '心臓'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', '決して先を行かず、常に後ろにありながら、`n矢のように過ぎ去る。`n子にとって我は永遠であり、`n大人にとって我は去るのが早すぎる。'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', '若さ'),
    ('riddle_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', '彼女は背が高く、杯のように丸いが、`n王の馬をすべて集めても`n彼女を引き上げられぬ。'),
    ('answer_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', '井戸'),
    ('riddle_text', 'There more of it there is,`nThe less you see.', 'それが多いほど、`n汝は見えなくなる。'),
    ('answer_text', 'There more of it there is,`nThe less you see.', '闇'),
    ('riddle_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', '一人には足りず、`n二人にはちょうどよく、`n三人には多すぎるものは何か。'),
    ('answer_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', '秘密'),
    ('riddle_text', 'What gets wetter the more it dries?', '乾かすほど濡れるものは何か。'),
    ('answer_text', 'What gets wetter the more it dries?', '手ぬぐい'),
    ('riddle_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', '長い蛇一匹、`n刺すような噛みつき、`n我は巻いたままでいる`n戦わねばならぬ時でなければ。'),
    ('answer_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', '鞭'),
    ('riddle_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', '花々の間の戦士、`n彼は突き刺す剣を帯びる。`n用いる備えも腕もある、`n己の黄金の蓄えを守るために。'),
    ('answer_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', '蜂'),
    ('riddle_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', '荷を負う者、戦う者、`n怯える者、勇ましき者、`n足の速き者、鉄を履く者、`n忠実なる者、奴隷。'),
    ('answer_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', '馬'),
    ('riddle_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', '風の中を歩き`n雨の中を走り`n陽の下に乾いた海を作る。`n時を数え、時計を止め、`n王国を呑み、岩を齧る。'),
    ('answer_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', '砂'),
    ('riddle_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', '起伏する丘、永遠に脈打つ心、`n決して変わらず、決して静まらぬ地、`n故郷を遠く離れた旅人が耕すが、種は蒔かれぬ。`n怒れば白く、和めば緑、そして常に青い。'),
    ('answer_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', '海'),
    ('riddle_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', 'よく聞け、我は解し難い。`n我は一握りの砂のように捉えどころがない。`n我を察したとしても、汝は我を知らぬ、`n我が何を忘れたか汝が言えるまでは。'),
    ('answer_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', '謎かけ'),
    ('riddle_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', '身を挟まずに戸を通るものは何か。`n身を焼かずに竈の上に座るものは何か。`n恥じることなく食卓の上に座るものは何か。'),
    ('answer_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', '太陽'),
    ('riddle_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', '我が座っている間に`n死せるものが生けるものを運ぶのを見た。`n我が見たものは何か。'),
    ('answer_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', '船'),
    ('riddle_text', 'I know a word of letters three,`nAdd two and fewer there will be.', '我は三文字の語を知っている。`n二つ足せば、より少なくなる。'),
    ('answer_text', 'I know a word of letters three,`nAdd two and fewer there will be.', '少ない'),
    ('riddle_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', '作る者はそれを必要とせず、`n買う者はそれを使う当てがなく、`n使う者はそれを見も感じもせぬ。'),
    ('answer_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', '棺'),
    ('riddle_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', 'それを作った者はそれを必要としなかった。`nそれを買った者はそれを使わなかった。`nそれを使った者はそれを望まなかった。'),
    ('answer_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', '棺'),
    ('riddle_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', '汝は我を捕らえたが、我は逃げた。`n汝は我が逃げるのを見ても、しかと掴めぬ。`n手に握れば、拳は空だ。`n我は何か。'),
    ('answer_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', '雪'),
    ('riddle_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', '朝には四本足、`n昼には二本足、`n夕べには三本足のものは何か。'),
    ('answer_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', '人間'),
    ('riddle_text', 'What is deaf, dumb and blind`nand always tells the truth ?', '耳も聞こえず口も利けず目も見えぬのに`n常に真実を告げるものは何か。'),
    ('answer_text', 'What is deaf, dumb and blind`nand always tells the truth ?', '鏡'),
    ('riddle_text', 'What is always in front of you`nbut cannot be seen?', '常に汝の前にありながら`n見ることのできぬものは何か。'),
    ('answer_text', 'What is always in front of you`nbut cannot be seen?', '未来'),
    ('riddle_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', '人が命より愛し、`n死や命がけの争いよりも憎むもの、`n満ち足りた者が望むもの、`n貧しき者が持ち、富める者が求めるもの、`n守銭奴が費やし、浪費家が蓄えるもの、`nそしてすべての人が墓まで携えるものは何か。'),
    ('answer_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', '無'),
    ('riddle_text', 'A life longer than any man,`nit dies each year to be reborn.', 'いかなる人よりも長い命、`n毎年死んでは生まれ変わる。'),
    ('answer_text', 'A life longer than any man,`nit dies each year to be reborn.', '木'),
    ('riddle_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', '目には盲いをもたらし、`n鼻にはくしゃみを起こすのみ。`nされど幾人かはこれを吸い込み、`nさも嬉しげに振る舞う。'),
    ('answer_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', '煙'),
    ('riddle_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', 'それは骨も固い形も持たず、独りで立つ。`n断固として決して誤らぬが、`n傷つけることはある。`n捻じ曲げることも、こねることもできようが、`n常に矢のようにまっすぐだ。'),
    ('answer_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', '真実'),
    ('riddle_text', 'What sphinxes employ,`nthe players enjoy.', 'スフィンクスが用い、`n遊ぶ者が楽しむもの。'),
    ('answer_text', 'What sphinxes employ,`nthe players enjoy.', '謎かけ'),
    ('riddle_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', '我が常に寄り添う者がいるが、`n闇の中では我は消える。`nこの者にのみ我は忠実であり、`n彼の後ろで労するよう定められている。`n彼は我を感じぬ（我らは常に触れ合っているのに）。`n我が失われても、彼が失うものは少ない。`nそして今、驚くべき点に至る、`n彼こそが汝なのだ — ならば我は誰か。'),
    ('answer_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', '影'),
    ('riddle_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', '我はしばしば抱かれるが、めったに触れられず、`n常に濡れているが、決して錆びず、`n時に振られ、時に噛まれる。`n我をうまく使うには機知がいる。'),
    ('answer_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', '舌'),
    ('riddle_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', '窓辺に座って彼女は泣いていた。`nそして涙の一滴ごとに彼女の命が滲み出ていった。'),
    ('answer_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', '蝋燭'),
    ('riddle_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', '我は実のところ、穴と穴を繋いだものに`n過ぎぬ。`n良質の鋼ほど頑丈だが、棒ほど`n硬くはない。'),
    ('answer_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', '鎖'),
    ('riddle_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', '我は力は乏しいが、大いなる権能を持つ。`n我は小さな小屋も大いなる塔も守る。`nされど万一我が主が去るなら、`n彼は必ず我を守らねばならぬ。'),
    ('answer_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', '鍵'),
    ('riddle_text', 'Delivered by breath,`nscares heroes to death.', '息によって届けられ、`n英雄を死ぬほど怯えさせる。'),
    ('answer_text', 'Delivered by breath,`nscares heroes to death.', '謎かけ'),
    ('riddle_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', '昼間は溜まりのように広がり、`n夜には霧のように覆う。`n閉じた箱の中にも忍び込み`n汝の握った拳の中にも入る。`n見えぬ時にこそ我は最もよく見える、`n我は存在せぬのだから。'),
    ('answer_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', '闇'),
    ('riddle_text', 'Devils and rogues know nothing else,`nsave starlight.', '悪魔も悪党も星明かりのほかには`n何も知らぬ。'),
    ('answer_text', 'Devils and rogues know nothing else,`nsave starlight.', '闇'),
    ('riddle_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', '王も馬もこれを持っているが、`n汝はそのどちらも欲しくはあるまい。'),
    ('answer_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', '治世; 手綱'),
    ('riddle_text', 'My spring up on the cliff.', '崖の上の我が泉。'),
    ('answer_text', 'My spring up on the cliff.', 'ココヤシの実'),
    ('riddle_text', 'Three walls and you reach water.', '壁を三つ抜ければ水に届く。'),
    ('answer_text', 'Three walls and you reach water.', 'ココヤシの実'),
    ('riddle_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', '休みなく鳴り続ける`n我がカパ（布の一種）の丸太。'),
    ('answer_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', '海'),
    ('riddle_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', '朝には四本足、`n昼には二本足、`n夕べには三本足。'),
    ('answer_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', '人間'),
    ('riddle_text', 'My man that cannot be cut.', '斬ることのできぬ我が男。'),
    ('answer_text', 'My man that cannot be cut.', '影'),
    ('riddle_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', '昼も夜も進む我がカヌーたち、`n舳先は十、艫は二つ。'),
    ('answer_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', '人の両足'),
    ('riddle_text', 'My red cave, white soldiers standing in line.', '我が赤い洞窟、白い兵士が列をなして立つ。'),
    ('answer_text', 'My red cave, white soldiers standing in line.', '人の口'),
    ('riddle_text', 'My man crying day and night,`nall through the year.', '昼も夜も泣き続ける我が男、`n一年中ずっと。'),
    ('answer_text', 'My man crying day and night,`nall through the year.', '海')
  ) AS source
  JOIN riddle ON riddle.riddle_text = source.column2;

DELETE FROM catalog_translation WHERE entity_type = 'riddle' AND locale_code = 'zh';

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'riddle', riddle.riddle_id, source.column1, 'zh', source.column3
  FROM (VALUES
    ('riddle_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', '你吃着既不曾播种也不曾耕作之物。`n它是水之子，但水一碰它便死。'),
    ('answer_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', '盐'),
    ('riddle_text', 'Teacher, open thy book.', '先生，请翻开你的书。'),
    ('answer_text', 'Teacher, open thy book.', '蝴蝶'),
    ('riddle_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', '我的枝长。`n我的枝短。`n我的枝在`n我最初的通报之前便已终结。'),
    ('answer_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', '闪电；霹雳'),
    ('riddle_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', '把我们翻过来`n剖开我们的肚腹`n你将成为最有智慧的人`n纵然起初是个蠢材。'),
    ('answer_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', '书'),
    ('riddle_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', '埋得再深，`n压上石头，`n我仍会`n把骨头掘出来。'),
    ('answer_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', '记忆'),
    ('riddle_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', '它每分钟出现一次`n每一刻出现两次`n却在十万年里一次也不出现。'),
    ('answer_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', '字母M；M'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', '从不在前，永远在后，`n却疾驰而过；`n于孩童我永恒，`n于成人我去得太快。'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', '童年'),
    ('riddle_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', '两匹跑得最快的马，`n并辔而系，`n却总在远离彼此的地方`n吃草。'),
    ('answer_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', '双眼；日与月'),
    ('riddle_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', '可以这样说：`n是金便是善；`n是石便是无；`n是玻璃便是脆；`n是冷便是残忍。`n剥去比喻，我是什么？'),
    ('answer_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', '心'),
    ('riddle_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', '她是圆的，却平如板，`n是狼族君王的祭坛。`n黑绒上的宝石，海中的明珠，`n不变而又永恒地变化。'),
    ('answer_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', '月亮'),
    ('riddle_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', '它有金色的头`n有金色的尾`n却没有身子。'),
    ('answer_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', '金币；硬币'),
    ('riddle_text', 'Speak, friend, and enter!', '朋友，说出口令，进来吧！'),
    ('answer_text', 'Speak, friend, and enter!', '朋友'),
    ('riddle_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', '一条皮革般的蛇，`n咬起来如同螫刺，`n我会一直盘着，`n除非非战不可。'),
    ('answer_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', '鞭子'),
    ('riddle_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', '什么东西有无人得见的根，`n比树还高，`n不断向上、向上，`n却从不生长？'),
    ('answer_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', '山'),
    ('riddle_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', '红山之上三十匹白马，`n先是咀嚼，`n继而踩踏，`n然后静立不动。'),
    ('answer_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', '牙齿'),
    ('riddle_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', '无声而哭，`n无翼而舞，`n无齿而咬，`n无口而语。'),
    ('answer_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', '风'),
    ('riddle_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', '看不见，摸不着，`n听不到，闻不出。`n它卧在星辰之后，伏在山丘之下，`n填满空空的洞穴。`n它最先到来，又随后跟随，`n终结生命，扼杀笑声。'),
    ('answer_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', '黑暗'),
    ('riddle_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', '一只没有铰链、钥匙和盖子的盒子，`n里头却藏着金色的宝藏。'),
    ('answer_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', '蛋；橙子'),
    ('riddle_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', '无息而活，`n冷如死亡；`n从不口渴，却时时饮水，`n浑身甲胄却不作响。'),
    ('answer_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', '鱼'),
    ('riddle_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', '此物吞噬万物：`n飞鸟、走兽、树木、花朵；`n啃铁咬钢；`n把坚石磨成粉；`n弑君灭城，`n将高山夷平。'),
    ('answer_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', '时间'),
    ('riddle_text', 'You feel it, but never see it and never will.', '你能感觉到它，却永远看不见，将来也看不见。'),
    ('answer_text', 'You feel it, but never see it and never will.', '心'),
    ('riddle_text', 'You must keep it after giving it.', '给出之后仍须守住的东西。'),
    ('answer_text', 'You must keep it after giving it.', '承诺'),
    ('riddle_text', 'As light as a feather, but you can''t hold it for ten minutes.', '轻如鸿毛，你却握不住十分钟。'),
    ('answer_text', 'As light as a feather, but you can''t hold it for ten minutes.', '呼吸'),
    ('riddle_text', 'Has a mouth but does not speak, has a bed but never sleeps.', '有口不能言，有床却从不眠。'),
    ('answer_text', 'Has a mouth but does not speak, has a bed but never sleeps.', '河'),
    ('riddle_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', '流得比任何韵律都顺畅，爱落却不能升！'),
    ('answer_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', '水'),
    ('riddle_text', 'You break it even if you name it!', '你只要叫出它的名字，它就碎了！'),
    ('answer_text', 'You break it even if you name it!', '寂静'),
    ('riddle_text', 'It passes before the sun and makes no shadow.', '它从太阳前经过，却不留影子。'),
    ('answer_text', 'It passes before the sun and makes no shadow.', '空气'),
    ('riddle_text', 'You feed it, it lives, you give it something to drink, it dies.', '你喂它，它便活；你给它喝，它就死。'),
    ('answer_text', 'You feed it, it lives, you give it something to drink, it dies.', '火'),
    ('riddle_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', '一面红鼓`n不被敲击时作响，`n一旦被触碰，`n便归于沉寂。'),
    ('answer_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', '心'),
    ('riddle_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', '同一天播种又收割的庄稼，`n生在未曾耕过的田里，`n不长而增，`n内外皆被吞食`n却依然完整，`n无甚用处，却又是`n列国的主食。'),
    ('answer_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', '战争'),
    ('riddle_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', '你若打碎我`n我并不停止运作，`n你若触碰我`n我或许会被套住，`n你若失去我`n一切都将无关紧要。'),
    ('answer_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', '希望'),
    ('riddle_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', '四处皆是却看不见，`n可以捕捉却握不住，`n没有喉咙却能被听见。'),
    ('answer_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', '声音'),
    ('riddle_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', '我兜着圈子走，`n却始终笔直向前。`n无论被带往何处，`n从不抱怨。'),
    ('answer_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', '车轮'),
    ('riddle_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', '我比造就我之物`n更轻，`n藏起来的部分`n比看得见的更多。'),
    ('answer_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', '冰山'),
    ('riddle_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', '若有人背起我的负担，`n他会折断脊背。`n我并不富有，`n却在行迹上留下银痕。'),
    ('answer_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', '蜗牛'),
    ('riddle_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', '我的生命以小时计量，`n以被吞噬来尽职。`n瘦时我快，`n胖时我慢，`n风是我的敌人。'),
    ('answer_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', '蜡烛'),
    ('riddle_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', '腹中有重物，`n背上有树木，`n肋间有钉子，`n却没有脚。'),
    ('answer_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', '船；洞穴'),
    ('riddle_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', '当你望进我的脸`n便再看不见别的。`n我会直视你的眼睛`n且永不说谎。'),
    ('answer_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', '镜子'),
    ('riddle_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', '我永远饥饿，`n必须不断被喂食，`n我舔过的手指`n很快会变红。'),
    ('answer_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', '火'),
    ('riddle_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', '我有三种生命。`n柔得足以抚慰肌肤，`n轻得足以轻拂天空，`n硬得足以裂开岩石。'),
    ('answer_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', '水'),
    ('riddle_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', '向下直刺的`n闪亮尖端，`n永不生锈的`n晶莹长矛。'),
    ('answer_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', '冰柱'),
    ('riddle_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', '每天清晨我出现`n卧在你的脚边，`n整日跟随着你`n无论你跑得多快，`n可到了正午的烈日下`n我却几乎消亡。'),
    ('answer_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', '影子'),
    ('riddle_text', 'Keys without locks`nYet I unlock the soul.', '没有锁的钥匙`n我却能开启灵魂。'),
    ('answer_text', 'Keys without locks`nYet I unlock the soul.', '钢琴；拨弦古钢琴'),
    ('riddle_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', '我如此简单，`n只会指方向，`n却引导着`n全世界的人。'),
    ('answer_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', '罗盘'),
    ('riddle_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', '因我们的甘露，朱庇特`n赐我们以致命之螫。`n虽有人嘲笑我们的力量，`n我们却曾平息巨龙的吐息。`n我们是谁？'),
    ('answer_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', '蜜蜂'),
    ('riddle_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', '色如少女被掐红的双颊，`n我开始时时间尚未存在；`n我被偷偷带过花园，`n唯我一物成了人的堕落。`n我是什么？'),
    ('answer_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', '苹果'),
    ('riddle_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', '本不该有处偏有其一，`n或该有二处却只余一，`n在王的林中`n寻觅纯洁。`n我是什么？'),
    ('answer_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', '独角兽'),
    ('riddle_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', '一齿用来咬，`n他是森林之敌。`n一齿用来战，`n北欧人尽知。`n那是什么？'),
    ('answer_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', '斧'),
    ('riddle_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', '鸟身上`n不在天空的那部分，`n能在海里游`n却始终不湿。`n那是什么？'),
    ('answer_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', '鸟的影子；影子'),
    ('riddle_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', '这倒长的东西`n根在干之上，`n冬天生长`n春天死去。`n那是什么？'),
    ('answer_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', '冰柱'),
    ('riddle_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', '触一而含二，`n它是一环之链，`n缚住守信之人，`n直到死亡将其撕裂。`n那是什么？'),
    ('answer_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', '婚戒；戒指'),
    ('riddle_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', '睿智博学之人对它笃定。`n就连愚者也知道它。`n富人想要它。`n最伟大的英雄惧怕它。`n然而最卑劣的懦夫也愿为它而死。`n我所思量的这是什么？'),
    ('answer_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', '无；某物'),
    ('riddle_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', '什么比神更伟大，`n比魔鬼更邪恶，`n死人吃它，`n你若吃了便会死？'),
    ('answer_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', '无'),
    ('riddle_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', '我是女人们绝好的帮手，`n是将来之事的希望。除了杀我之人，`n我不伤害任何百姓。`n我扎根立于高床之上。`n我下身毛茸茸。有时那美丽的`n农家女儿，臂膀急切、`n骄傲的女子攥住我的身体，`n剥去我红色的皮，紧紧握住，`n夺走我的头。那卷发的`n女子若牢牢擒住我，便会感受到`n我们的相遇。她的眼睛会湿润。'),
    ('answer_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', '洋葱'),
    ('riddle_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', '供君王执掌的力量与珍宝，`n坚硬而陡峭的颊，裹在赤金`n与石榴石之中，自明亮花朵的原野`n被撕出，锻造而成——火与锉的`n遗物，以纤细的金丝束成峻美。`n我的握力令战士哭泣，我的螫刺`n威胁着攫取黄金的手。缀着`n一枚环，我蹂躏继承者与传家宝。`n对我的主人和敌人我永远美丽`n且致命，不断变换面容与形貌。'),
    ('answer_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', '剑'),
    ('riddle_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', '我去圣艾夫斯的路上，`n遇见一个男人带着七位妻子；`n每位妻子有七个袋子，`n每个袋子里有七只猫，`n每只猫有七只小猫：`n小猫、猫、袋子和妻子，`n去圣艾夫斯的一共有几个？'),
    ('answer_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', '一个'),
    ('riddle_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', '晨光退去，`n白日转灰，`n我必须远行。`n但我会回来，`n那时我们将一同追寻，`n又一日的光。'),
    ('answer_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', '太阳；影子'),
    ('riddle_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', '深深地、暗暗地、在地底下，`n那便是能找到我的地方。`n可一旦被带到日光之下，`n我便四面八方洒下光辉。`n纵使被油污蒙住，`n我依旧完好而坚实。`n把我迅速切开便能看见，`n我立刻焕发出奇妙的光泽。'),
    ('answer_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', '钻石；宝石'),
    ('riddle_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', '什么必须在炉中却烤不熟？`n在热中生长却避开日光？`n入水下沉却随气而升？`n看似皮肤却细如发丝？'),
    ('answer_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', '酵母'),
    ('riddle_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', '小约翰尼·沃克，`n哎呀，他可真能说！`n可他一个字也没吐出！`n我把他拿出来时，`n人人都指着他喊叫！`n还求我把他收起来。'),
    ('answer_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', '看法'),
    ('riddle_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', '它们既多又一，`n挥动又拍打，`n用来遮住目光，`n随你走遍天涯。'),
    ('answer_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', '双手'),
    ('riddle_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', '踏踏，踏踏，`n嚼嚼，嚼嚼，`n蹦蹦，跳跳。`n静静站着，`n一切就绪。'),
    ('answer_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', '马'),
    ('riddle_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', '嗜甜之人，`n啊呀，`n全没了，`n我们都盼着，`n再来一块。'),
    ('answer_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', '糖果'),
    ('riddle_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', '它踏着猫步而来，`n既不酸也不甜。`n悬在空中，`n转眼便不见。'),
    ('answer_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', '雾'),
    ('riddle_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', '一声笑，`n一声哭，`n一声呻吟，`n一声叹息。'),
    ('answer_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', '情绪'),
    ('riddle_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', '什么是你必须回答的？`n可要回答就得先问；`n要问就得开口；`n要开口就得先知道，`n那个答案。'),
    ('answer_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', '谜语'),
    ('riddle_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', '我能击中你的眼睛，`n又能在天上闪烁，`n死时还会膨胀，`n你猜我是什么？'),
    ('answer_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', '星'),
    ('riddle_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', '黏糊糊，`n软塌塌，`n让人想洗澡，`n还会沾到头发上，`n弄得人不好看。'),
    ('answer_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', '泥'),
    ('riddle_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', '上山，`n下山，`n我或许四处游荡，`n可走遍之后，`n没有一处比得上自己的地方。'),
    ('answer_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', '家'),
    ('riddle_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', '这东西着实奇妙。`n它可以锋利如刀，`n也可以平坦如地板。`n然而尽管千变万化，`n它却像蜜蜂一样自然。'),
    ('answer_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', '音乐；音符'),
    ('riddle_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', '深深地、深深地向下去。`n一边前行一边散开。`n从不需要空气。`n有时细如发丝。'),
    ('answer_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', '根'),
    ('riddle_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', '主啊！我不配！`n我把枝条垂向地面。`n我哭泣，却无声无息。`n让我畅饮深水吧。`n我将在寂静中哀哭。'),
    ('answer_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', '柳树'),
    ('riddle_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', '移动，移动，深深流转。`n我之下沉睡着伟大的城池。`n盘旋，奔走，遍布四方。`n我只在无水之处。'),
    ('answer_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', '沙漠'),
    ('riddle_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', '我咕嘟作响又欢笑`n把水喷到你脸上。`n我不是什么淑女，`n也不穿蕾丝。'),
    ('answer_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', '喷泉'),
    ('riddle_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', '什么有翅膀，`n却不能飞。`n被围合着，`n却也能置于外。`n能自行打开，`n也能自行合上。`n是帝王后妃的所在，`n也是各色打油诗的所在。`n我所立之处是什么？`n它能引我们通往不同的天地。'),
    ('answer_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', '舞台'),
    ('riddle_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', '莫要怨恨此事，`n因这是每个人的命运。`n然而它令人畏惧，`n在许多地方被回避。`n它带来麻烦，有时留下空缺，`n能绊倒最强壮者，令记忆断片。`n我们都要面对的这一危险是什么？`n只因身为人类的一员。'),
    ('answer_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', '衰老；年岁'),
    ('riddle_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', '这东西我有两份。`n一份给我，一份给你。`n你若问价钱，`n我只是微笑着点两下头。'),
    ('answer_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', '分享'),
    ('riddle_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', '我是奇异的造物，`n悬停在空中，`n从此处飞到彼处，`n带着绚丽的光彩。`n有人说我歌唱，`n也有人说我没有嗓音。`n所以我只是嗡鸣——出于自愿。`n我是什么？'),
    ('answer_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', '蜂鸟'),
    ('riddle_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', '白日里沉睡，`n我把自己藏起。`n整夜警醒，`n黎明时我绽开。`n可只有极短的时刻，`n我才闪耀。`n随后我又藏起，`n沉睡整个白昼。'),
    ('answer_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', '牵牛花'),
    ('riddle_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', '看似水，`n实为热。`n坐在沙上，`n卧于水泥。`n据说人们`n会随它走遍各处。`n可它带人一无所至，`n只能干瞪着眼。'),
    ('answer_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', '海市蜃楼'),
    ('riddle_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', '天的一部分，`n却触及大地。`n有人说它珍贵，`n也有人说毫无价值。'),
    ('answer_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', '彩虹'),
    ('riddle_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', '我站着，`n眺望大海，`n那有波浪、浪峰、浪谷与低洼的大海。`n我阔步，`n跨过这片水，我的马跟在后面，`n水拍打着它的肩，`n又蹭过我的大腿，`n我用笑声填满这片空茫。`n而它——以叹息填之。`n我们要去何方？`n还是根本不曾前行？`n又或者我们只是在此涉水，`n奔向下一个港口。`n在海止之处，`n在脚下泥土坚实之处，`n我将再次跨上坐骑，`n继续前行，直到下次相见。`n真正说的是什么？'),
    ('answer_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', '辽阔的平原；平原'),
    ('riddle_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', '我生来目盲，`n看不见东西，`n直到差一刻三点。`n我笑不出来，`n直到六点半，`n而我的手脚`n全是木棍做的。'),
    ('answer_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', '玩偶'),
    ('riddle_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', '啊！我的呼吸颤抖，`n四肢瘦削，`n腹中作痛。`n白色加冕于我的头顶，`n我留下的足迹，`n所过之处摇摇晃晃。`n我用浑浊的眼睛望向外面，`n仿佛在道最后的别。`n黑暗把我拉近，`n我向它倾身——好听得更清楚些。'),
    ('answer_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', '衰老；年岁'),
    ('riddle_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', '希卡摩，哈卡摩，`n在国王的厨房门上。`n国王所有的马，`n国王所有的臣仆，`n都没能把希卡摩、哈卡摩`n从国王的厨房门上弄下来。'),
    ('answer_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', '阳光'),
    ('riddle_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', '有人问我能做成什么，`n于是人们靠我果腹。`n有人问我能做成什么，`n于是房屋得以建起。`n有人问我能做成什么，`n于是文字得以书写。`n有人问我能做成什么，`n于是我肥沃了土地。`n可当再问我还能做成什么时，`n已一无所剩。'),
    ('answer_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', '树'),
    ('riddle_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', '有了它你能做奇妙的事。`n可看近物，也可看远物，`n能看见大的，`n也能看见小的。`n或许你什么也看不见。`n我有各种颜色与色调，`n有时是绿，有时是蓝。`n我发红时并非因为羞愧，`n而是因为另有名目之物。'),
    ('answer_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', '眼睛'),
    ('riddle_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', '哦，我多爱我这跳舞的脚！`n它们凑在一起——这般齐整。`n我若想走成一条直线，`n它们便一齐加倍地动。`n我数过十遍还不止，`n又在地板上来回奔走。'),
    ('answer_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', '蜈蚣；马陆'),
    ('riddle_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', '圈栏里传来低沉的咕哝，`n我走着走着便停下往里看。`n我看见的是什么？`n一头庞然巨兽，有蹄有颚。`n威严的额上生着尖角，`n我看着它踢踏泥土来回踱步。`n然而尽管如此威武，`n它却出不了那道木栅栏。'),
    ('answer_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', '公牛'),
    ('riddle_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', '那是我必须讲述`n我所参与之事的`n那一天的夜里。`n太阳出着`n一声不吭地`n悄悄进去了。`n真是古怪`n我以为他会瞪我`n可我一句话也插不上。`n又是一言不发`n（至少我听来如此）`n他就回到原处去了。'),
    ('answer_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', '日食'),
    ('riddle_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', '从日出到日落我凝望大海。`n从日落到日出我凝望大海。`n但日出时我只能在光亮中眨眼。`n日落后我却能把光亮眨出去。'),
    ('answer_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', '灯塔'),
    ('riddle_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', '吠声（树皮）不少，`n却无人留意。`n可咬之处甚多，`n人人都在意。`n我不是狗，`n若有人留意的话。`n我身上东西不少，`n却没有毛发。`n我笔直站立，`n若你曾注意到我。`n我有许多肢干，`n若有人在意的话。`n我能给你阴凉，`n若你曾察觉。`n而我做的还不止于此，`n我给你空气。'),
    ('answer_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', '树'),
    ('riddle_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', '那是十二月还是六月，`n我家夫人昏倒的时候。`n她的头发脱落，`n眼镜也不见了的时候。`n她尖叫起来的时候，`n那模样实在难看。`n一边指着我，`n一边喊着“呀啊！呀啊！”`n我得说这未免过头了些，`n毕竟我谁也没碰。`n但显然是`n出了什么岔子。`n于是我决定改日再来，`n或许趁她不在的时候。'),
    ('answer_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', '老鼠'),
    ('riddle_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', '我漂流，`n慢如一条懒河。`n我起舞，`n凭着一缕微风。`n我翻滚，`n胜过最了不起的杂技艺人。`n盘旋，`n打转，`n落到地上。`n我便躺在那里，`n直到再得一阵风。`n于是我又能重新开始。'),
    ('answer_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', '树叶'),
    ('riddle_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', '一个易解的谜。`n红胸脯。`n万千之中仅此一个。`n生于蛋中。`n受启而歌。`n现在把字母凑起来，说说我是什么意思。'),
    ('answer_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', '知更鸟'),
    ('riddle_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', '这东西我有四个，`n各自末端还配着一套。`n它们能做许多事，`n也极少让我疼痛。`n除非我用针去扎它们，`n或者有时把它们烫着……`n我能随意扭动、`n还能派上别的用场的这是什么？'),
    ('answer_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', '手指'),
    ('riddle_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', '当我望见他情热的火焰，`n与她触碰的清冷，`n我便知他们的结合只能生出悲剧。`n果然，当他们相会之时，`n黑暗统治了大地。`n虽然他们不久便分开，`n明白彼此并不相宜，`n然而他们擦身而过的那一眼，`n却在所有目睹者心上留下印记，`n并将被传说许多世代。'),
    ('answer_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', '日食'),
    ('riddle_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', '什么东西有外套？`n拥抱你却非出于同情？`n它的笑容你宁可不见？`n它的架势看着就可怕？`n勇者见了都要逃开的是谁？`n手指生着利爪的是谁？`n一睡数月的是谁？`n而我们避之唯恐不及的又是谁？'),
    ('answer_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', '熊'),
    ('riddle_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', '你可以在上面翻滚，`n也可以在上面打滚，`n可以烧它，`n牲口吃它，`n用来铺地，`n马厩门外也照样用它。`n它使所铺之处清爽，`n把倒在其上的一切吸干。`n它是什么？'),
    ('answer_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', '干草'),
    ('riddle_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', '在百香果里能找到它们，`n石榴的冠中更多。`n苹果核里它们成排，`n别的果子里还要更多。`n油桃虽只有一个，`n这一切也不过是玩笑。`n捉迷藏——孩童的游戏。`n找出来才发现，参与者原来都一样。'),
    ('answer_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', '种子'),
    ('riddle_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', '它在天堂被低语，在地狱被嘟囔，`n回声在它坠落时隐约将其捕捉；`n在大地的边界它被允许安歇，`n在海洋的深处它也显露踪迹；`n天穹裂开时将在其中被发现，`n在闪电中被看见，在雷霆中被听闻；`n它随人最初的呼吸一同赋予，`n出生时伴他左右，死时等他到来，`n主宰他的幸福、荣誉与健康，`n是他家宅的支柱，也是他财富的终点。`n在守财奴的堆积中被小心珍藏，`n却注定丧失于挥霍的继承人手里；`n它开启每一个希望，界定每一个愿望，`n与农夫一同劳作，与君王一同加冕；`n没有它，士兵与水手仍可漂泊，`n但把它逐出家门的可怜人有祸了！`n在良心的低语中能寻见它的声音，`n在情欲的旋风中也绝不会被淹没；`n它能软化心肠；纵使耳朵失聪，`n也会使他敏锐而即刻地听见。`n把它置于荫处，让它如娇花般安歇；`n啊！轻轻地对它呼气，一小时它便死去'),
    ('answer_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', '字母H；H'),
    ('riddle_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', '我们是些轻盈如气的小东西，`n各有各的声音与模样；`n我们之中有一个在玻璃（glass）里，`n有一个你能在黑玉（jet）中找到，`n另一个你可在锡（tin）里见着，`n第四个则在盒子（box）之内；`n你若去追第五个，`n它永远逃不出你的掌心。'),
    ('answer_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', '元音'),
    ('riddle_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', '我是个奇怪的矛盾体；我既新又旧，`n常常破烂不堪，又常以黄金装点。`n我从不识字，身上却满是字母；`n我目盲却能启人，我松散却被装订。`n我总是黑的，我也总是白的；`n我庄重又欢快，我沉重又轻盈——`n形制上也各异——我厚也我薄，`n我无血无骨，却被皮所覆盖；`n我的点比罗盘多，我的停顿比长笛多；`n我无声而歌，不言而驳。`n我是英国人，是德国人，是法国人，也是荷兰人；`n有人待我过分痴迷，有人待我过分轻慢；`n我常常早夭，有时却活上几世；`n世上没有哪位君主拥有我这么多侍从（书页）。'),
    ('answer_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', '书'),
    ('riddle_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', '我穿过花园的缺口时，`n遇见的不是别人，正是红帽子迪克！`n手里一根棍，喉里一块石。`n你若解得此谜，我便给你一枚银币。'),
    ('answer_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', '樱桃'),
    ('riddle_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', '小南希·艾提科特，`n穿着白衬裙，`n生着红鼻子；`n她站得越久`n个头越矮。'),
    ('answer_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', '蜡烛'),
    ('riddle_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', '我有个小妹妹，人们叫她啾啾；`n她涉过深深深深的水；`n她爬上高高高高的山；`n可怜的小家伙只有一只眼睛。'),
    ('answer_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', '星'),
    ('riddle_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', '我看见一队人马在行进，`n跨过大海行进。`n望着他们，`n我问自己“那会是什么？”`n那里有一匹马，`n还有一头牛，`n还有人们在行进，`n带着房屋和树木。可这怎么可能？`n我看见一队人马在行进，`n跨过大海行进。`n我在歇息中纳闷，`n自己该有多懒。'),
    ('answer_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', '天上的云；云'),
    ('riddle_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', '我在上。`n我在下。`n我无处不在。`n却永远找不着我。`n我是谁？'),
    ('answer_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', '风'),
    ('riddle_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', '我可以被移动。`n我可以被滚动。`n但我什么也装不下。`n我是红的，也是蓝的。`n我还可以是别的颜色。`n没有头，形状却相似，`n没有眼睛——却四处游走。`n我是什么？'),
    ('answer_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', '球'),
    ('riddle_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', '你可以踏在我身上，`n在遮盖之下轻轻地踏。`n我会带你去`n你尚未发现的地方。`n我时高时低，`n中间却是平的。`n虽是孩子的欢乐，`n大人却不把我放在心上。`n我是什么？'),
    ('answer_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', '楼梯'),
    ('riddle_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', '什么东西筑起万物？`n夷平山峦？`n使湖泊干涸，`n又让万物生长？`n对你的逝去毫不在意？`n且与别物大不相同，`n因为它永不止息？'),
    ('answer_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', '时间'),
    ('riddle_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', '它落在柳树上，`n轻轻向我歌唱。`n以歌声抚平我的痛楚与哀伤，`n我本想飞走，却久久停留。`n在我的苦痛之中，`n那柳树宛如清凉的泉。`n是什么这样帮了我？`n陪我度过忧愁的时光。'),
    ('answer_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', '鸟'),
    ('riddle_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', '它们可以被怀抱，却少有能盛水的，`n你可以哺育它们，但只能把它们对着别人，`n你可以携带它们，却不是用手臂，`n你可以埋葬它们，却不是埋在土里。'),
    ('answer_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', '怨恨'),
    ('riddle_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', '深如碗，圆如杯，`n可世上所有的海水也填不满它。'),
    ('answer_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', '筛子'),
    ('riddle_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', '沙漠中人曾称我为神，`n如今人们却说我疯癫，`n因为我恼怒时摇尾，`n欢喜时低吼。'),
    ('answer_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', '猫'),
    ('riddle_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', '我听闻一支入侵而所向披靡的大军`n如水般迅疾席卷大地；`n征服一切，压平抵抗。`n随之而来的是黑暗，遮蔽了光。`n人们躲在屋里，屋外`n长矛穿刺，击碎石墙。`n无数士兵砸进地里，`n但每一个死去时都唤出了生命；`n当大军消失、北进而去，`n大地已一片青绿，焕然更新。'),
    ('answer_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', '暴雨；雨'),
    ('riddle_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '“我能找到看不见之物，也能看见找不到之物。`n前者是时间，后者是我眼前的斑点。”'),
    ('answer_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '时间'),
    ('riddle_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', '我能感受到摸不着之物，也能摸到感受不到之物。`n前者悲哀可怜，后者是你的心。'),
    ('answer_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', '心'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', '从不在前，永远在后，`n却疾驰而过；`n于孩童我永恒，`n于成人我去得太快。'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', '青春'),
    ('riddle_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', '她身量高挑，圆如杯盏，`n可国王所有的马`n也拉不起她。'),
    ('answer_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', '井'),
    ('riddle_text', 'There more of it there is,`nThe less you see.', '它越多，`n你看见的越少。'),
    ('answer_text', 'There more of it there is,`nThe less you see.', '黑暗'),
    ('riddle_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', '什么对一个人不够，`n对两个人正好，`n对三个人又太多？'),
    ('answer_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', '秘密'),
    ('riddle_text', 'What gets wetter the more it dries?', '什么东西越擦越湿？'),
    ('answer_text', 'What gets wetter the more it dries?', '毛巾'),
    ('riddle_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', '一条长蛇，`n咬起来如同螫刺，`n我会一直盘着`n除非非战不可。'),
    ('answer_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', '鞭子'),
    ('riddle_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', '花丛中的战士，`n他佩着一柄可刺之剑。`n随时能用且善用，`n为的是守护他金色的库藏。'),
    ('answer_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', '蜜蜂'),
    ('riddle_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', '负重者，战士，`n受惊者，勇者，`n疾足者，蹄铁加身者，`n忠诚者，奴仆。'),
    ('answer_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', '马'),
    ('riddle_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', '在风中行走`n在雨中奔跑`n在阳光下造出干涸的海。`n计量时间，令钟表停摆，`n吞没王国，啃噬岩石。'),
    ('answer_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', '沙'),
    ('riddle_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', '起伏的丘陵，永远跳动的心，`n从不改变、从不静止的土地，`n被远离家园的旅人犁过，却未曾播种，`n怒时白，静时绿，而且永远是蓝的。'),
    ('answer_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', '海'),
    ('riddle_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', '仔细听，我难以理解，`n我如一把沙子般难以把握。`n纵使你察觉了我，你仍不识我，`n除非你能说出我遗忘了什么。'),
    ('answer_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', '谜语'),
    ('riddle_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', '什么东西过门而不夹到自己？`n什么东西坐在炉上而不烫伤自己？`n什么东西坐在桌上却不害臊？'),
    ('answer_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', '太阳'),
    ('riddle_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', '我正坐着的时候`n看见死者驮着生者。`n我看见的是什么？'),
    ('answer_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', '船'),
    ('riddle_text', 'I know a word of letters three,`nAdd two and fewer there will be.', '我知道一个三个字母的词，`n再加两个反而更少。'),
    ('answer_text', 'I know a word of letters three,`nAdd two and fewer there will be.', '少'),
    ('riddle_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', '造它的人不需要它，`n买它的人用不上它，`n用它的人既看不见也感觉不到它。'),
    ('answer_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', '棺材'),
    ('riddle_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', '造它的人不需要它。`n买它的人没有用它。`n用它的人并不想要它。'),
    ('answer_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', '棺材'),
    ('riddle_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', '你抓住了我，我却逃走了；`n你看着我逃，却握不紧我。`n你把我按在手中，拳头却是空的。`n我是什么？'),
    ('answer_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', '雪'),
    ('riddle_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', '什么东西早晨四条腿，`n下午两条腿，`n傍晚三条腿？'),
    ('answer_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', '人'),
    ('riddle_text', 'What is deaf, dumb and blind`nand always tells the truth ?', '什么东西又聋又哑又瞎`n却总说真话？'),
    ('answer_text', 'What is deaf, dumb and blind`nand always tells the truth ?', '镜子'),
    ('riddle_text', 'What is always in front of you`nbut cannot be seen?', '什么东西总在你面前`n却看不见？'),
    ('answer_text', 'What is always in front of you`nbut cannot be seen?', '未来'),
    ('riddle_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', '什么东西人爱之胜于生命，`n恨之甚于死亡或殊死之争；`n知足者渴求它，`n穷人拥有它，富人需要它；`n吝啬者花掉它，挥霍者积攒它，`n且人人都带着它进坟墓？'),
    ('answer_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', '无'),
    ('riddle_text', 'A life longer than any man,`nit dies each year to be reborn.', '比任何人都长的生命，`n它年年死去又重生。'),
    ('answer_text', 'A life longer than any man,`nit dies each year to be reborn.', '树'),
    ('riddle_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', '入眼便致盲，`n入鼻只打喷嚏；`n可有人偏要吸它，`n还装作乐在其中。'),
    ('answer_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', '烟'),
    ('riddle_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', '它独自而立，无骨无固形。`n坚定不移，从不出错，`n尽管它可能伤人。`n它可扭可揉，`n却始终笔直如箭。'),
    ('answer_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', '真相'),
    ('riddle_text', 'What sphinxes employ,`nthe players enjoy.', '斯芬克斯所使用的，`n游戏者所享受的。'),
    ('answer_text', 'What sphinxes employ,`nthe players enjoy.', '谜语'),
    ('riddle_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', '有个人我总在他身旁，`n可在黑暗中我便消失。`n我只对他一人忠诚，`n注定要在他身后劳碌。`n他感觉不到我（我们却始终相触）；`n我若丢了，他也损失不大。`n如今我要说出令人惊讶之处，`n因为他就是你——那么我是谁？'),
    ('answer_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', '影子'),
    ('riddle_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', '我常被握住，却少被触碰；`n我总是湿的，却从不生锈；`n我时而被摇动，时而被咬住；`n要善用我，你得有几分机智。'),
    ('answer_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', '舌头'),
    ('riddle_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', '她坐在窗边哭泣。`n每一滴泪落下，她的生命便渗走一分。'),
    ('answer_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', '蜡烛'),
    ('riddle_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', '我其实不过是把一个个洞`n串在一起；`n我像好钢一样结实，却不像杆子`n那样僵硬。'),
    ('answer_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', '锁链'),
    ('riddle_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', '我力气不大，权能却大；`n我守护小屋，也守护高塔。`n可若我的主人偶然离开，`n他必须确保把我看管好。'),
    ('answer_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', '钥匙'),
    ('riddle_text', 'Delivered by breath,`nscares heroes to death.', '由呼吸传递，`n吓得英雄要死。'),
    ('answer_text', 'Delivered by breath,`nscares heroes to death.', '谜语'),
    ('riddle_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', '白天我如水洼般铺开，`n夜里我如雾般笼罩。`n我钻进关紧的箱子里`n也钻进你攥紧的拳头中。`n看不见时你才最看得见我，`n因为我并不存在。'),
    ('answer_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', '黑暗'),
    ('riddle_text', 'Devils and rogues know nothing else,`nsave starlight.', '除了星光之外，`n魔鬼与恶棍一无所知。'),
    ('answer_text', 'Devils and rogues know nothing else,`nsave starlight.', '黑暗'),
    ('riddle_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', '国王与马都有此物，`n但你两者都不会想要。'),
    ('answer_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', '统治；缰绳'),
    ('riddle_text', 'My spring up on the cliff.', '我在崖上的泉。'),
    ('answer_text', 'My spring up on the cliff.', '椰子'),
    ('riddle_text', 'Three walls and you reach water.', '穿过三堵墙便见水。'),
    ('answer_text', 'Three walls and you reach water.', '椰子'),
    ('riddle_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', '我的卡帕（一种布）原木`n不停地响个不住。'),
    ('answer_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', '海'),
    ('riddle_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', '早晨四条腿，`n中午两条腿，`n傍晚三条腿。'),
    ('answer_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', '人'),
    ('riddle_text', 'My man that cannot be cut.', '我那砍不断的人。'),
    ('answer_text', 'My man that cannot be cut.', '影子'),
    ('riddle_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', '我的独木舟日夜前行，`n十个船首，两个船尾。'),
    ('answer_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', '某人的双脚'),
    ('riddle_text', 'My red cave, white soldiers standing in line.', '我的红色洞穴，白色士兵列队而立。'),
    ('answer_text', 'My red cave, white soldiers standing in line.', '某人的嘴'),
    ('riddle_text', 'My man crying day and night,`nall through the year.', '我那日夜哭泣的人，`n终年不休。'),
    ('answer_text', 'My man crying day and night,`nall through the year.', '海')
  ) AS source
  JOIN riddle ON riddle.riddle_text = source.column2;

DELETE FROM catalog_translation WHERE entity_type = 'riddle' AND locale_code = 'ru';

INSERT INTO catalog_translation (entity_type, entity_id, field_code, locale_code, translation_text)
SELECT 'riddle', riddle.riddle_id, source.column1, 'ru', source.column3
  FROM (VALUES
    ('riddle_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', 'Ты ешь то, чего не сеял и не пахал.`nОно — сын воды, но, коснувшись воды, умирает.'),
    ('answer_text', 'You eat something you neither plant nor plow.`nIt is the son of water, but if water touches it, it dies.', 'Соль'),
    ('riddle_text', 'Teacher, open thy book.', 'Учитель, открой свою книгу.'),
    ('answer_text', 'Teacher, open thy book.', 'Бабочка'),
    ('riddle_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', 'Мои зубцы длинны.`nМои зубцы коротки.`nМои зубцы кончаются прежде,`nчем придёт первая весть обо мне.'),
    ('answer_text', 'My tines are long.`nMy tines are short.`nMy tines end ere`nMy first report.', 'Молния'),
    ('riddle_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', 'Переверни нас на спину`nи вскрой нам животы —`nстанешь мудрейшим из людей,`nхоть поначалу был увальнем.'),
    ('answer_text', 'Turn us on our backs`nAnd open up our stomachs`nYou will be the wisest of men`nThough at start a lummox.', 'Книга'),
    ('riddle_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', 'Зарой поглубже,`nзавали камнями,`nи всё же я`nвыкопаю кости.'),
    ('answer_text', 'Bury deep,`nPile on stones,`nYet I will`nDig up the bones.', 'Воспоминания'),
    ('riddle_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', 'Оно случается раз в каждую минуту,`nдважды в каждое мгновение`nи ни разу за сто тысяч лет.'),
    ('answer_text', 'It occurs once in every minute`nTwice in every moment`nAnd yet never in one hundred thousand years.', 'Буква «М»; М'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', 'Никогда впереди, всегда позади,`nи всё же стремительно проносится мимо;`nдля ребёнка я длюсь вечно,`nдля взрослых я исчезаю слишком быстро.'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past;`nFor a child I last forever,`nFor adults I''m gone too fast.', 'Детство'),
    ('riddle_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', 'Два коня, быстрее всех бегущих,`nзапряжённые в пару, и`nвечно пасущиеся в местах,`nдалёких от них самих.'),
    ('answer_text', 'Two horses, swiftest travelling,`nHarnessed in a pair, and`nGrazing ever in places`nDistant from them.', 'Твои глаза; солнце и луна'),
    ('riddle_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', 'Можно сказать так:`nбыть золотым — значит быть добрым;`nбыть каменным — значит быть ничем;`nбыть стеклянным — значит быть хрупким;`nбыть холодным — значит быть жестоким.`nБез метафор — что я такое?'),
    ('answer_text', 'It can be said:`nTo be gold is to be good;`nTo be stone is to be nothing;`nTo be glass is to be fragile;`nTo be cold is to be cruel.`nUnmetaphored, what am I?', 'Сердце'),
    ('riddle_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', 'Кругла она, но плоска, как доска,`nалтарь Волчьих Владык.`nСамоцвет на чёрном бархате, жемчужина в море,`nнеизменная, но вечно меняющаяся.'),
    ('answer_text', 'Round she is, yet flat as a board`nAltar of the Lupine Lords.`nJewel on black velvet, pearl in the sea`nUnchanged but e''erchanging, eternally.', 'Луна'),
    ('riddle_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', 'У него золотая голова,`nу него золотой хвост,`nно нет туловища.'),
    ('answer_text', 'It has a golden head`nIt has a golden tail`nbut it hasn''t got a body.', 'Золотая монета; монета'),
    ('riddle_text', 'Speak, friend, and enter!', 'Скажи, друг, и войди!'),
    ('answer_text', 'Speak, friend, and enter!', 'Друг'),
    ('riddle_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', 'Кожаная змея`nс жалящим укусом,`nя буду лежать свёрнутой,`nесли только не придётся драться.'),
    ('answer_text', 'A leathery snake,`nWith a stinging bite,`nI''ll stay coiled up,`nUnless I must fight.', 'Кнут'),
    ('riddle_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', 'У чего корни, которых никто не видит,`nчто выше деревьев,`nвверх и вверх поднимается,`nи всё же никогда не растёт?'),
    ('answer_text', 'What has roots as nobody sees,`nIs taller than trees,`nUp, up it goes,`nAnd yet never grows?', 'Гора'),
    ('riddle_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', 'Тридцать белых коней на красном холме:`nсперва грызут,`nпотом топчут,`nа потом стоят смирно.'),
    ('answer_text', 'Thirty white horses on a red hill,`nFirst they champ,`nThen they stamp,`nThen they stand still.', 'Зубы'),
    ('riddle_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', 'Без голоса кричит,`nбез крыльев порхает,`nбез зубов кусает,`nбез рта бормочет.'),
    ('answer_text', 'Voiceless it cries,`nWingless it flutters,`nToothless bites,`nMouthless mutters.', 'Ветер'),
    ('riddle_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', 'Его не увидеть и не пощупать,`nне услышать и не учуять.`nОно лежит за звёздами и под холмами,`nи заполняет пустые ямы.`nОно приходит первым и следует после,`nобрывает жизнь, убивает смех.'),
    ('answer_text', 'It cannot be seen, cannot be felt,`nCannot be heard, cannot be smelt.`nIt lies behind stars and under hills,`nAnd empty holes it fills.`nIt comes first and follows after,`nEnds life, kills laughter.', 'Тьма'),
    ('riddle_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', 'Ларец без петель, ключа и крышки,`nа внутри спрятано золотое сокровище.'),
    ('answer_text', 'A box without hinges, key, or lid,`nYet golden treasure inside is hid.', 'Яйца; апельсины'),
    ('riddle_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', 'Живое без дыхания,`nхолодное, как смерть;`nникогда не жаждет, но вечно пьёт,`nвсё в кольчуге, но не звенит.'),
    ('answer_text', 'Alive without breath,`nAs cold as death;`nNever thirsty, ever drinking,`nAll in mail never clinking.', 'Рыба'),
    ('riddle_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', 'Это пожирает всё:`nптиц, зверей, деревья, цветы;`nгрызёт железо, кусает сталь;`nтвёрдые камни перемалывает в муку;`nубивает королей, разрушает города`nи сравнивает с землёй высокие горы.'),
    ('answer_text', 'This thing all things devours:`nBirds, beast, trees, flowers;`nGnaws iron, bites steel;`nGrinds hard stones to meal;`nSlays king, ruins town,`nAnd beats high mountain down.', 'Время'),
    ('riddle_text', 'You feel it, but never see it and never will.', 'Ты его чувствуешь, но никогда не видел и не увидишь.'),
    ('answer_text', 'You feel it, but never see it and never will.', 'Сердце'),
    ('riddle_text', 'You must keep it after giving it.', 'Это надо хранить и после того, как отдал.'),
    ('answer_text', 'You must keep it after giving it.', 'Слово'),
    ('riddle_text', 'As light as a feather, but you can''t hold it for ten minutes.', 'Легко, как пёрышко, но и десяти минут не удержишь.'),
    ('answer_text', 'As light as a feather, but you can''t hold it for ten minutes.', 'Дыхание'),
    ('riddle_text', 'Has a mouth but does not speak, has a bed but never sleeps.', 'Есть рот, но не говорит; есть ложе, но никогда не спит.'),
    ('answer_text', 'Has a mouth but does not speak, has a bed but never sleeps.', 'Река'),
    ('riddle_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', 'Течёт глаже любой рифмы, обожает падать, но не умеет взбираться!'),
    ('answer_text', 'Runs smoother than any rhyme, loves to fall but cannot climb!', 'Вода'),
    ('riddle_text', 'You break it even if you name it!', 'Ты нарушаешь его, даже просто назвав!'),
    ('answer_text', 'You break it even if you name it!', 'Тишина'),
    ('riddle_text', 'It passes before the sun and makes no shadow.', 'Оно проходит перед солнцем и не отбрасывает тени.'),
    ('answer_text', 'It passes before the sun and makes no shadow.', 'Воздух'),
    ('riddle_text', 'You feed it, it lives, you give it something to drink, it dies.', 'Покормишь — живёт, дашь попить — умирает.'),
    ('answer_text', 'You feed it, it lives, you give it something to drink, it dies.', 'Огонь'),
    ('riddle_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', 'Красный барабан, что звучит,`nкогда его не касаются,`nи умолкает,`nкогда к нему прикасаются.'),
    ('answer_text', 'A red drum which sounds`nWithout being touched,`nAnd grows silent,`nWhen it is touched.', 'Сердце'),
    ('riddle_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', 'Урожай, посеянный и сжатый в один день`nна невспаханном поле,`nкоторый прибывает, не вырастая,`nостаётся целым, хоть его едят`nизнутри и снаружи,`nбесполезен и всё же`nосновная пища народов.'),
    ('answer_text', 'A harvest sown and reaped on the same day`nIn an unplowed field,`nWhich increases without growing,`nRemains whole though it is eaten`nWithin and without,`nIs useless and yet`nThe staple of nations.', 'Война'),
    ('riddle_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', 'Если ты меня сломаешь,`nя не перестану работать;`nесли коснёшься меня,`nменя можно поймать в силок;`nесли потеряешь меня,`nничто уже не будет иметь значения.'),
    ('answer_text', 'If you break me`nI do not stop working,`nIf you touch me`nI may be snared,`nIf you lose me`nNothing will matter.', 'Надежда'),
    ('riddle_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', 'Повсюду, но не видно,`nможно поймать, но не удержать;`nгорла нет, а слышно.'),
    ('answer_text', 'All about, but cannot be seen,`nCan be captured, cannot be held`nNo throat, but can be heard.', 'Звуки; шумы'),
    ('riddle_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', 'Я хожу кругами,`nно всегда прямо вперёд;`nникогда не жалуюсь,`nкуда бы меня ни вели.'),
    ('answer_text', 'I go around in circles,`nBut always straight ahead`nNever complain,`nNo matter where I am led.', 'Колесо'),
    ('riddle_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', 'Легче того,`nиз чего я сделан,`nи скрыто во мне больше,`nчем видно.'),
    ('answer_text', 'Lighter than what`nI am made of,`nMore of me is hidden`nThan is seen.', 'Айсберг'),
    ('riddle_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', 'Если бы человек нёс мою ношу,`nон сломал бы спину.`nЯ не богат,`nно оставляю за собой серебро.'),
    ('answer_text', 'If a man carried my burden,`nHe would break his back.`nI am not rich,`nBut leave silver in my track.', 'Улитка'),
    ('riddle_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', 'Мою жизнь измеряют часами,`nя служу тем, что меня пожирают.`nТонкий — я быстр,`nтолстый — я медлен;`nветер — мой враг.'),
    ('answer_text', 'My life can be measured in hours,`nI serve by being devoured.`nThin, I am quick`nFat, I am slow`nWind is my foe.', 'Свеча'),
    ('riddle_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', 'Тяжесть в брюхе,`nдеревья на спине,`nгвозди в рёбрах,`nа ног нет.'),
    ('answer_text', 'Weight in my belly,`nTrees on my back,`nNails in my ribs,`nFeet I do lack.', 'Корабль; пещера'),
    ('riddle_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', 'Ты не увидишь ничего другого,`nкогда посмотришь мне в лицо.`nЯ взгляну тебе в глаза`nи никогда не солгу.'),
    ('answer_text', 'You can see nothing else`nWhen you look in my face`nI will look you in the eye`nAnd I will never lie.', 'Зеркало'),
    ('riddle_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', 'Я вечно голоден,`nменя надо постоянно кормить;`nпалец, который я лизну,`nвскоре покраснеет.'),
    ('answer_text', 'I am always hungry,`nI must always be fed,`nThe finger I lick`nWill soon turn red.', 'Огонь'),
    ('riddle_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', 'У меня три жизни.`nДостаточно нежен, чтобы утешить кожу,`nдостаточно лёгок, чтобы ласкать небо,`nдостаточно твёрд, чтобы дробить камни.'),
    ('answer_text', 'Three lives have I.`nGentle enough to soothe the skin,`nLight enough to caress the sky`nHard enough to crack rocks.', 'Вода'),
    ('riddle_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', 'Сверкающие острия,`nустремлённые вниз,`nискрящиеся копья,`nчто никогда не ржавеют.'),
    ('answer_text', 'Glittering points`nThat downward thrust,`nSparkling spears`nThat never rust.', 'Сосульки'),
    ('riddle_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', 'Каждое утро я появляюсь,`nчтобы лечь у твоих ног;`nвесь день я следую за тобой,`nкак быстро ты бы ни бежал,`nи всё же почти гибну`nв полуденном солнце.'),
    ('answer_text', 'Each morning I appear`nTo lie at your feet,`nAll day I follow`nNo matter how fast you run,`nYet I nearly perish`nIn the midday sun.', 'Тень'),
    ('riddle_text', 'Keys without locks`nYet I unlock the soul.', 'Ключи без замков,`nи всё же я отпираю душу.'),
    ('answer_text', 'Keys without locks`nYet I unlock the soul.', 'Пианино; клавесин'),
    ('riddle_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', 'Я так прост,`nчто умею лишь указывать,`nи всё же веду людей`nпо всему свету.'),
    ('answer_text', 'I am so simple,`nThat I can only point`nYet I guide men`nAll over the world.', 'Компас'),
    ('riddle_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', 'За нашу амброзию Юпитер`nблагословил нас смертельным жалом.`nПусть наша мощь кому-то и смешна,`nмы усмиряли дыхание дракона.`nКто мы?'),
    ('answer_text', 'For our ambrosia we were blessed,`nby Jupiter, with a sting of death.`nThough our might, to some is jest,`nwe have quelled the dragon''s breath.`nWho are we?', 'Пчёлы'),
    ('riddle_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', 'Цвета девичьих щёк, тронутых румянцем;`nкогда я начиналось, времени ещё не было;`nменя тайком пронесли через сад,`nи я одно стало падением человека.`nЧто я?'),
    ('answer_text', 'Colored as a maiden tweaked,`ntime was naught when I began;`nthrough the garden I was sneaked,`nI alone am the fall of man.`nWhat am I?', 'Яблоко'),
    ('riddle_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', 'Один там, где не должно быть ни одного,`nили, быть может, там, где должно быть двое,`nищущий чистоты`nв королевских лесах.`nЧто я?'),
    ('answer_text', 'One where none should be,`nor maybe where two should be,`nseeking out purity,`nin the kings trees.`nWhat am I?', 'Единорог'),
    ('riddle_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', 'Один зуб, чтобы кусать, —`nон враг лесов.`nОдин зуб, чтобы драться, —`nкак ведомо всем северянам.`nЧто это?'),
    ('answer_text', 'One tooth to bite,`nhe''s the forests foe.`nOne tooth to fight,`nas all Norse know.`nWhat is it?', 'Топор'),
    ('riddle_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', 'Та часть птицы,`nчто не в небе,`nкоторая может плавать в океане`nи всегда оставаться сухой.`nЧто это?'),
    ('answer_text', 'The part of the bird`nthat is not in the sky,`nwhich can swim in the ocean`nand always stay dry.`nWhat is it?', 'Тень птицы; тень'),
    ('riddle_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', 'У этой перевёрнутой вещи`nкорень венчает ствол;`nона растёт зимой`nи умирает весной.`nЧто это?'),
    ('answer_text', 'The root tops the trunk`non this backward thing,`nthat grows in the winter`nand dies in the spring.`nWhat is it?', 'Сосулька'),
    ('riddle_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', 'Касаясь одного, но держа двоих,`nэто цепь в одно звено,`nсвязывающая тех, кто верен слову,`nпока смерть не разорвёт её надвое.`nЧто это?'),
    ('answer_text', 'Touching one, yet holding two,`nit is a one link chain`nbinding those who keep words true,`n''til death rent it in twain.`nWhat is it?', 'Обручальное кольцо; кольцо'),
    ('riddle_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', 'Мудрый и знающий уверен в этом.`nДаже глупец это знает.`nБогач этого хочет.`nВеличайший из героев этого боится.`nИ всё же ничтожнейший из трусов умрёт за это.`nО чём же я размышляю?'),
    ('answer_text', 'The wise and knowledgeable man is sure of it.`nEven the fool knows it.`nThe rich man wants it.`nThe greatest of heroes fears it.`nYet the lowliest of cowards would die for it.`nWhat is this upon which I ponder?', 'Ничто; нечто'),
    ('riddle_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', 'Что больше Бога,`nхуже Дьявола,`nмертвецы это едят,`nа съешь ты — умрёшь?'),
    ('answer_text', 'What is greater than God,`nWorse than the Devil,`nDead man eat it,`nIf you eat it you''ll die.', 'Ничто'),
    ('riddle_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', 'Я — чудесная помощь женщинам,`nнадежда на грядущее. Я не причиняю вреда`nникому, кроме своего убийцы.`nУкоренённый, я стою на высоком ложе.`nСнизу я лохмат. Порой прекрасная`nдочь крестьянина, нетерпеливая,`nгордая женщина хватает моё тело,`nсдирает мою красную кожу, крепко держит,`nзавладевает моей головой. Кудрявая`nженщина, что схватит меня, почувствует`nнашу встречу. Глаз её увлажнится.'),
    ('answer_text', 'I am a wonderful help to women,`nThe hope of something to come. I harm`nNo citizen except my slayer.`nRooted I stand on a high bed.`nI am shaggy below. Sometimes the beautiful`nPeasant''s daughter, an eager-armed,`nProud woman grabs my body,`nRushes my red skin, holds me hard,`nClaims my head. The curly-haired`nWoman who catches me fast will feel`nOur meeting. Her eye will be wet.', 'Луковица'),
    ('riddle_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', 'Мощь и сокровище в руке государя,`nтвёрдый, с крутыми щеками, окутанный красным`nзолотом и гранатом, вырванный с равнины`nярких цветов, выкованный — остаток`nогня и напильника, связанный в суровой красоте`nтонкой проволокой; хватка моя заставляет`nвоинов плакать, жало моё грозит`nруке, что тянется к золоту. Украшенный`nкольцом, я разоряю наследника и наследие.`nДля господина и для врагов я всегда прекрасен`nи смертоносен, меняя лик и облик.'),
    ('answer_text', 'Power and treasure for a prince to hold,`nHard and steep-cheeked, wrapped in red`nGold and garnet, ripped from a plain`nOf bright flowers, wrought - a remnant`nOf fire and file, bound in stark beauty`nWith delicate wire, my grip makes`nWarriors weep, my sting threatens`nThe hand that grasps gold. Studded`nWith a ring, I ravage heir and heirloom.`nTo my lord and foes always lovely`nAnd deadly, altering face and form.', 'Меч'),
    ('riddle_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', 'Когда я шёл в Сент-Айвс,`nнавстречу мне шёл человек с семью жёнами;`nу каждой жены было по семь мешков,`nв каждом мешке — по семь кошек,`nу каждой кошки — по семь котят.`nКотята, кошки, мешки и жёны —`nсколько же их шло в Сент-Айвс?'),
    ('answer_text', 'As I was going to St. Ives,`nI met a man with seven wives;`nEvery wife had seven sacks,`nEvery sack had seven cats,`nEvery cat had seven kits:`nKits, cats, sacks, and wives,`nHow many were there going to St. Ives?', 'Один'),
    ('riddle_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', 'Рассвет уходит,`nдень посерел,`nи мне пора в дальний путь.`nНо я вернусь,`nи тогда мы вместе проследим`nсвет ещё одного дня.'),
    ('answer_text', 'Dawns away,`nThe day''s turned grey,`nAnd I must travel far away.`nBut I''ll be back,`nAnd then we''ll track,`nThe light of yet another day.', 'Солнце; тень'),
    ('riddle_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', 'Глубоко, темно, под землёй —`nвот где меня находят.`nНо вынеси меня на дневной свет,`nи я разбрызгиваю солнце во все стороны.`nПусть меня находят потускневшим от масла,`nя на удивление целый и крепкий.`nОгранишь меня быстро — и станет видно,`nчто я мгновенно обретаю дивный блеск.'),
    ('answer_text', 'Deep, dark, underground,`nThat is the place where I''ll be found.`nYet brought into the light of day,`nI sprinkle sunlight every-which-a-way.`nThough dulled with oil I will be found,`nI am remarkably well and throughly sound.`nCut me quick and it will be seen,`nThat I instantly have a marvelous sheen.', 'Алмаз; самоцвет'),
    ('riddle_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', 'Что должно быть в печи, но не выпекается?`nЧто растёт в тепле, но избегает дневного света?`nЧто тонет в воде, но поднимается с воздухом?`nЧто похоже на кожу, но тонко, как волос?'),
    ('answer_text', 'What must be in the oven yet can not be baked?`nGrows in the heat yet shuns the light of day?`nWhat sinks in water but rises with air?`nLooks like skin, but is fine as hair?', 'Дрожжи'),
    ('riddle_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', 'Малыш Джонни Уокер,`nох и болтун же он был!`nНо ни словечка не вымолвил!`nА когда я его доставал,`nвсе показывали пальцем и кричали!`nИ просили убрать его обратно.'),
    ('answer_text', 'Little Johnny Walker,`nMy, but he was a talker!`nYet nary a word did he say!`nWhen I took him out,`nThen they would all point and shout!`nAnd ask that I put him away.', 'Твои мнения'),
    ('riddle_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', 'Их много и они одно,`nони машут и барабанят,`nими прикрывают взгляд,`nи они всюду с тобой.'),
    ('answer_text', 'They are many and one,`nThey wave and they drum,`nUsed to cover a stare,`nThey go with you everywhere.', 'Твои руки'),
    ('riddle_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', 'Топ-топ,`nхруп-хруп,`nскок-скок.`nСтоят на месте,`nво всей упряжи.'),
    ('answer_text', 'Stomp, stomp,`nChomp, chomp,`nRomp, romp.`nStanding still,`nall in gear.', 'Кони'),
    ('riddle_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', 'Сластёна,`nах ты ж,`nвсё вышло,`nа мы все жаждем`nещё кусочка.'),
    ('answer_text', 'Sweet tooth,`nAh shoot,`nAll gone,`nWe all long,`nFor another piece of it.', 'Конфеты'),
    ('riddle_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', 'Оно приходит на мягких кошачьих лапах,`nни кислое, ни сладкое.`nПовисит в воздухе,`nа потом его уже нет.'),
    ('answer_text', 'It comes in on little cat''s feet,`nIs neither sour, nor sweet.`nHovers in the air,`nAnd then is not there.', 'Туман'),
    ('riddle_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', 'Смех,`nплач,`nстон,`nвздох.'),
    ('answer_text', 'A laugh,`nA cry,`nA moan,`nA sigh.', 'Чувства'),
    ('riddle_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', 'Что это, на что ты должен ответить?`nНо чтобы ответить, надо спросить;`nа чтобы спросить, надо заговорить;`nа чтобы заговорить, надо знать`nответ.'),
    ('answer_text', 'What is it you have to answer?`nBut to answer you have to ask?`nAnd to ask you have to speak?`nAnd to speak you have to know,`nThe answer.', 'Загадка'),
    ('riddle_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', 'Я могу попасть тебе в глаз`nи мерцать в небесах,`nа умирая, расширяюсь.`nКак думаешь, что я такое?'),
    ('answer_text', 'I can hit you in the eye,`nYet twinkle in the sky,`nExpanding when I die,`nWhat do you think am I?', 'Звезда'),
    ('riddle_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', 'Хлюпает,`nчавкает,`nхочется отмыться,`nпопадает в волосы,`nи вид у меня незавидный.'),
    ('answer_text', 'Squishes,`nSquashes,`nWishes I washes,`nCan get it in my hair,`nMakes me not look too fair.', 'Грязь'),
    ('riddle_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', 'В гору,`nс горы,`nпо ним я могу бродить,`nно после всех скитаний`nнет места лучше собственного.'),
    ('answer_text', 'Up a hill,`nDown a hill,`nOver them I may roam,`nBut after all my walking,`nThere''s no place like my own.', 'Твой дом'),
    ('riddle_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', 'Это удивительнейшая вещь.`nОна может быть острой, как нож,`nили плоской, как пол.`nИ при всём том,`nона естественна, как пчела.'),
    ('answer_text', 'This thing is a most amazing thing.`nFor it can be both as sharp as a knife,`nOr as flat as a floor.`nAnd yet, for all that it can be,`nIt is as natural as a bee.', 'Музыка; ноты'),
    ('riddle_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', 'Глубоко, глубоко уходят они.`nРасходясь по мере продвижения.`nИм никогда не нужен воздух.`nПорой они тонки, как волос.'),
    ('answer_text', 'Deep, deep, do they go.`nSpreading out as they go.`nNever needing any air.`nThey are sometimes as fine as hair.', 'Корни'),
    ('riddle_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', 'О Господи! Я недостойна!`nЯ клоню ветви к земле.`nЯ плачу, но беззвучно.`nДай мне испить глубоких вод.`nИ в тишине я буду рыдать.'),
    ('answer_text', 'Oh Lord!  I am not worthy!`nI bend my limbs to the ground.`nI cry, yet without a sound.`nLet me drink of waters deep.`nAnd in silence I will weep.', 'Ива'),
    ('riddle_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', 'Смещаюсь, смещаюсь, ухожу вглубь.`nПодо мной спят великие и могучие города.`nКружусь, мечусь повсюду.`nЯ лишь там, где не найти воды.'),
    ('answer_text', 'Shifting, Shifting, Drifting deep.`nBelow me great and mighty cities sleep.`nSwirling, Scurlling, All around.`nI''m only where no water will be found.', 'Пустыня'),
    ('riddle_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', 'Я булькаю и смеюсь`nи плюю водой тебе в лицо.`nЯ не дама`nи кружев не ношу.'),
    ('answer_text', 'I bubble and laugh`nAnd spit water in your face.`nI am no lady,`nAnd I don''t wear lace.', 'Фонтан'),
    ('riddle_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', 'У чего есть крылья,`nно оно не летает?`nОно замкнуто,`nно может лежать и снаружи.`nМожет само раскрыться`nи само закрыться.`nЭто место королей и королев`nи всяческих виршей.`nЧто это, на чём я стою?`nОно способно вести нас в разные земли.'),
    ('answer_text', 'What has wings,`nBut can not fly.`nIs enclosed,`nBut can outside also lie.`nCan open itself up,`nOr close itself away.`nIs the place of kings and queens,`nAnd doggerel of every means.`nWhat is it upon which I stand?`nWhich can lead us to different lands.', 'Сцена'),
    ('riddle_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', 'Не ропщи на это,`nибо такова участь каждого.`nИ всё же этого боятся`nи избегают во многих землях.`nОно приносит беды, а порой и провалы,`nсбивает с ног сильнейших и путает память.`nЧто это за опасность, с которой мы все сталкиваемся`nлишь потому, что принадлежим к роду людскому?'),
    ('answer_text', 'Do not begrudge this,`nFor it is the fate of every man.`nYet it is feared,`nAnd shunned in many lands.`nCauses problems, and sometimes gaps,`nCan hobble the strongest, and make memory laps.`nWhat is this danger we all face?`nFor being a part - of the human race.', 'Старость; возраст'),
    ('riddle_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', 'Этих вещей у меня две.`nОдна мне — и одна тебе.`nА когда спрашивают о цене,`nя просто улыбаюсь и дважды киваю.'),
    ('answer_text', 'Of these things - I have two.`nOne for me - and one for you.`nAnd when you ask about the price,`nI simply smile and nod twice.', 'Умение делиться'),
    ('riddle_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', 'Я странное создание,`nпарящее в воздухе,`nперелетающее туда-сюда`nс ослепительным блеском.`nОдни говорят, что я пою,`nдругие — что у меня нет голоса.`nПоэтому я просто жужжу — по своему выбору.`nЧто я такое?'),
    ('answer_text', 'I am a strange creature,`nHovering in the air,`nMoving from here to there,`nWith a brilliant flare.`nSome say I sing,`nBut others say I have no voice.`nSo I just hum - as a matter of choice.`nWhat am I?', 'Колибри'),
    ('riddle_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', 'Днём я сплю,`nпрячусь.`nБодрствую всю ночь,`nа на рассвете раскрываюсь.`nНо лишь на краткий миг`nя сияю.`nА потом снова прячусь`nи сплю весь день.'),
    ('answer_text', 'Sleeping during the day,`nI hide away.`nWatchful through the night,`nI open at dawn''s light.`nBut only for the briefest time,`nDo I shine.`nAnd then I hide away,`nAnd sleep through the day.', 'Ипомея'),
    ('riddle_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', 'Похоже на воду,`nно это жар.`nСидит на песке,`nлежит на бетоне.`nГоворят, люди`nходят за ним повсюду.`nНо он никуда их не приводит,`nи остаётся лишь смотреть.'),
    ('answer_text', 'Looks like water,`nBut it''s heat.`nSits on sand,`nLays on concrete.`nPeople have been known,`nTo follow it everywhere.`nBut it gets them no place,`nAnd all they can do is stare.', 'Мираж'),
    ('riddle_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', 'Часть небес,`nхоть и касается земли.`nОдни говорят, что оно бесценно,`nдругие — что ничего не стоит.'),
    ('answer_text', 'A part of heaven,`nThough it touches the earth.`nSome say it''s valuable,`nOthers - no worth.', 'Радуга'),
    ('riddle_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', 'Я стою`nи смотрю через море,`nс его волнами, гребнями, впадинами и долинами.`nЯ шагаю`nчерез эту воду, мой конь следует за мной,`nи пока она плещет о его холку`nи задевает мои бёдра,`nя наполняю пустоту смехом.`nА он — вздохами.`nКуда же мы идём?`nИ идём ли вообще?`nИли просто бредём здесь по воде`nк следующей пристани?`nТам, где кончается море,`nгде под ногами твердеет суглинок,`nя снова сяду в седло`nи поеду дальше, до новой встречи.`nО чём на самом деле речь?'),
    ('answer_text', 'I stand,`nAnd look across the sea,`nWith its waves, crests, troughs, and valleys.`nI stride,`nAcross this water, my horse following after,`nAnd while it laps against his withers,`nAnd brushes against my thighs,`nI fill the emptiness with laughter.`nAnd he - with his sighs.`nWhether do we go?`nOr do we go at all?`nOr are we simply out here wading,`nTo the next port of call.`nWhere the sea ends,`nWhere the loam lays firm beneath my feet,`nAnd I can mount my steed again,`nAnd continue til next we meet.`nWhat is really being talked about?', 'Открытые равнины; равнина'),
    ('riddle_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', 'Я родился слепым`nи не мог видеть,`nпока не стало без четверти три.`nЯ не мог улыбаться`nдо половины седьмого,`nи все мои руки и ноги`nбыли из палочек.'),
    ('answer_text', 'I was born blind,`nAnd could not see,`nUntil it was a quarter of three.`nI could not smile,`nTil half past six,`nAnd all of my arms and legs`nWere made of sticks.', 'Кукла'),
    ('riddle_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', 'Ах! Дыхание моё дрожит,`nруки-ноги худы,`nживот болит.`nБелизна венчает мою голову,`nи следы, что я оставляю,`nневерны там, где я прошёл.`nЯ гляжу наружу мутными глазами`nи будто прощаюсь навсегда.`nТьма притягивает меня ближе,`nи я склоняюсь к ней — чтобы лучше слышать.'),
    ('answer_text', 'Ah!  My breath doth shake,`nMy limbs are thin,`nMy belly aches.`nWhiteness doth crown my head,`nAnd the tracks I leave,`nAre unsteady where I''ve led.`nI look out through rheumy eyes,`nAnd seem to say my last goodbyes.`nThe darkness doth draw me near,`nI lean towards it - the better to hear.', 'Старость; возраст'),
    ('riddle_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', 'Хика-мор, Хака-мор`nна королевской кухонной двери.`nВся королевская конница,`nвся королевская рать`nне смогли снять Хика-мора, Хака-мора`nс королевской кухонной двери.'),
    ('answer_text', 'Hick-a-more, Hack-a-more,`nOn the King''s kitchen door.`nAll the King''s horses,`nAnd all the King''s men,`nCouldn''t get Hick-a-more, Hack-a-more,`nOff the King''s kitchen door.', 'Солнечный свет'),
    ('riddle_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', 'Спросили меня, что из меня можно сделать, —`nи люди насытились мной.`nСпросили меня, что из меня можно сделать, —`nи были построены дома.`nСпросили меня, что из меня можно сделать, —`nи были написаны книги.`nСпросили меня, что из меня можно сделать, —`nи я удобрил землю.`nНо когда спросили, что ещё из меня можно сделать,`nне осталось ничего.'),
    ('answer_text', 'It was asked of me what I could be made,`nAnd so people were fed from me.`nIt was asked of me what I could be made,`nAnd so houses were built.`nIt was asked of me what I could be made,`nAnd so things were written.`nIt was asked of me what I could be made,`nAnd so I fertilized the ground.`nBut when asked more of what I could be made,`nThere was nothing to be found.', 'Дерево'),
    ('riddle_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', 'С этим можно творить чудеса.`nСмотреть на вещи вблизи или издалека,`nвидеть большое`nили видеть малое.`nА может, и вовсе ничего не видеть.`nЯ бываю разных цветов и оттенков,`nиногда зелёный, иногда голубой.`nА когда я красный — это не от стыда,`nа от чего-то, что зовётся иначе.'),
    ('answer_text', 'With this you can do wonderous things.`nLook at things close, or far away,`nYou can see things big,`nOr you can see things small.`nOr maybe you don''t see things at all.`nI come in many colors and hues,`nSometimes green and sometimes blue.`nAnd when I''m red - it''s not from shame,`nBut from something with a different name.', 'Твои глаза'),
    ('riddle_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', 'О, как я люблю свои танцующие ноги!`nОни держатся вместе — так славно.`nА когда я хочу пройти по прямой,`nвсе они идут вместе и вдвое быстрее.`nЯ пересчитываю их десять раз и больше`nи мчусь туда-сюда по полу.'),
    ('answer_text', 'Oh how I love my dancing feet!`nThey stay together - oh so neat.`nAnd when I want to walk a line,`nThey all stay together and do double time.`nI count them up, ten times or more,`nAnd race on-off, across the floor.', 'Сороконожка; многоножка'),
    ('riddle_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', 'Из загона донеслось глухое ворчание,`nи я, проходя мимо, остановился заглянуть.`nЧто же я увидел?`nОгромного зверя, с копытами и челюстями,`nс шипами на могучем челе;`nя смотрел, как он бьёт копытом дёрн и расхаживает.`nИ всё же при всём его великолепии`nон не мог выбраться за деревянную изгородь.'),
    ('answer_text', 'A muttered rumble was heard from the pen,`nAnd I, in my walking, stopped to look in.`nWhat was this I saw?`nA massive beast, hooved, and jawed.`nWith spikes upon its mighty brow,`nI watched as he struck the turf and prowled.`nAnd yet for all of his magnificience,`nHe couldn''t get out of that wooden fence.', 'Бык'),
    ('riddle_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', 'То была ночь того дня,`nо котором я должен поведать,`nтого, в чём сам участвовал.`nИбо солнце было на небе`nи безо всякого крика`nтихо ушло.`nЭто было так странно —`nя думал, оно глянет искоса,`nно и слова вставить не удалось.`nИ снова ни слова`n(по крайней мере, я ничего не слышал) —`nи оно вернулось туда, где было.'),
    ('answer_text', 'Twas the night of the day`nin which I must relay`nthat in which I took part in.`nFor the sun was out`nand without so much as a shout`nhe quietly went in.`nTwas ever so queer`nI thought he would leer`nbut never a word did I get in.`nFor without another word`n(at least that''s what I heard)`nHe was back to the place he''d been in.', 'Затмение'),
    ('riddle_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', 'От восхода до заката я гляжу вдаль через море.`nОт заката до восхода я гляжу вдаль через море.`nНо при солнце я лишь моргаю от яркости.`nА когда солнце сядет, я выморгиваю яркость наружу.'),
    ('answer_text', 'From sun up to sun down I stare out across the sea.`nFrom sun down to sun up I stare out across the sea.`nBut while with sun up I can only blink in the brightness.`nWith the sun down I can blink out the brightness.', 'Маяк'),
    ('riddle_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', 'Много лая (коры),`nно никто не замечает.`nМного укусов,`nи всем есть до этого дело.`nЯ не собака,`nесли кто-то заметит.`nВо мне много всего,`nно нет волос.`nЯ стою прямо,`nесли ты меня приметил.`nУ меня много конечностей,`nесли кому-то есть дело.`nЯ могу дать тебе тень,`nесли ты это заметил.`nИ делаю даже больше:`nя даю тебе воздух.'),
    ('answer_text', 'A lot of bark,`nBut no one notices.`nA lot to bite,`nAnd everyone cares.`nI''m not a dog,`nIf anyone notices.`nAnd there''s a lot to me,`nBut I don''t have hair.`nI stand up straight,`nIf you''ve noticed me.`nI''ve got lots of limbs,`nIf anyone cares.`nI can give you shade,`nIf you''ve noticed it.`nAnd I do even more,`nI give you air.', 'Дерево'),
    ('riddle_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', 'Было ли то в декабре или в июне,`nкогда моя госпожа лишилась чувств.`nКогда её волосы упали,`nа очки потерялись.`nКогда она завизжала`nсамым непристойным образом.`nУказывая на меня`nи вопя: «И-и-и! И-и-и!»`nДолжен сказать, это было чересчур,`nведь я никого и не тронул.`nНо было совершенно ясно,`nчто что-то не так.`nПоэтому я решил зайти в другой день,`nкогда её, быть может, не будет дома.'),
    ('answer_text', 'Twas in December or June,`nWhen my lady did swoon.`nWhen her hair did fall off,`nAnd her glasses were lost.`nWhen she did scream,`nIn a manner most obscene.`nWhile pointing at me,`nAnd saying 봂eeeee!  Eeeeee!?nI must say it was all a bit much,`nSince no one did I touch.`nBut it was quite apparent,`nThat something was errant.`nSo I decided to come back another day,`nWhen, mayhap, she was away.', 'Мышь'),
    ('riddle_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', 'Я плыву,`nмедленно, как ленивая река.`nЯ танцую`nна одном лишь дуновении ветра.`nЯ кувыркаюсь`nлучше величайшего акробата.`nКружась,`nвертясь,`nопускаюсь на землю.`nТам я и лежу,`nпока не поймаю второе дыхание.`nЧтобы начать всё сначала.'),
    ('answer_text', 'I drift,`nAs slowly as a lazy river.`nI dance,`nUpon as little as a puff of air.`nI tumble,`nBetter than the greatest acrobat.`nSwirling,`nTwirling,`nDown to the ground.`nWhere I lie,`nTil I get my second wind.`nSo I can begin again.', 'Лист'),
    ('riddle_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', 'Загадка, что решается легко.`nКрасногрудый.`nЛишь один среди множества.`nРождён из яйца.`nВдохновлён петь.`nТеперь собери буквы и скажи, что я значу.'),
    ('answer_text', 'A riddle, easily solved.`nRed breasted.`nOnly one in a field of many.`nBorn in an egg.`nInspired to sing.`nNow gather the letters and tell me what I mean.', 'Малиновка'),
    ('riddle_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', 'У меня их четыре,`nи на каждой — по набору отростков.`nОни умеют многое`nи почти никогда не причиняют мне боли.`nРазве что я уколю их булавкой`nили порой обожгу...`nЧто это, чем я могу шевелить по своей воле`nи использовать ещё как-нибудь?'),
    ('answer_text', 'I have four of these,`nWith matching extremities.`nThey can do many things,`nAnd hardly ever bring me pain.`nUnless I stick them with a pin,`nOr burn them sometimes when...`nWhat is it that I can wiggle at will?`nAnd use in other means still?', 'Пальцы'),
    ('riddle_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', 'Когда я взглянул на пламя его страсти`nи на прохладу её прикосновения,`nя понял, что из их союза выйдет лишь трагедия.`nИ верно, когда они сошлись,`nтьма воцарилась над землёй.`nИ хотя вскоре их разлучили,`nи они поняли, что не созданы друг для друга,`nвсё же мимолётные взгляды, которыми они обменялись,`nоставили след на всех, кто это видел,`nи будут обсуждаться ещё многие века.'),
    ('answer_text', 'When I looked upon the flames of his passion,`nAnd the coolness of her touch,`nI knew tragedy could only come from their union.`nAnd indeed, when they came together,`nDarkness reigned upon the land.`nAnd although they were soon separated,`nLearning as they did that they were not for each other,`nStill, their passing regards for each other,`nLeft it''s impression upon all who had witnessed it.`nAnd would be talked about for ages still to come.', 'Солнечное затмение; затмение'),
    ('riddle_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', 'У кого есть шуба?`nКто обнимает вовсе не из сочувствия?`nЧью улыбку лучше не видеть?`nЧья стойка ужасна на вид?`nОт кого бегут храбрецы?`nУ кого пальцы с когтями?`nЧей сон длится месяцами?`nИ чьего общества мы избегаем?'),
    ('answer_text', 'What has a coat?`nHugs you not in sympathy?`nWhose smile you''d rather not see?`nWhose stance is a terrible thing to see?`nWho is it that brave men run away from?`nWhose fingers are clawed?`nWhose sleep lasts for months?`nAnd whose company we shun?', 'Медведь'),
    ('riddle_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', 'На этом можно кувыркаться,`nваляться,`nэто можно жечь,`nживотные это едят,`nим устилают полы`nи по сей день используют за дверями стойл.`nОно освежает всё, на что его кладут,`nи впитывает всё, что на него льют.`nЧто это?'),
    ('answer_text', 'You can tumble in it,`nRoll in it,`nBurn it,`nAnimals eat it,`nUsed to cover floors,`nStill used beyond stall doors.`nFreshens whatever it is placed on,`nAbsorbs whatever is poured into it.`nWhat is it?', 'Сено'),
    ('riddle_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', 'В плоде страсти их можно найти,`nа в короне граната их ещё больше.`nОни рядами лежат в сердцевине яблока,`nа в других плодах их и того больше.`nИ хотя у нектарина он всего один,`nвсё это лишь забава.`nПрятки — детская игра.`nА найдёшь — и окажется, что все игроки одинаковы.'),
    ('answer_text', 'Within passion''s fruit they will be found,`nAnd more of them in the pomegranate''s crown.`nRowed they are within an apple''s core,`nYet other fruits have them more.`nAnd though the nectarine has but one,`nStill, this is all just in fun.`nPlaying hide and seek - a children''s game.`nFinding out each player is just the same.', 'Семена'),
    ('riddle_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', 'Это шептали на небесах, бормотали в аду,`nи эхо слабо ловило звук, пока он падал;`nна краю земли ему дозволили отдохнуть,`nи в глубинах океана обнаружилось его присутствие;`nего найдут в небесной сфере, когда она расколется,`nувидят в молнии и услышат в громе;`nоно даровано человеку с первым его вздохом,`nсопровождает его при рождении и ждёт при смерти,`nправит его счастьем, честью и здоровьем,`nоно — опора его дома и предел его богатства.`nВ грудах скупца оно копится с заботой,`nно непременно теряется у расточительного наследника;`nоно начинает всякую надежду и ограничивает всякое желание,`nтрудится с землепашцем и венчается с монархами;`nбез него солдат и моряк могут скитаться,`nно горе несчастному, кто изгонит его из дома!`nВ шёпоте совести отыщется его голос,`nи никогда не потонет он в вихре страстей;`nоно смягчит сердце; и пусть ухо глухо,`nоно заставит услышать остро и мгновенно.`nПомести его в тень, дай ему покоиться, как нежному цветку;`nах! дыши на него мягко — за час оно умрёт'),
    ('answer_text', '''Twas whispered in Heaven, ''twas muttered in hell,`nAnd echo caught faintly the sound as it fell;`nOn the confines of earth ''twas permitted to rest,`nAnd in the depths of the ocean its presence confes''d;`n''Twill be found in the sphere when ''tis riven asunder,`nBe seen in the lightning and heard in the thunder;`n''Twas allotted to man with his earliest breath,`nAttends him at birth and awaits him at death,`nPresides o''er his happiness, honor and health,`nIs the prop of his house, and the end of his wealth.`nIn the heaps of the miser ''tis hoarded with care,`nBut is sure to be lost on his prodigal heir;`nIt begins every hope, every wish it must bound,`nWith the husbandman toils, and with monarchs is crowned;`nWithout it the soldier and seaman may roam,`nBut woe to the wretch who expels it from home!`nIn the whispers of conscience its voice will be found,`nNor e''er in the whirlwind of passion be drowned;`n''Twill soften the heart; but though deaf be the ear,`nIt will make him acutely and instantly hear.`nSet in shade, let it rest like a delicate flower;`nAh!  Breathe on it softly, it dies in an hour', 'Буква «H»; H'),
    ('riddle_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', 'Мы — маленькие воздушные создания,`nу каждого свой голос и облик;`nодин из нас стоит в стекле (glass),`nдругого найдёшь в гагате (jet),`nтретьего увидишь в олове (tin),`nа четвёртый — внутри коробки (box);`nа если погонишься за пятым,`nон никогда от тебя не улетит.'),
    ('answer_text', 'We are little airy creatures,`nAll of different voice and features;`nOne of us in glass is set,`nOne of us you''ll find in jet,`nT''other you may see in tin,`nAnd the fourth a box within;`nIf the fifth you should pursue,`nIt can never fly from you.', 'Гласные'),
    ('riddle_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', 'Я странное противоречие; я новое и я старое,`nчасто в лохмотьях и часто в золоте.`nЯ никогда не умело читать, но всё в буквах;`nслепое, я просвещаю; несвязанное, я переплетено.`nЯ всегда в чёрном и всегда в белом;`nя серьёзно и я весело, я тяжело и легко —`nи формой я разное: я толстое и я тонкое,`nво мне нет ни плоти, ни костей, но я покрыто кожей;`nво мне больше точек, чем в компасе, больше пауз, чем во флейте;`nя пою без голоса, опровергаю без слов.`nЯ английское, я немецкое, я французское и я голландское;`nодни любят меня слишком нежно, другие слишком пренебрегают;`nя часто умираю рано, хоть иногда живу века,`nи ни у одного из живущих монархов нет столько пажей (страниц).'),
    ('answer_text', 'I''m a strange contradiction; I''m new, and I''m old,`nI''m often in tatters, and oft decked with gold.`nThough I never could read, yet lettered I''m found;`nThough blind, I enlighten; though loose, I am bound,`nI''m always in black, and I''m always in white;`nI''m grave and I''m gay, I am heavey and light-`nIn form too I differ - I''m thick and I''m thin,`nI''ve no flesh and bones, yet I''m covered with skin;`nI''ve more points than the compass, more stops than the flute;`nI sing without voice, without speaking confute.`nI''m English, I''m German, I''m French, and I''m Dutch;`nSome love me too fondly, some slight me too much;`nI often die soon, though I sometimes live ages,`nAnd no monarch alive has so many pages.', 'Книга'),
    ('riddle_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', 'Когда я шёл через садовый проём,`nкого я встретил, как не Дика Красную Шапку!`nПалка в руке, камень в горле.`nОтгадаешь эту загадку — дам тебе грош.'),
    ('answer_text', 'As I went through the garden gap,`nWho should I meet but Dick Red-cap!`nA stick in his hand, a stone in his throat,`nIf you''ll tell me this riddle, I''ll give you a groat.', 'Вишня'),
    ('riddle_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', 'Малышка Нэнси Эттикот`nв белой нижней юбке,`nс красным носом;`nчем дольше она стоит,`nтем ниже становится.'),
    ('answer_text', 'Little Nancy Etticote,`nIn a white petticoat,`nWith a red nose;`nThe longer she stands`nThe shorter she grows.', 'Свеча'),
    ('riddle_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', 'У меня есть сестрёнка, её зовут Пип-Пип;`nона переходит вброд глубокие-глубокие воды;`nона взбирается на высокие-высокие горы;`nбедняжка, у неё всего один глаз.'),
    ('answer_text', 'I have a little sister, they call her Peep, Peep;`nShe wades the waters deep, deep, deep;`nShe climbs the mountains high, high, high;`nPoor little creature she has but one eye.', 'Звезда'),
    ('riddle_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', 'Я видел, как шло войско,`nшло через море.`nИ, глядя на них,`nя спросил себя: «Что бы это могло быть?»`nИбо там был конь,`nи была корова,`nи шли люди`nс домами и деревьями. Но как?`nЯ видел, как шло войско,`nшло через море.`nИ дивился, отдыхая,`nдо чего же я ленив.'),
    ('answer_text', 'I saw a company a marching,`nA marching across the sea.`nAnd looking upon them,`nI asked myself 봚hat can they be??nFor there was a horse,`nAnd there was a cow,`nAnd there were men marching,`nWith houses and trees.  But how?`nI saw a company marching,`nA marching across the sea.`nAnd wondered in my rest,`nHow lazy I must be.', 'Облака в небе; облака'),
    ('riddle_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', 'Я вверху.`nЯ внизу.`nЯ повсюду.`nИ всё же меня не найти.`nКто я?'),
    ('answer_text', 'I''m up.`nI''m down.`nI''m all around.`nYet never can I be found.`nWho am I?', 'Ветер'),
    ('riddle_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', 'Меня можно передвинуть.`nМеня можно катить.`nНо я ничего не удержу.`nЯ красный и я синий.`nИ могу быть других цветов.`nГоловы нет, хоть форма похожа,`nглаз нет — а качусь повсюду.`nЧто я такое?'),
    ('answer_text', 'I can be moved.`nI can be rolled.`nBut nothing will I hold.`nI''m red and I''m blue.`nAnd I can be other colors too.`nHaving no head, though similar in shape,`nI have no eyes - yet move all over the place.`nWhat am I?', 'Мяч'),
    ('riddle_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', 'По мне можно ступать,`nтихонько, под покровом.`nИ я отведу тебя туда,`nчего ты ещё не открыл.`nЯ высоко и я низко,`nа посередине плоско.`nИ хоть я радость для детей,`nвзрослые обо мне почти не думают.`nЧто я такое?'),
    ('answer_text', 'Upon me you can tread,`nThough softly under cover.`nAnd I will take you places,`nThat you have yet to discover.`nI''m high, and I''m low,`nThough flat in the middle.`nAnd though a joy to the children,`nAdults think of me little.`nWhat am I?', 'Лестница'),
    ('riddle_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', 'Что созидает?`nСрывает горы?`nОсушает озёра`nи заставляет всё расти?`nЧто ничуть не заботится о твоём уходе?`nИ мало на что похоже,`nпотому что оно вечно?'),
    ('answer_text', 'What is it which builds things up?`nLays mountains low?`nDries up lakes,`nAnd makes things grow?`nCares not a whim about your passing?`nAnd is like few other things,`nBecause it is everlasting?', 'Время'),
    ('riddle_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', 'Оно сидело на иве`nи тихо пело мне.`nОблегчая песней мою боль и печаль,`nя хотел взлететь, но задержался надолго.`nИ в моём страдании`nива была как прохладный чистый родник.`nЧто же так мне помогло?`nЧто скрасило часы моей тоски.'),
    ('answer_text', 'It sat upon a willow tree,`nAnd sang softly unto me.`nEasing my pain and sorrow with its song,`nI wished to fly, but tarried long.`nAnd in my suffering,`nThe willow was like a cool clear spring.`nWhat was it that helped me so?`nTo spend my time in my woe.', 'Птица'),
    ('riddle_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', 'Их можно затаить, но воду они держат редко;`nих можно вынашивать, но лишь держа против кого-то;`nих можно носить, но не в руках;`nих можно похоронить, но не в земле.'),
    ('answer_text', 'They can be harbored, but few hold water,`nYou can nurse them, but only by holding them against someone else,`nYou can carry them, but not with your arms,`nYou can bury them, but not in the earth.', 'Обида'),
    ('riddle_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', 'Глубока, как чаша, кругла, как кубок,`nи всё же все океаны мира её не наполнят.'),
    ('answer_text', 'Deep as a bowl, round as a cup,`nYet all the world''s oceans can''t fill it up.', 'Решето; дуршлаг'),
    ('riddle_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', 'Хоть люди пустыни когда-то звали меня богом,`nсегодня меня зовут безумцем,`nибо я виляю хвостом, когда сержусь,`nи ворчу, когда рад.'),
    ('answer_text', 'Though desert men once called me God,`nTo-day men call me mad,`nFor I wag my tail when I am angry,`nAnd growl when I am glad.', 'Кошка'),
    ('riddle_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', 'Я слышал о вторгшемся, всепобеждающем войске,`nчто неслось по земле, быстрое, как вода;`nпокоряя всё, подавляя сопротивление.`nС ним пришла тьма, затмившая свет.`nЛюди прятались в домах, а снаружи`nкопья вонзались, круша каменные стены.`nБесчисленные воины разбивались о землю,`nно каждый, умирая, вызывал жизнь;`nа когда войско исчезло, двинувшись на север,`nземля зазеленела и ожила, обновлённая.'),
    ('answer_text', 'I heard of an invading, vanquishing army`nsweeping across the land, liquid-quick;`nconquering everything, quelling resistance.`nWith it came darkness, dimming the light.`nHumans hid in their houses, while outside`nspears pierced, shattering stone walls.`nUncountable soldiers smashed into the ground,`nbut each elicited life as he died;`nwhen the army had vanished, advancing northward,`nthe land was green and growing, refreshed.', 'Ливень; дождь'),
    ('riddle_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', '«Я могу найти то, чего не вижу, и увидеть то, чего не найду.`nПервое — время, второе — пятнышко перед глазами».'),
    ('answer_text', '봊 can find a thing I cannot see and see a thing I cannot find.`nThe first is time, the second is a spot before my eyes.', 'Время'),
    ('riddle_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', 'Я могу чувствовать то, чего не могу коснуться, и коснуться того, чего не чувствую.`nПервое — печально и горько, второе — твоё сердце.'),
    ('answer_text', 'I can feel a thing I cannot touch and touch a thing I cannot feel.`nThe first is sad and sorry, the second is your heart.', 'Твоё сердце'),
    ('riddle_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', 'Никогда впереди, всегда позади,`nи всё же стремительно проносится мимо;`nдля ребёнка я длюсь вечно,`nдля взрослых я исчезаю слишком быстро.'),
    ('answer_text', 'Never ahead, ever behind,`nYet flying swiftly past,`nFor a child, I last forever,`nFor adults, I''m gone too fast.', 'Молодость'),
    ('riddle_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', 'Она высока и кругла, как чаша,`nи всё же вся королевская конница`nне вытащит её наверх.'),
    ('answer_text', 'Tall she is, and round as a cup,`nYet all the king''s horses`nCan''t draw her up.', 'Колодец'),
    ('riddle_text', 'There more of it there is,`nThe less you see.', 'Чем больше его,`nтем меньше ты видишь.'),
    ('answer_text', 'There more of it there is,`nThe less you see.', 'Темнота'),
    ('riddle_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', 'Что мало для одного,`nв самый раз для двоих`nи слишком много для троих?'),
    ('answer_text', 'What is not enough for one,`nJust right for two,`nToo much for three?', 'Тайна'),
    ('riddle_text', 'What gets wetter the more it dries?', 'Что становится мокрее, чем больше сушит?'),
    ('answer_text', 'What gets wetter the more it dries?', 'Полотенце'),
    ('riddle_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', 'Длинная змея`nс жалящим укусом,`nя лежу свёрнутой,`nесли только не придётся драться.'),
    ('answer_text', 'A long snake`nWith a stinging bite,`nI stay coiled up`nUnless I must fight.', 'Кнут'),
    ('riddle_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', 'Воин среди цветов,`nон носит колющий меч.`nСпособный и готовый пустить его в ход,`nчтобы стеречь свою золотую казну.'),
    ('answer_text', 'A warrior amongst the flowers,`nHe bears a thrusting sword.`nAble and ready to use,`nTo guard his golden hoard.', 'Пчёлы'),
    ('riddle_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', 'Несущий груз, Воин,`nИспуганный, Храбрый,`nБыстроногий, Подкованный,`nВерный, Раб.'),
    ('answer_text', 'The Load-bearer, the Warrior,`nThe Frightened One, the Brave,`nThe Fleet-of-foot, the Ironshod`nThe Faithful One, the Slave', 'Конь'),
    ('riddle_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', 'Ходит в ветре,`nбежит в дожде,`nсоздаёт сухие океаны под солнцем.`nОтсчитывает время, останавливает часы,`nпоглощает королевства, точит камни.'),
    ('answer_text', 'Walks in the wind`nRuns in the rain`nMakes dry oceans in the sun`nCounts time, stops clocks`nSwallows kingdoms, gnaws rocks.', 'Песок'),
    ('riddle_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', 'Катящиеся холмы, сердце, что бьётся вечно,`nземля, что никогда не меняется и не замирает,`nвспахана путниками вдали от дома, но не засеяна,`nбелая во гневе, зелёная в покое и всегда синяя.'),
    ('answer_text', 'The rolling hills, the heart that beats forever,`nThe land that never changes, never stills`nPloughed by travellers far from home, not planted,`nWhite in anger, green in peace, and always blue.', 'Море; океан'),
    ('riddle_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', 'Слушай внимательно, меня трудно понять,`nя неуловима, как горсть песка.`nДаже уловив меня, ты меня не знаешь,`nпока не скажешь, что же я позабыла.'),
    ('answer_text', 'Listen closely, I''m hard to understand`nI am as elusive as is a handful of sand.`nEven if you perceive me, you know me not`nbefore you can tell me, what I have forgot.', 'Загадка'),
    ('riddle_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', 'Что проходит в дверь, не защемив себя?`nЧто сидит на печи, не обжигаясь?`nЧто сидит на столе и не стыдится?'),
    ('answer_text', 'What goes through the door without pinching itself?`nWhat sits on the stove without burning itself?`nWhat sits on the table and is not ashamed?', 'Солнце'),
    ('riddle_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', 'Пока я сидел,`nя увидел, как мёртвое несёт живое.`nЧто я видел?'),
    ('answer_text', 'Whilst I was engaged in sitting`nI spied the dead carrying the living`nWhat did I see?', 'Корабль'),
    ('riddle_text', 'I know a word of letters three,`nAdd two and fewer there will be.', 'Я знаю слово из трёх букв,`nприбавь ещё две — и станет меньше.'),
    ('answer_text', 'I know a word of letters three,`nAdd two and fewer there will be.', 'Мало'),
    ('riddle_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', 'Кто это делает — тому оно не нужно.`nКто покупает — тому оно ни к чему.`nА кто им пользуется — тот его не видит и не чувствует.'),
    ('answer_text', 'Who makes it, has no need of it.`nWho buys it, has no use for it.`nWho uses it, can neither see nor feel it.', 'Гроб'),
    ('riddle_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', 'Тому, кто это сделал, оно было не нужно.`nТот, кто это купил, им не пользовался.`nТот, кто им воспользовался, его не хотел.'),
    ('answer_text', 'The man who made it didn''t need it.`nThe man who bought it didn''t use it.`nThe man who used it didn''t want it.', 'Гроб'),
    ('riddle_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', 'Ты схватил меня, а я всё же ускользнул.`nТы видишь, как я убегаю, и не можешь удержать.`nСожмёшь меня в руке — и кулак пуст.`nЧто я такое?'),
    ('answer_text', 'You seized me, and yet I fled`nYou see me flee and cannot hold me tight`nYou press me in your hand, then your fist is empty.`nWhat am I?', 'Снег'),
    ('riddle_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', 'Что утром на четырёх ногах,`nднём на двух,`nа вечером на трёх?'),
    ('answer_text', 'What has four legs in the morning,`nTwo legs in the afternoon,`nAnd three legs in the evening?', 'Человек'),
    ('riddle_text', 'What is deaf, dumb and blind`nand always tells the truth ?', 'Что глухо, немо и слепо,`nа всегда говорит правду?'),
    ('answer_text', 'What is deaf, dumb and blind`nand always tells the truth ?', 'Зеркало'),
    ('riddle_text', 'What is always in front of you`nbut cannot be seen?', 'Что всегда перед тобой,`nно его не увидеть?'),
    ('answer_text', 'What is always in front of you`nbut cannot be seen?', 'Будущее'),
    ('riddle_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', 'Что человек любит больше жизни,`nненавидит больше смерти и смертельной вражды;`nчего желают довольные,`nчто есть у бедных и в чём нуждаются богатые;`nчто тратит скупец и копит мот,`nи что все уносят с собой в могилу?'),
    ('answer_text', 'What does man love more than life,`nhate more than death or mortal strife;`nThat which contented men desire,`nthe poor have, the rich require;`nThe miser spends, the spendthrift saves,`nand all men carry to their graves?', 'Ничто'),
    ('riddle_text', 'A life longer than any man,`nit dies each year to be reborn.', 'Жизнь дольше любой человеческой:`nоно умирает каждый год, чтобы родиться вновь.'),
    ('answer_text', 'A life longer than any man,`nit dies each year to be reborn.', 'Дерево'),
    ('riddle_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', 'В глазах оно вызывает слепоту,`nв носу — всего лишь чих;`nи всё же иные втягивают это в себя`nи делают вид, что довольны.'),
    ('answer_text', 'In the eyes it causes blindness,`nin the nose just a sneeze;`nYet some suck this down,`nand act as if pleased.', 'Дым'),
    ('riddle_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', 'Оно стоит само по себе, без костей и твёрдой формы.`nНепреклонное, оно никогда не бывает неправым,`nхотя может ранить.`nЕго можно крутить и мять,`nно оно всегда прямо, как стрела.'),
    ('answer_text', 'It stands alone, with no bone or solid form.`nAdamant, it prospers never wrong,`nthough hurt it may.`nTwistable, malleable, might it be,`nbut always straight as an arrow.', 'Правда'),
    ('riddle_text', 'What sphinxes employ,`nthe players enjoy.', 'То, чем пользуются сфинксы,`nи то, чем наслаждаются игроки.'),
    ('answer_text', 'What sphinxes employ,`nthe players enjoy.', 'Загадка'),
    ('riddle_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', 'Есть тот, к кому я всегда близко,`nно во тьме я исчезаю.`nЛишь ему одному я верен,`nхотя обречён трудиться в его тени.`nОн меня не чувствует (а мы всегда соприкасаемся);`nесли бы я пропал, он потерял бы немного.`nИ вот я подхожу к неожиданному:`nведь он — это ты, так кто же я?'),
    ('answer_text', 'There''s someone that I''m always near,`nYet in the dark I disappear.`nTo this one only I am loyal,`nThough in his wake I''m doomed to toil.`nHe feels me not (we always touch);`nIf I were lost, he''d not lose much.`nAnd now I come to my surprise,`nFor you are he - but who am I ?', 'Твоя тень'),
    ('riddle_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', 'Меня часто держат, но редко трогают;`nя всегда влажен, но никогда не ржавею;`nменя то треплют, то прикусывают;`nчтобы пользоваться мной умело, нужен ум.'),
    ('answer_text', 'I''m often held, yet rarely touched;`nI''m always wet, yet never rust;`nI''m sometimes wagged and sometimes bit;`nTo use me well, you must have wit.', 'Язык'),
    ('riddle_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', 'Она сидела у окна и плакала.`nИ с каждой слезой из неё утекала жизнь.'),
    ('answer_text', 'In the window she sat weeping.`nAnd with each tear her life went seeping.', 'Свеча'),
    ('riddle_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', 'На самом деле я не более чем дырки, связанные`nс другими дырками;`nя крепок, как добрая сталь, хоть и не так жёсток,`nкак шест.'),
    ('answer_text', 'I''m not really more than holes tied to more`nholes;`nI''m strong as good steel, though not as stiff`nas a pole.', 'Цепь'),
    ('riddle_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', 'Сил у меня мало, но власть велика;`nя стерегу и малые лачуги, и великие башни.`nНо если случится хозяину уйти,`nон должен позаботиться о моей сохранности.'),
    ('answer_text', 'I''ve little strength, but mighty powers;`nI guard small hovels and great towers.`nBut if perchance my master leaves,`nHe must ensure he safeguards me.', 'Ключ'),
    ('riddle_text', 'Delivered by breath,`nscares heroes to death.', 'Доставляется дыханием,`nпугает героев до смерти.'),
    ('answer_text', 'Delivered by breath,`nscares heroes to death.', 'Загадка'),
    ('riddle_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', 'Днём я растекаюсь лужами,`nночью укрываю, как туман.`nЯ пробираюсь в закрытые ящики`nи в твой сжатый кулак.`nЛучше всего ты видишь меня, когда не видишь,`nибо меня не существует.'),
    ('answer_text', 'In daytime I lie pooled about,`nAt night I cloak like a mist.`nI creep inside shut boxes and`nInside your tightened fist.`nYou see me best when you can''t see,`nFor I do not exist.', 'Темнота'),
    ('riddle_text', 'Devils and rogues know nothing else,`nsave starlight.', 'Дьяволы и негодяи не знают ничего иного,`nкроме звёздного света.'),
    ('answer_text', 'Devils and rogues know nothing else,`nsave starlight.', 'Темнота'),
    ('riddle_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', 'И у короля, и у коня это есть, конечно,`nно тебе не захочется ни того, ни другого.'),
    ('answer_text', 'Both king and horse have this, of course,`nBut you''ll want neither of them, perforce.', 'Правление; поводья'),
    ('riddle_text', 'My spring up on the cliff.', 'Мой источник на утёсе.'),
    ('answer_text', 'My spring up on the cliff.', 'Кокос'),
    ('riddle_text', 'Three walls and you reach water.', 'Три стены — и ты достигнешь воды.'),
    ('answer_text', 'Three walls and you reach water.', 'Кокос'),
    ('riddle_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', 'Моё бревно капа (род ткани),`nчто звучит без устали.'),
    ('answer_text', 'My kapa (a type of cloth) log that`nis always sounding without rest.', 'Море'),
    ('riddle_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', 'Утром четыре ноги,`nв полдень две ноги,`nвечером три ноги.'),
    ('answer_text', 'In the morning four legs,`nat noon two legs,`nat evening three legs.', 'Человек'),
    ('riddle_text', 'My man that cannot be cut.', 'Мой человек, которого не разрубить.'),
    ('answer_text', 'My man that cannot be cut.', 'Тень'),
    ('riddle_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', 'Мои каноэ, идущие днём и ночью,`nдесять носов, две кормы.'),
    ('answer_text', 'My canoes, going day and night,`nten bowspirits, two sterns.', 'Чьи-то ступни'),
    ('riddle_text', 'My red cave, white soldiers standing in line.', 'Моя красная пещера, белые воины стоят в ряд.'),
    ('answer_text', 'My red cave, white soldiers standing in line.', 'Чей-то рот'),
    ('riddle_text', 'My man crying day and night,`nall through the year.', 'Мой человек, что плачет день и ночь,`nвесь год напролёт.'),
    ('answer_text', 'My man crying day and night,`nall through the year.', 'Море')
  ) AS source
  JOIN riddle ON riddle.riddle_text = source.column2;

-- =============================================================================
-- 0017_seed_default_equipment_label.sql
-- character-stat 네임스페이스에 기본 장비 이름 라벨 2개와 5개 언어 번역을 적재한다.
-- 선행: 0001_seed_character_stat_label.sql (동일 네임스페이스의 label_key 27개)
-- 대응: src/i18n/locale/<code>/character-stat.json 의 equipment.bare-hand /
--       equipment.plain-shirt 와 키·값이 일치해야 한다.
-- 근거: database/migration/0001_create_schema.sql 의 character_equipment 정의 —
--       weapon_name TEXT NOT NULL DEFAULT 'Fists',
--       armor_name  TEXT NOT NULL DEFAULT 'T-Shirt'.
--       두 값은 weapon / armor 카탈로그에 없는 미장착 상태의 표시 문자열이므로
--       catalog_translation 이 아니라 라벨로 번역한다.
-- =============================================================================

INSERT OR IGNORE INTO label_key (namespace_code, label_path, source_reference, placeholder_json)
VALUES
    ('character-stat', 'equipment.bare-hand',   'database/migration/0001_create_schema.sql character_equipment.weapon_name DEFAULT', '[]'),
    ('character-stat', 'equipment.plain-shirt', 'database/migration/0001_create_schema.sql character_equipment.armor_name DEFAULT',  '[]');

INSERT OR REPLACE INTO label_translation (label_key_id, locale_code, translation_text)
SELECT label_key.label_key_id, translation_source.locale_code, translation_source.translation_text
  FROM (
        SELECT 'equipment.bare-hand'   AS label_path, 'en' AS locale_code, 'Fists' AS translation_text
  UNION ALL SELECT 'equipment.plain-shirt', 'en', 'T-Shirt'
  UNION ALL SELECT 'equipment.bare-hand',   'ko', '맨주먹'
  UNION ALL SELECT 'equipment.plain-shirt', 'ko', '티셔츠'
  UNION ALL SELECT 'equipment.bare-hand',   'ja', '素手'
  UNION ALL SELECT 'equipment.plain-shirt', 'ja', 'Tシャツ'
  UNION ALL SELECT 'equipment.bare-hand',   'zh', '赤手空拳'
  UNION ALL SELECT 'equipment.plain-shirt', 'zh', 'T恤'
  UNION ALL SELECT 'equipment.bare-hand',   'ru', 'Кулаки'
  UNION ALL SELECT 'equipment.plain-shirt', 'ru', 'Футболка'
       ) AS translation_source
  JOIN label_key
    ON label_key.namespace_code = 'character-stat'
   AND label_key.label_path     = translation_source.label_path;
